  'No offline mentor available right now.' => 'ಸದ್ಯಕ್ಕೆ ಯಾವುದೇ ಆಫ್‌ಲೈನ್ ಮಾರ್ಗದರ್ಶಕರು ಲಭ್ಯವಿಲ್ಲ.',
  'We will email you as soon as a mentor for your skills joins.' => 'ನಿಮ್ಮ ಕೌಶಲ್ಯಗಳಿಗೆ ಮಾರ್ಗದರ್ಶಕರು ಸೇರಿದ ತಕ್ಷಣ ನಾವು ನಿಮಗೆ ಇಮೇಲ್ ಮಾಡುತ್ತೇವೆ.',
  'Mentor Request' => 'ಮಾರ್ಗದರ್ಶಕರ ವಿನಂತಿ',
  'This link is not valid.' => 'ಈ ಲಿಂಕ್ ಮಾನ್ಯವಾಗಿಲ್ಲ.',
  'Thank you! You accepted this candidate. We have sent them your details and the Jobsence team will contact you to fix the class schedule.' => 'ಧನ್ಯವಾದಗಳು! ನೀವು ಈ ಅಭ್ಯರ್ಥಿಯನ್ನು ಸ್ವೀಕರಿಸಿದ್ದೀರಿ. ನಿಮ್ಮ ವಿವರಗಳನ್ನು ಅವರಿಗೆ ಕಳುಹಿಸಿದ್ದೇವೆ ಮತ್ತು ತರಗತಿಯ ವೇಳಾಪಟ್ಟಿ ನಿಗದಿಪಡಿಸಲು Jobsence ತಂಡ ನಿಮ್ಮನ್ನು ಸಂಪರ್ಕಿಸುತ್ತದೆ.',
  'Okay – we have offered the candidate other mentors.' => 'ಸರಿ – ನಾವು ಅಭ್ಯರ್ಥಿಗೆ ಇತರ ಮಾರ್ಗದರ್ಶಕರನ್ನು ಸೂಚಿಸಿದ್ದೇವೆ.',
  'You have already accepted this request.' => 'ನೀವು ಈಗಾಗಲೇ ಈ ವಿನಂತಿಯನ್ನು ಸ್ವೀಕರಿಸಿದ್ದೀರಿ.',
  'You already declined this request.' => 'ನೀವು ಈಗಾಗಲೇ ಈ ವಿನಂತಿಯನ್ನು ನಿರಾಕರಿಸಿದ್ದೀರಿ.',
