  'Apply on the official website ↗' => 'ಅಧಿಕೃತ ವೆಬ್‌ಸೈಟ್‌ನಲ್ಲಿ ಅರ್ಜಿ ಸಲ್ಲಿಸಿ ↗',
  'Download notification PDF' => 'ಅಧಿಸೂಚನೆ PDF ಡೌನ್‌ಲೋಡ್ ಮಾಡಿ',
