  'After login, get the Jobs Pass for ₹150 + GST (₹' => 'ಲಾಗಿನ್ ನಂತರ, ₹150 + GST ಗೆ ಜಾಬ್ಸ್ ಪಾಸ್ ಪಡೆಯಿರಿ (₹',
