  'Get the Jobs Pass for full details and the apply link' => 'ಪೂರ್ಣ ವಿವರಗಳು ಮತ್ತು ಅರ್ಜಿ ಲಿಂಕ್‌ಗಾಗಿ ಜಾಬ್ಸ್ ಪಾಸ್ ಪಡೆಯಿರಿ',
  '₹150 + GST = ₹' => '₹150 + GST = ₹',
  'Get Jobs Pass – ₹' => 'ಜಾಬ್ಸ್ ಪಾಸ್ ಪಡೆಯಿರಿ – ₹',
  'Jobs Abroad' => 'ವಿದೇಶದಲ್ಲಿ ಉದ್ಯೋಗಗಳು',
  'Jobs Abroad – ' => 'ವಿದೇಶದಲ್ಲಿ ಉದ್ಯೋಗಗಳು – ',
  'passport mandatory' => 'ಪಾಸ್‌ಪೋರ್ಟ್ ಕಡ್ಡಾಯ',
  'Verify every job yourself with the embassy / consulate or that country’s ministry – Jobsence is not liable for fraud.' => 'ಪ್ರತಿ ಉದ್ಯೋಗವನ್ನು ರಾಯಭಾರ ಕಚೇರಿ / ಕಾನ್ಸುಲೇಟ್ ಅಥವಾ ಆ ದೇಶದ ಸಚಿವಾಲಯದೊಂದಿಗೆ ನೀವೇ ಪರಿಶೀಲಿಸಿ – ವಂಚನೆಗೆ Jobsence ಹೊಣೆಯಲ್ಲ.',
  'Register free' => 'ಉಚಿತವಾಗಿ ನೋಂದಾಯಿಸಿ',
  'Top destinations' => 'ಪ್ರಮುಖ ಗಮ್ಯಸ್ಥಾನಗಳು',
  'companies' => 'ಕಂಪನಿಗಳು',
  'candidates' => 'ಅಭ್ಯರ್ಥಿಗಳು',
  'All countries' => 'ಎಲ್ಲಾ ದೇಶಗಳು',
  'job roles' => 'ಉದ್ಯೋಗ ಹುದ್ದೆಗಳು',
  'See all →' => 'ಎಲ್ಲವನ್ನೂ ನೋಡಿ →',
  'Jobsence is a platform, not a recruiting agent. ECR passport holders must emigrate only through agents registered on eMigrate (emigrate.gov.in). Never pay anyone for a job or visa.' => 'Jobsence ಒಂದು ವೇದಿಕೆ, ನೇಮಕಾತಿ ಏಜೆಂಟ್ ಅಲ್ಲ. ECR ಪಾಸ್‌ಪೋರ್ಟ್ ಹೊಂದಿರುವವರು eMigrate (emigrate.gov.in) ನಲ್ಲಿ ನೋಂದಾಯಿತ ಏಜೆಂಟ್‌ಗಳ ಮೂಲಕ ಮಾತ್ರ ವಲಸೆ ಹೋಗಬೇಕು. ಉದ್ಯೋಗ ಅಥವಾ ವೀಸಾಗಾಗಿ ಯಾರಿಗೂ ಎಂದಿಗೂ ಹಣ ಪಾವತಿಸಬೇಡಿ.',
  'Companies hiring abroad' => 'ವಿದೇಶಕ್ಕೆ ನೇಮಕಾತಿ ಮಾಡುತ್ತಿರುವ ಕಂಪನಿಗಳು',
  'Hiring for jobs abroad? Register free' => 'ವಿದೇಶಿ ಉದ್ಯೋಗಗಳಿಗೆ ನೇಮಕಾತಿ ಮಾಡುತ್ತಿದ್ದೀರಾ? ಉಚಿತವಾಗಿ ನೋಂದಾಯಿಸಿ',
  'Paid internships (₹8,000 to ₹5,00,000 a month stipend) and unpaid – both.' => 'ಪಾವತಿಸಿದ ಇಂಟರ್ನ್‌ಶಿಪ್‌ಗಳು (ತಿಂಗಳಿಗೆ ₹8,000 ರಿಂದ ₹5,00,000 ಸ್ಟೈಪೆಂಡ್) ಮತ್ತು ಪಾವತಿರಹಿತ – ಎರಡೂ.',
  '3000+ domains: IT, marketing, accounts, HR, design, healthcare and more.' => '3000+ ಕ್ಷೇತ್ರಗಳು: IT, ಮಾರ್ಕೆಟಿಂಗ್, ಲೆಕ್ಕಪತ್ರ, HR, ವಿನ್ಯಾಸ, ಆರೋಗ್ಯ ಸೇವೆ ಮತ್ತು ಇನ್ನಷ್ಟು.',
  'Choose up to 5 of 3000+ skills – you are trained only in those.' => '3000+ ಕೌಶಲ್ಯಗಳಲ್ಲಿ 5 ರವರೆಗೆ ಆಯ್ಕೆಮಾಡಿ – ನಿಮಗೆ ಅವುಗಳಲ್ಲಿ ಮಾತ್ರ ತರಬೇತಿ ನೀಡಲಾಗುತ್ತದೆ.',
  'Email as soon as a mentor accepts; registration is valid for 3 months.' => 'ಮಾರ್ಗದರ್ಶಕರು ಸ್ವೀಕರಿಸಿದ ತಕ್ಷಣ ಇಮೇಲ್; ನೋಂದಣಿ 3 ತಿಂಗಳವರೆಗೆ ಮಾನ್ಯ.',
  'Providers register free; the ₹155 plan opens 3 profiles a day for 10 days, up to 20.' => 'ಒದಗಿಸುವವರು ಉಚಿತವಾಗಿ ನೋಂದಾಯಿಸುತ್ತಾರೆ; ₹155 ಯೋಜನೆಯು 10 ದಿನಗಳವರೆಗೆ ದಿನಕ್ಕೆ 3 ಪ್ರೊಫೈಲ್‌ಗಳನ್ನು, ಗರಿಷ್ಠ 20 ರವರೆಗೆ ತೆರೆಯುತ್ತದೆ.',
  'Phone and email only after the tripartite agreement.' => 'ತ್ರಿಪಕ್ಷೀಯ ಒಪ್ಪಂದದ ನಂತರವೇ ಫೋನ್ ಮತ್ತು ಇಮೇಲ್.',
  'Companies register free; the ₹155 plan opens 3 full candidate profiles with resume a day.' => 'ಕಂಪನಿಗಳು ಉಚಿತವಾಗಿ ನೋಂದಾಯಿಸುತ್ತವೆ; ₹155 ಯೋಜನೆಯು ದಿನಕ್ಕೆ ರೆಸ್ಯೂಮ್ ಸಹಿತ 3 ಪೂರ್ಣ ಅಭ್ಯರ್ಥಿ ಪ್ರೊಫೈಲ್‌ಗಳನ್ನು ತೆರೆಯುತ್ತದೆ.',
  'Search by your current location, or type your area / PIN code.' => 'ನಿಮ್ಮ ಪ್ರಸ್ತುತ ಸ್ಥಳದ ಮೂಲಕ ಹುಡುಕಿ, ಅಥವಾ ನಿಮ್ಮ ಪ್ರದೇಶ / PIN ಕೋಡ್ ಟೈಪ್ ಮಾಡಿ.',
  'Every provider is photo and live-selfie verified; number after the agreement.' => 'ಪ್ರತಿ ಒದಗಿಸುವವರೂ ಫೋಟೋ ಮತ್ತು ಲೈವ್-ಸೆಲ್ಫಿ ಮೂಲಕ ಪರಿಶೀಲಿತರು; ಒಪ್ಪಂದದ ನಂತರ ಸಂಖ್ಯೆ.',
  'Mentors and institutes register free; learners fill the ₹155 form.' => 'ಮಾರ್ಗದರ್ಶಕರು ಮತ್ತು ಸಂಸ್ಥೆಗಳು ಉಚಿತವಾಗಿ ನೋಂದಾಯಿಸುತ್ತಾರೆ; ಕಲಿಯುವವರು ₹155 ಫಾರ್ಮ್ ಭರ್ತಿ ಮಾಡುತ್ತಾರೆ.',
  'Phone and email only after the tripartite agreement (candidate + mentor + Jobsence).' => 'ತ್ರಿಪಕ್ಷೀಯ ಒಪ್ಪಂದದ (ಅಭ್ಯರ್ಥಿ + ಮಾರ್ಗದರ್ಶಕರು + Jobsence) ನಂತರವೇ ಫೋನ್ ಮತ್ತು ಇಮೇಲ್.',
  'Govt, PSU, railway, police and top company jobs in one place.' => 'ಸರ್ಕಾರಿ, PSU, ರೈಲ್ವೆ, ಪೊಲೀಸ್ ಮತ್ತು ಪ್ರಮುಖ ಕಂಪನಿಗಳ ಉದ್ಯೋಗಗಳು ಒಂದೇ ಕಡೆ.',
  '30,000+ job categories – register once, get a call / email on a match.' => '30,000+ ಉದ್ಯೋಗ ವರ್ಗಗಳು – ಒಮ್ಮೆ ನೋಂದಾಯಿಸಿ, ಹೊಂದಾಣಿಕೆಯಾದಾಗ ಕರೆ / ಇಮೇಲ್ ಪಡೆಯಿರಿ.',
  'incl. GST, one-time' => 'GST ಸೇರಿ, ಒಂದು ಬಾರಿ',
  'Find a mentor – apply' => 'ಮಾರ್ಗದರ್ಶಕರನ್ನು ಹುಡುಕಿ – ಅರ್ಜಿ ಸಲ್ಲಿಸಿ',
  'Want an internship – apply' => 'ಇಂಟರ್ನ್‌ಶಿಪ್ ಬೇಕೇ – ಅರ್ಜಿ ಸಲ್ಲಿಸಿ',
  'Want a job – apply' => 'ಉದ್ಯೋಗ ಬೇಕೇ – ಅರ್ಜಿ ಸಲ್ಲಿಸಿ',
  'Need a service – Near Me pass' => 'ಸೇವೆ ಬೇಕೇ – ನಿಯರ್ ಮಿ ಪಾಸ್',
  'Provide a service? Enrol' => 'ಸೇವೆ ಒದಗಿಸುತ್ತೀರಾ? ನೋಂದಾಯಿಸಿ',
  'Registration free · unlock ' => 'ನೋಂದಣಿ ಉಚಿತ · ಅನ್‌ಲಾಕ್ ',
  'See all' => 'ಎಲ್ಲವನ್ನೂ ನೋಡಿ',
  'Other countries' => 'ಇತರ ದೇಶಗಳು',
  'Frequently asked questions' => 'ಪದೇ ಪದೇ ಕೇಳಲಾಗುವ ಪ್ರಶ್ನೆಗಳು',
  'What is the registration fee?' => 'ನೋಂದಣಿ ಶುಲ್ಕ ಎಷ್ಟು?',
  '₹155 (including GST), one-time, non-refundable.' => '₹155 (GST ಸೇರಿ), ಒಂದು ಬಾರಿ, ಮರುಪಾವತಿ ಇಲ್ಲ.',
  'Is a job or placement guaranteed?' => 'ಉದ್ಯೋಗ ಅಥವಾ ನಿಯೋಜನೆಯ ಖಾತರಿ ಇದೆಯೇ?',
  'No. Jobsence tries to share your profile with suitable companies and mentors.' => 'ಇಲ್ಲ. Jobsence ನಿಮ್ಮ ಪ್ರೊಫೈಲ್ ಅನ್ನು ಸೂಕ್ತ ಕಂಪನಿಗಳು ಮತ್ತು ಮಾರ್ಗದರ್ಶಕರೊಂದಿಗೆ ಹಂಚಿಕೊಳ್ಳಲು ಪ್ರಯತ್ನಿಸುತ್ತದೆ.',
  'Is this a Government scheme?' => 'ಇದು ಸರ್ಕಾರಿ ಯೋಜನೆಯೇ?',
  'No. This is Jobsence’s initiative to make India skilled – not a Government of India scheme.' => 'ಇಲ್ಲ. ಇದು ಭಾರತವನ್ನು ಕೌಶಲ್ಯಪೂರ್ಣಗೊಳಿಸಲು Jobsence ನ ಉಪಕ್ರಮ – ಭಾರತ ಸರ್ಕಾರದ ಯೋಜನೆ ಅಲ್ಲ.',
  'This agreement was not found. Open the link from your email again.' => 'ಈ ಒಪ್ಪಂದ ಕಂಡುಬಂದಿಲ್ಲ. ನಿಮ್ಮ ಇಮೇಲ್‌ನಲ್ಲಿರುವ ಲಿಂಕ್ ಅನ್ನು ಮತ್ತೆ ತೆರೆಯಿರಿ.',
  'Dashboard' => 'ಡ್ಯಾಶ್‌ಬೋರ್ಡ್',
  'Awaiting signatures' => 'ಸಹಿಗಳಿಗಾಗಿ ಕಾಯಲಾಗುತ್ತಿದೆ',
  'Complete – signed by all three' => 'ಪೂರ್ಣಗೊಂಡಿದೆ – ಮೂವರೂ ಸಹಿ ಮಾಡಿದ್ದಾರೆ',
  'Declined' => 'ನಿರಾಕರಿಸಲಾಗಿದೆ',
  'Expired' => 'ಅವಧಿ ಮುಗಿದಿದೆ',
  'Cancelled (another agreement was signed)' => 'ರದ್ದುಗೊಳಿಸಲಾಗಿದೆ (ಇನ್ನೊಂದು ಒಪ್ಪಂದಕ್ಕೆ ಸಹಿ ಮಾಡಲಾಗಿದೆ)',
  'Ended' => 'ಕೊನೆಗೊಂಡಿದೆ',
  'My dashboard' => 'ನನ್ನ ಡ್ಯಾಶ್‌ಬೋರ್ಡ್',
  'Tripartite Agreement' => 'ತ್ರಿಪಕ್ಷೀಯ ಒಪ್ಪಂದ',
  'Facilitator' => 'ಸಹಾಯಕ (ಫೆಸಿಲಿಟೇಟರ್)',
  'Service' => 'ಸೇವೆ',
  'Role / domain' => 'ಹುದ್ದೆ / ಕ್ಷೇತ್ರ',
  'Offline (Delhi-NCR)' => 'ಆಫ್‌ಲೈನ್ (ದೆಹಲಿ-NCR)',
  'Online' => 'ಆನ್‌ಲೈನ್',
  'Terms' => 'ನಿಯಮಗಳು',
  'version' => 'ಆವೃತ್ತಿ',
  'Signatures' => 'ಸಹಿಗಳು',
  'Provider' => 'ಒದಗಿಸುವವರು',
  'Pending' => 'ಬಾಕಿ ಇದೆ',
  'Contact' => 'ಸಂಪರ್ಕ',
  'Email' => 'ಇಮೇಲ್',
  'Address' => 'ವಿಳಾಸ',
  'Use these details only for this purpose.' => 'ಈ ವಿವರಗಳನ್ನು ಈ ಉದ್ದೇಶಕ್ಕೆ ಮಾತ್ರ ಬಳಸಿ.',
  'Print / save as PDF' => 'ಮುದ್ರಿಸಿ / PDF ಆಗಿ ಉಳಿಸಿ',
  'Reject my mentor / provider' => 'ನನ್ನ ಮಾರ್ಗದರ್ಶಕರು / ಒದಗಿಸುವವರನ್ನು ತಿರಸ್ಕರಿಸಿ',
  'End this agreement' => 'ಈ ಒಪ್ಪಂದವನ್ನು ಕೊನೆಗೊಳಿಸಿ',
  'Note: if you reject, your registration closes and a new form fee is needed for a new mentor / internship.' => 'ಸೂಚನೆ: ನೀವು ತಿರಸ್ಕರಿಸಿದರೆ, ನಿಮ್ಮ ನೋಂದಣಿ ಮುಚ್ಚಲ್ಪಡುತ್ತದೆ ಮತ್ತು ಹೊಸ ಮಾರ್ಗದರ್ಶಕರು / ಇಂಟರ್ನ್‌ಶಿಪ್‌ಗಾಗಿ ಹೊಸ ಫಾರ್ಮ್ ಶುಲ್ಕ ಪಾವತಿಸಬೇಕಾಗುತ್ತದೆ.',
  'I understand and want to end it' => 'ನಾನು ಅರ್ಥಮಾಡಿಕೊಂಡಿದ್ದೇನೆ ಮತ್ತು ಇದನ್ನು ಕೊನೆಗೊಳಿಸಲು ಬಯಸುತ್ತೇನೆ',
  'End agreement' => 'ಒಪ್ಪಂದವನ್ನು ಕೊನೆಗೊಳಿಸಿ',
  'You have signed. Waiting for the other party – you will get an email once it is complete.' => 'ನೀವು ಸಹಿ ಮಾಡಿದ್ದೀರಿ. ಇನ್ನೊಂದು ಪಕ್ಷಕ್ಕಾಗಿ ಕಾಯಲಾಗುತ್ತಿದೆ – ಪೂರ್ಣಗೊಂಡ ನಂತರ ನಿಮಗೆ ಇಮೇಲ್ ಬರುತ್ತದೆ.',
  'Choose a hiring plan – then sign here' => 'ನೇಮಕಾತಿ ಯೋಜನೆಯನ್ನು ಆಯ್ಕೆಮಾಡಿ – ನಂತರ ಇಲ್ಲಿ ಸಹಿ ಮಾಡಿ',
  'Sign with an email OTP' => 'ಇಮೇಲ್ OTP ಮೂಲಕ ಸಹಿ ಮಾಡಿ',
  'Resend OTP' => 'OTP ಮತ್ತೆ ಕಳುಹಿಸಿ',
  '1. Send OTP to my email' => '1. ನನ್ನ ಇಮೇಲ್‌ಗೆ OTP ಕಳುಹಿಸಿ',
  'I have read and accept all the terms above.' => 'ಮೇಲಿನ ಎಲ್ಲಾ ನಿಯಮಗಳನ್ನು ನಾನು ಓದಿದ್ದೇನೆ ಮತ್ತು ಒಪ್ಪಿಕೊಳ್ಳುತ್ತೇನೆ.',
  '2. Sign agreement' => '2. ಒಪ್ಪಂದಕ್ಕೆ ಸಹಿ ಮಾಡಿ',
  'Decline this request' => 'ಈ ವಿನಂತಿಯನ್ನು ನಿರಾಕರಿಸಿ',
  'Declining before signing costs nothing.' => 'ಸಹಿ ಮಾಡುವ ಮೊದಲು ನಿರಾಕರಿಸಿದರೆ ಯಾವುದೇ ವೆಚ್ಚವಿಲ್ಲ.',
  'Agreement signed' => 'ಒಪ್ಪಂದಕ್ಕೆ ಸಹಿ ಮಾಡಲಾಗಿದೆ',
  'Cancelled' => 'ರದ್ದುಗೊಳಿಸಲಾಗಿದೆ',
  'My Mentoring Dashboard' => 'ನನ್ನ ಮಾರ್ಗದರ್ಶನ ಡ್ಯಾಶ್‌ಬೋರ್ಡ್',
  'Skill and internship seekers fill the ₹155 form. Mentors, institutes, group mentors and internship companies register free. Phone and email only after both have paid and signed the tripartite agreement.' => 'ಕೌಶಲ್ಯ ಮತ್ತು ಇಂಟರ್ನ್‌ಶಿಪ್ ಬಯಸುವವರು ₹155 ಫಾರ್ಮ್ ಭರ್ತಿ ಮಾಡುತ್ತಾರೆ. ಮಾರ್ಗದರ್ಶಕರು, ಸಂಸ್ಥೆಗಳು, ಗುಂಪು ಮಾರ್ಗದರ್ಶಕರು ಮತ್ತು ಇಂಟರ್ನ್‌ಶಿಪ್ ಕಂಪನಿಗಳು ಉಚಿತವಾಗಿ ನೋಂದಾಯಿಸುತ್ತಾರೆ. ಇಬ್ಬರೂ ಪಾವತಿಸಿ ತ್ರಿಪಕ್ಷೀಯ ಒಪ್ಪಂದಕ್ಕೆ ಸಹಿ ಮಾಡಿದ ನಂತರವೇ ಫೋನ್ ಮತ್ತು ಇಮೇಲ್.',
  'Apply – ₹155' => 'ಅರ್ಜಿ ಸಲ್ಲಿಸಿ – ₹155',
  'See ' => 'ನೋಡಿ: ',
  'Already registered? Open the “My mentoring dashboard” link in your receipt or email.' => 'ಈಗಾಗಲೇ ನೋಂದಾಯಿಸಿದ್ದೀರಾ? ನಿಮ್ಮ ರಸೀದಿ ಅಥವಾ ಇಮೇಲ್‌ನಲ್ಲಿರುವ “ನನ್ನ ಮಾರ್ಗದರ್ಶನ ಡ್ಯಾಶ್‌ಬೋರ್ಡ್” ಲಿಂಕ್ ತೆರೆಯಿರಿ.',
  'My countries' => 'ನನ್ನ ದೇಶಗಳು',
  'Each country one-time ₹1,180 (₹1,000 + GST) or USD 10 – employers in that country can see you.' => 'ಪ್ರತಿ ದೇಶಕ್ಕೆ ಒಂದು ಬಾರಿ ₹1,180 (₹1,000 + GST) ಅಥವಾ USD 10 – ಆ ದೇಶದ ಉದ್ಯೋಗದಾತರು ನಿಮ್ಮನ್ನು ನೋಡಬಹುದು.',
  'pay' => 'ಪಾವತಿಸಿ',
  'No country unlocked yet – add one below.' => 'ಇನ್ನೂ ಯಾವುದೇ ದೇಶವನ್ನು ಅನ್‌ಲಾಕ್ ಮಾಡಿಲ್ಲ – ಕೆಳಗೆ ಒಂದನ್ನು ಸೇರಿಸಿ.',
  'Unlock – ₹1,180' => 'ಅನ್‌ಲಾಕ್ – ₹1,180',
  'Unlock – USD 10' => 'ಅನ್‌ಲಾಕ್ – USD 10',
