  'Plumbers, electricians, carpenters, welders, painters, hair dressers, salons and more – near your PIN code. Every provider registers with a photo and a live selfie.' => 'ಪ್ಲಂಬರ್‌ಗಳು, ಎಲೆಕ್ಟ್ರಿಷಿಯನ್‌ಗಳು, ಬಡಗಿಗಳು, ವೆಲ್ಡರ್‌ಗಳು, ಪೇಂಟರ್‌ಗಳು, ಕ್ಷೌರಿಕರು, ಸಲೂನ್‌ಗಳು ಮತ್ತು ಇನ್ನಷ್ಟು – ನಿಮ್ಮ PIN ಕೋಡ್ ಹತ್ತಿರ. ಪ್ರತಿ ಒದಗಿಸುವವರೂ ಫೋಟೋ ಮತ್ತು ಲೈವ್ ಸೆಲ್ಫಿಯೊಂದಿಗೆ ನೋಂದಾಯಿಸುತ್ತಾರೆ.',
  'I need a service' => 'ನನಗೆ ಸೇವೆ ಬೇಕು',
  'I provide a service – enrol' => 'ನಾನು ಸೇವೆ ಒದಗಿಸುತ್ತೇನೆ – ನೋಂದಾಯಿಸಿ',
  'My requests' => 'ನನ್ನ ವಿನಂತಿಗಳು',
  'Which service' => 'ಯಾವ ಸೇವೆ',
  'PIN code' => 'PIN ಕೋಡ್',
  'or' => 'ಅಥವಾ',
  'State' => 'ರಾಜ್ಯ',
  'City / District' => 'ನಗರ / ಜಿಲ್ಲೆ',
  'Search near me' => 'ನನ್ನ ಹತ್ತಿರ ಹುಡುಕಿ',
  'Your address / area / colony' => 'ನಿಮ್ಮ ವಿಳಾಸ / ಪ್ರದೇಶ / ಕಾಲೋನಿ',
  '✓ Using your location' => '✓ ನಿಮ್ಮ ಸ್ಥಳವನ್ನು ಬಳಸಲಾಗುತ್ತಿದೆ',
  'Use your location, or enter a PIN code, state & city, or your area – anywhere in India.' => 'ನಿಮ್ಮ ಸ್ಥಳವನ್ನು ಬಳಸಿ, ಅಥವಾ PIN ಕೋಡ್, ರಾಜ್ಯ ಮತ್ತು ನಗರ, ಅಥವಾ ನಿಮ್ಮ ಪ್ರದೇಶವನ್ನು ನಮೂದಿಸಿ – ಭಾರತದ ಎಲ್ಲಿಯಾದರೂ.',
  'Enter a valid 6-digit PIN code, or choose a state / city' => 'ಮಾನ್ಯವಾದ 6-ಅಂಕಿಯ PIN ಕೋಡ್ ನಮೂದಿಸಿ, ಅಥವಾ ರಾಜ್ಯ / ನಗರವನ್ನು ಆಯ್ಕೆಮಾಡಿ',
  'All ' => 'ಎಲ್ಲಾ ',
  'Enter a PIN code above, or choose a state / city, and press “Search near me”.' => 'ಮೇಲೆ PIN ಕೋಡ್ ನಮೂದಿಸಿ, ಅಥವಾ ರಾಜ್ಯ / ನಗರವನ್ನು ಆಯ್ಕೆಮಾಡಿ, ಮತ್ತು “ನನ್ನ ಹತ್ತಿರ ಹುಡುಕಿ” ಒತ್ತಿ.',
  'No verified service provider found in this area yet.' => 'ಈ ಪ್ರದೇಶದಲ್ಲಿ ಇನ್ನೂ ಯಾವುದೇ ಪರಿಶೀಲಿತ ಸೇವಾ ಒದಗಿಸುವವರು ಕಂಡುಬಂದಿಲ್ಲ.',
  'Do you provide this service? ' => 'ನೀವು ಈ ಸೇವೆಯನ್ನು ಒದಗಿಸುತ್ತೀರಾ? ',
  'Enrol now' => 'ಈಗಲೇ ನೋಂದಾಯಿಸಿ',
  'Your ' => 'ನಿಮ್ಮ ',
  'Get the Near Me pass to see mobile numbers & full addresses' => 'ಮೊಬೈಲ್ ಸಂಖ್ಯೆಗಳು ಮತ್ತು ಪೂರ್ಣ ವಿಳಾಸಗಳನ್ನು ನೋಡಲು ನಿಯರ್ ಮಿ ಪಾಸ್ ಪಡೆಯಿರಿ',
  'ID Verified' => 'ID ಪರಿಶೀಲಿತ',
  'Paid member' => 'ಪಾವತಿಸಿದ ಸದಸ್ಯ',
  'Renewed ' => 'ನವೀಕರಿಸಲಾಗಿದೆ: ',
  'ratings' => 'ರೇಟಿಂಗ್‌ಗಳು',
  'No ratings yet' => 'ಇನ್ನೂ ರೇಟಿಂಗ್‌ಗಳಿಲ್ಲ',
  'Visit charge from' => 'ಭೇಟಿ ಶುಲ್ಕ ಇಲ್ಲಿಂದ',
  'Agreement awaiting signatures' => 'ಒಪ್ಪಂದವು ಸಹಿಗಳಿಗಾಗಿ ಕಾಯುತ್ತಿದೆ',
  'Request service – sign agreement' => 'ಸೇವೆ ವಿನಂತಿಸಿ – ಒಪ್ಪಂದಕ್ಕೆ ಸಹಿ ಮಾಡಿ',
  'Number shown after both sign' => 'ಇಬ್ಬರೂ ಸಹಿ ಮಾಡಿದ ನಂತರ ಸಂಖ್ಯೆ ತೋರಿಸಲಾಗುತ್ತದೆ',
  'See number' => 'ಸಂಖ್ಯೆ ನೋಡಿ',
  'Verified customer' => 'ಪರಿಶೀಲಿತ ಗ್ರಾಹಕ',
  'Your rating: ' => 'ನಿಮ್ಮ ರೇಟಿಂಗ್: ',
  '⭐ Rate & give feedback' => '⭐ ರೇಟ್ ಮಾಡಿ ಮತ್ತು ಪ್ರತಿಕ್ರಿಯೆ ನೀಡಿ',
  'Save rating' => 'ರೇಟಿಂಗ್ ಉಳಿಸಿ',
  ' Agree on the price and check identity before work starts.' => ' ಕೆಲಸ ಪ್ರಾರಂಭವಾಗುವ ಮೊದಲು ಬೆಲೆಯನ್ನು ಒಪ್ಪಿಕೊಳ್ಳಿ ಮತ್ತು ಗುರುತನ್ನು ಪರಿಶೀಲಿಸಿ.',
  'Not a Govt. scheme' => 'ಸರ್ಕಾರಿ ಯೋಜನೆ ಅಲ್ಲ',
  'Join the Jobsence Mentor Team' => 'Jobsence ಮಾರ್ಗದರ್ಶಕರ ತಂಡಕ್ಕೆ ಸೇರಿ',
  'Who Can Apply?' => 'ಯಾರು ಅರ್ಜಿ ಸಲ್ಲಿಸಬಹುದು?',
  'Anyone who is unemployed – educated or not, from a village or a city.' => 'ನಿರುದ್ಯೋಗಿಯಾಗಿರುವ ಯಾರಾದರೂ – ವಿದ್ಯಾವಂತರಾಗಿರಲಿ ಇಲ್ಲದಿರಲಿ, ಹಳ್ಳಿಯವರಾಗಿರಲಿ ನಗರದವರಾಗಿರಲಿ.',
  'Uneducated' => 'ಅವಿದ್ಯಾವಂತರು',
  '10th Pass' => '10ನೇ ತರಗತಿ ಉತ್ತೀರ್ಣ',
  '12th Pass' => '12ನೇ ತರಗತಿ ಉತ್ತೀರ್ಣ',
  'ITI / Diploma' => 'ITI / ಡಿಪ್ಲೊಮಾ',
  'Graduates' => 'ಪದವೀಧರರು',
  'Engineers' => 'ಇಂಜಿನಿಯರ್‌ಗಳು',
  'Doctors' => 'ವೈದ್ಯರು',
  'Drivers' => 'ಚಾಲಕರು',
  'Homemakers' => 'ಗೃಹಿಣಿಯರು',
  'Daily wage workers' => 'ದಿನಗೂಲಿ ಕಾರ್ಮಿಕರು',
  'Students' => 'ವಿದ್ಯಾರ್ಥಿಗಳು',
  'Village & city youth' => 'ಹಳ್ಳಿ ಮತ್ತು ನಗರದ ಯುವಕರು',
  'How It Works – 4 Simple Steps' => 'ಇದು ಹೇಗೆ ಕೆಲಸ ಮಾಡುತ್ತದೆ – 4 ಸರಳ ಹಂತಗಳು',
  'Fill the form' => 'ಫಾರ್ಮ್ ಭರ್ತಿ ಮಾಡಿ',
  'Enter your details and preferred skills in Hindi or English.' => 'ನಿಮ್ಮ ವಿವರಗಳು ಮತ್ತು ಆದ್ಯತೆಯ ಕೌಶಲ್ಯಗಳನ್ನು ಹಿಂದಿ ಅಥವಾ ಇಂಗ್ಲಿಷ್‌ನಲ್ಲಿ ನಮೂದಿಸಿ.',
  'Pay securely online via UPI, card or net banking.' => 'UPI, ಕಾರ್ಡ್ ಅಥವಾ ನೆಟ್ ಬ್ಯಾಂಕಿಂಗ್ ಮೂಲಕ ಸುರಕ್ಷಿತವಾಗಿ ಆನ್‌ಲೈನ್‌ನಲ್ಲಿ ಪಾವತಿಸಿ.',
  'Wait for scrutiny' => 'ಪರಿಶೀಲನೆಗಾಗಿ ಕಾಯಿರಿ',
  'Scrutiny of forms and resumes takes minimum 3–6 months.' => 'ಫಾರ್ಮ್‌ಗಳು ಮತ್ತು ರೆಸ್ಯೂಮ್‌ಗಳ ಪರಿಶೀಲನೆಗೆ ಕನಿಷ್ಠ 3–6 ತಿಂಗಳು ಬೇಕಾಗುತ್ತದೆ.',
  'Join classes' => 'ತರಗತಿಗಳಿಗೆ ಸೇರಿ',
  'After selection, start training online or offline in Delhi-NCR.' => 'ಆಯ್ಕೆಯ ನಂತರ, ಆನ್‌ಲೈನ್‌ನಲ್ಲಿ ಅಥವಾ ದೆಹಲಿ-NCR ನಲ್ಲಿ ಆಫ್‌ಲೈನ್‌ನಲ್ಲಿ ತರಬೇತಿ ಪ್ರಾರಂಭಿಸಿ.',
  'Fill Form Now' => 'ಈಗಲೇ ಫಾರ್ಮ್ ಭರ್ತಿ ಮಾಡಿ',
  'Course Details, Training Modes & Languages' => 'ಕೋರ್ಸ್ ವಿವರಗಳು, ತರಬೇತಿ ವಿಧಾನಗಳು ಮತ್ತು ಭಾಷೆಗಳು',
  'Schedule' => 'ವೇಳಾಪಟ್ಟಿ',
  '2 hours/day, 3 days a week, including practical training.' => 'ದಿನಕ್ಕೆ 2 ಗಂಟೆ, ವಾರಕ್ಕೆ 3 ದಿನ, ಪ್ರಾಯೋಗಿಕ ತರಬೇತಿ ಸೇರಿ.',
  'Online Video Classes – Pan-India' => 'ಆನ್‌ಲೈನ್ ವೀಡಿಯೊ ತರಗತಿಗಳು – ಭಾರತದಾದ್ಯಂತ',
  'Learn from anywhere on your mobile or computer.' => 'ನಿಮ್ಮ ಮೊಬೈಲ್ ಅಥವಾ ಕಂಪ್ಯೂಟರ್‌ನಲ್ಲಿ ಎಲ್ಲಿಂದಲಾದರೂ ಕಲಿಯಿರಿ.',
  'Offline Classes – Delhi-NCR only' => 'ಆಫ್‌ಲೈನ್ ತರಗತಿಗಳು – ದೆಹಲಿ-NCR ನಲ್ಲಿ ಮಾತ್ರ',
  'Classroom learning with hands-on practical training.' => 'ಪ್ರತ್ಯಕ್ಷ ಪ್ರಾಯೋಗಿಕ ತರಬೇತಿಯೊಂದಿಗೆ ತರಗತಿ ಕಲಿಕೆ.',
  'Hindi, English or local/regional language – depending on mentor availability.' => 'ಹಿಂದಿ, ಇಂಗ್ಲಿಷ್ ಅಥವಾ ಸ್ಥಳೀಯ/ಪ್ರಾದೇಶಿಕ ಭಾಷೆ – ಮಾರ್ಗದರ್ಶಕರ ಲಭ್ಯತೆಯನ್ನು ಅವಲಂಬಿಸಿ.',
  '2000+ skills – a few examples' => '2000+ ಕೌಶಲ್ಯಗಳು – ಕೆಲವು ಉದಾಹರಣೆಗಳು',
  'Training is delivered by the Jobsence Mentor Team and third-party skill development partners.' => 'ತರಬೇತಿಯನ್ನು Jobsence ಮಾರ್ಗದರ್ಶಕರ ತಂಡ ಮತ್ತು ಮೂರನೇ ವ್ಯಕ್ತಿ ಕೌಶಲ್ಯ ಅಭಿವೃದ್ಧಿ ಪಾಲುದಾರರು ನೀಡುತ್ತಾರೆ.',
  'Fee Structure' => 'ಶುಲ್ಕ ರಚನೆ',
  'One-time processing fee (including GST)' => 'ಒಂದು ಬಾರಿಯ ಪ್ರಕ್ರಿಯಾ ಶುಲ್ಕ (GST ಸೇರಿ)',
  'Total course fee after selection' => 'ಆಯ್ಕೆಯ ನಂತರ ಒಟ್ಟು ಕೋರ್ಸ್ ಶುಲ್ಕ',
  'Both fees are non-refundable.' => 'ಎರಡೂ ಶುಲ್ಕಗಳು ಮರುಪಾವತಿಸಲಾಗುವುದಿಲ್ಲ.',
  'Jobsence is building its own Team of Mentors to give skills to unemployed youth of India. If you are good at any skill, enrol yourself.' => 'ಭಾರತದ ನಿರುದ್ಯೋಗಿ ಯುವಕರಿಗೆ ಕೌಶಲ್ಯ ನೀಡಲು Jobsence ತನ್ನದೇ ಆದ ಮಾರ್ಗದರ್ಶಕರ ತಂಡವನ್ನು ರಚಿಸುತ್ತಿದೆ. ನೀವು ಯಾವುದೇ ಕೌಶಲ್ಯದಲ್ಲಿ ಪರಿಣತರಾಗಿದ್ದರೆ, ನಿಮ್ಮನ್ನು ನೋಂದಾಯಿಸಿಕೊಳ್ಳಿ.',
  'Fixed Emolument' => 'ನಿಗದಿತ ಗೌರವಧನ',
  'Fixed payment per candidate – for video / online and offline (Delhi-NCR) classes, paid after training is completed.' => 'ಪ್ರತಿ ಅಭ್ಯರ್ಥಿಗೆ ನಿಗದಿತ ಪಾವತಿ – ವೀಡಿಯೊ / ಆನ್‌ಲೈನ್ ಮತ್ತು ಆಫ್‌ಲೈನ್ (ದೆಹಲಿ-NCR) ತರಗತಿಗಳಿಗೆ, ತರಬೇತಿ ಪೂರ್ಣಗೊಂಡ ನಂತರ ಪಾವತಿಸಲಾಗುತ್ತದೆ.',
  'Demo Video' => 'ಡೆಮೊ ವೀಡಿಯೊ',
  'Send your details with a demo video that mentions “This video is for Jobsence Skill Development”.' => '“ಈ ವೀಡಿಯೊ Jobsence ಕೌಶಲ್ಯ ಅಭಿವೃದ್ಧಿಗಾಗಿ” ಎಂದು ಉಲ್ಲೇಖಿಸುವ ಡೆಮೊ ವೀಡಿಯೊದೊಂದಿಗೆ ನಿಮ್ಮ ವಿವರಗಳನ್ನು ಕಳುಹಿಸಿ.',
  'Conditions' => 'ಷರತ್ತುಗಳು',
  'Fill Mentor Enrolment Form' => 'ಮಾರ್ಗದರ್ಶಕರ ನೋಂದಣಿ ಫಾರ್ಮ್ ಭರ್ತಿ ಮಾಡಿ',
  'Declaration & Disclaimer' => 'ಘೋಷಣೆ ಮತ್ತು ಹಕ್ಕು ನಿರಾಕರಣೆ',
  'Jobsence does not guarantee any job or placement.' => 'Jobsence ಯಾವುದೇ ಉದ್ಯೋಗ ಅಥವಾ ನಿಯೋಜನೆಯ ಖಾತರಿ ನೀಡುವುದಿಲ್ಲ.',
  'We only try to push your resume to companies, make you job-ready, or guide you towards self-employment.' => 'ನಾವು ನಿಮ್ಮ ರೆಸ್ಯೂಮ್ ಅನ್ನು ಕಂಪನಿಗಳಿಗೆ ತಲುಪಿಸಲು, ನಿಮ್ಮನ್ನು ಉದ್ಯೋಗಕ್ಕೆ ಸಿದ್ಧಗೊಳಿಸಲು ಅಥವಾ ಸ್ವಯಂ ಉದ್ಯೋಗದ ಕಡೆಗೆ ಮಾರ್ಗದರ್ಶನ ನೀಡಲು ಮಾತ್ರ ಪ್ರಯತ್ನಿಸುತ್ತೇವೆ.',
  'This is Jobsence’s initiative to make India skilled – not a Government of India scheme.' => 'ಇದು ಭಾರತವನ್ನು ಕೌಶಲ್ಯಪೂರ್ಣಗೊಳಿಸಲು Jobsence ನ ಉಪಕ್ರಮ – ಭಾರತ ಸರ್ಕಾರದ ಯೋಜನೆ ಅಲ್ಲ.',
  'Frequently Asked Questions' => 'ಪದೇ ಪದೇ ಕೇಳಲಾಗುವ ಪ್ರಶ್ನೆಗಳು',
  'Internship / Job forms' => 'ಇಂಟರ್ನ್‌ಶಿಪ್ / ಉದ್ಯೋಗ ಫಾರ್ಮ್‌ಗಳು',
  'Skill Development by State / UT' => 'ರಾಜ್ಯ / ಕೇಂದ್ರಾಡಳಿತ ಪ್ರದೇಶವಾರು ಕೌಶಲ್ಯ ಅಭಿವೃದ್ಧಿ',
  'Skills, Mentors & Training' => 'ಕೌಶಲ್ಯಗಳು, ಮಾರ್ಗದರ್ಶಕರು ಮತ್ತು ತರಬೇತಿ',
  'See which skills we offer training in right now (online or offline in Delhi-NCR) and which skills we are looking for mentors in. Learners can choose up to 5 skills.' => 'ನಾವು ಸದ್ಯ ಯಾವ ಕೌಶಲ್ಯಗಳಲ್ಲಿ ತರಬೇತಿ ನೀಡುತ್ತೇವೆ (ಆನ್‌ಲೈನ್ ಅಥವಾ ದೆಹಲಿ-NCR ನಲ್ಲಿ ಆಫ್‌ಲೈನ್) ಮತ್ತು ಯಾವ ಕೌಶಲ್ಯಗಳಿಗೆ ಮಾರ್ಗದರ್ಶಕರನ್ನು ಹುಡುಕುತ್ತಿದ್ದೇವೆ ಎಂದು ನೋಡಿ. ಕಲಿಯುವವರು 5 ಕೌಶಲ್ಯಗಳವರೆಗೆ ಆಯ್ಕೆ ಮಾಡಬಹುದು.',
  'Apply to Learn – ₹155' => 'ಕಲಿಯಲು ಅರ್ಜಿ ಸಲ್ಲಿಸಿ – ₹155',
  'Become a Mentor / Trainer' => 'ಮಾರ್ಗದರ್ಶಕರು / ತರಬೇತುದಾರರಾಗಿ',
  'Choose up to 5 skills' => '5 ಕೌಶಲ್ಯಗಳವರೆಗೆ ಆಯ್ಕೆಮಾಡಿ',
  'In order of preference – you are trained only in these skills.' => 'ಆದ್ಯತೆಯ ಕ್ರಮದಲ್ಲಿ – ನಿಮಗೆ ಈ ಕೌಶಲ್ಯಗಳಲ್ಲಿ ಮಾತ್ರ ತರಬೇತಿ ನೀಡಲಾಗುತ್ತದೆ.',
  'Get matched with a mentor' => 'ಮಾರ್ಗದರ್ಶಕರೊಂದಿಗೆ ಹೊಂದಾಣಿಕೆ ಪಡೆಯಿರಿ',
  'Once selected, we send a request to the best-matching mentor.' => 'ಆಯ್ಕೆಯಾದ ನಂತರ, ಅತ್ಯುತ್ತಮವಾಗಿ ಹೊಂದುವ ಮಾರ್ಗದರ್ಶಕರಿಗೆ ನಾವು ವಿನಂತಿ ಕಳುಹಿಸುತ್ತೇವೆ.',
  'Online or offline' => 'ಆನ್‌ಲೈನ್ ಅಥವಾ ಆಫ್‌ಲೈನ್',
  'If a mentor is not available, you can choose from the list of online and offline mentors yourself.' => 'ಮಾರ್ಗದರ್ಶಕರು ಲಭ್ಯವಿಲ್ಲದಿದ್ದರೆ, ಆನ್‌ಲೈನ್ ಮತ್ತು ಆಫ್‌ಲೈನ್ ಮಾರ್ಗದರ್ಶಕರ ಪಟ್ಟಿಯಿಂದ ನೀವೇ ಆಯ್ಕೆ ಮಾಡಬಹುದು.',
  'Skills We Teach & Mentors We Are Looking For' => 'ನಾವು ಕಲಿಸುವ ಕೌಶಲ್ಯಗಳು ಮತ್ತು ನಾವು ಹುಡುಕುತ್ತಿರುವ ಮಾರ್ಗದರ್ಶಕರು',
  'Want to learn? Or are you an expert in a skill? There is a place for both on Jobsence.' => 'ಕಲಿಯಲು ಬಯಸುವಿರಾ? ಅಥವಾ ನೀವು ಯಾವುದಾದರೂ ಕೌಶಲ್ಯದಲ್ಲಿ ಪರಿಣತರೇ? Jobsence ನಲ್ಲಿ ಇಬ್ಬರಿಗೂ ಸ್ಥಾನವಿದೆ.',
  'Training Available' => 'ಲಭ್ಯವಿರುವ ತರಬೇತಿ',
  'Offline Delhi-NCR' => 'ಆಫ್‌ಲೈನ್ ದೆಹಲಿ-NCR',
  'Our mentor team is forming – be one of the first mentors!' => 'ನಮ್ಮ ಮಾರ್ಗದರ್ಶಕರ ತಂಡ ರಚನೆಯಾಗುತ್ತಿದೆ – ಮೊದಲ ಮಾರ್ಗದರ್ಶಕರಲ್ಲಿ ಒಬ್ಬರಾಗಿ!',
  'Apply to learn' => 'ಕಲಿಯಲು ಅರ್ಜಿ ಸಲ್ಲಿಸಿ',
  'Mentors Wanted For' => 'ಈ ಕೌಶಲ್ಯಗಳಿಗೆ ಮಾರ್ಗದರ್ಶಕರು ಬೇಕಾಗಿದ್ದಾರೆ',
  'learners' => 'ಕಲಿಯುವವರು',
  'Become a mentor' => 'ಮಾರ್ಗದರ್ಶಕರಾಗಿ',
  'See all skills' => 'ಎಲ್ಲಾ ಕೌಶಲ್ಯಗಳನ್ನು ನೋಡಿ',
  'Find Doctors & Hospital Staff' => 'ವೈದ್ಯರು ಮತ್ತು ಆಸ್ಪತ್ರೆ ಸಿಬ್ಬಂದಿಯನ್ನು ಹುಡುಕಿ',
  'Keywords from your requirement are matched with candidates’ briefs and resumes. The pass lasts 15 days – name, mobile, email and resume.' => 'ನಿಮ್ಮ ಅವಶ್ಯಕತೆಯ ಕೀವರ್ಡ್‌ಗಳನ್ನು ಅಭ್ಯರ್ಥಿಗಳ ಸಂಕ್ಷಿಪ್ತ ವಿವರ ಮತ್ತು ರೆಸ್ಯೂಮ್‌ಗಳೊಂದಿಗೆ ಹೊಂದಿಸಲಾಗುತ್ತದೆ. ಪಾಸ್ 15 ದಿನಗಳವರೆಗೆ ಇರುತ್ತದೆ – ಹೆಸರು, ಮೊಬೈಲ್, ಇಮೇಲ್ ಮತ್ತು ರೆಸ್ಯೂಮ್.',
  'Talent Search – Hire Part-time People' => 'ಟ್ಯಾಲೆಂಟ್ ಸರ್ಚ್ – ಅರೆಕಾಲಿಕ ಸಿಬ್ಬಂದಿಯನ್ನು ನೇಮಿಸಿ',
  'Exhibition staff, promoters, models, bouncers, drivers and 30,000+ roles – with resume keywords, city, hours and daily pay.' => 'ಪ್ರದರ್ಶನ ಸಿಬ್ಬಂದಿ, ಪ್ರಮೋಟರ್‌ಗಳು, ಮಾಡೆಲ್‌ಗಳು, ಬೌನ್ಸರ್‌ಗಳು, ಚಾಲಕರು ಮತ್ತು 30,000+ ಹುದ್ದೆಗಳು – ರೆಸ್ಯೂಮ್ ಕೀವರ್ಡ್‌ಗಳು, ನಗರ, ಗಂಟೆಗಳು ಮತ್ತು ದಿನಗೂಲಿಯೊಂದಿಗೆ.',
  'Your pass is active till ' => 'ನಿಮ್ಮ ಪಾಸ್ ಇಲ್ಲಿಯವರೆಗೆ ಸಕ್ರಿಯವಾಗಿದೆ: ',
  'Role: ' => 'ಹುದ್ದೆ: ',
  'Total ' => 'ಒಟ್ಟು ',
  'Register to see names, numbers, emails and resumes' => 'ಹೆಸರುಗಳು, ಸಂಖ್ಯೆಗಳು, ಇಮೇಲ್‌ಗಳು ಮತ್ತು ರೆಸ್ಯೂಮ್‌ಗಳನ್ನು ನೋಡಲು ನೋಂದಾಯಿಸಿ',
  'Get the Talent Pass to see names, numbers and resumes' => 'ಹೆಸರುಗಳು, ಸಂಖ್ಯೆಗಳು ಮತ್ತು ರೆಸ್ಯೂಮ್‌ಗಳನ್ನು ನೋಡಲು ಟ್ಯಾಲೆಂಟ್ ಪಾಸ್ ಪಡೆಯಿರಿ',
  'One-time fee by role, valid 15 days' => 'ಹುದ್ದೆಯ ಪ್ರಕಾರ ಒಂದು ಬಾರಿಯ ಶುಲ್ಕ, 15 ದಿನಗಳವರೆಗೆ ಮಾನ್ಯ',
  'Register now' => 'ಈಗಲೇ ನೋಂದಾಯಿಸಿ',
  'Keywords (skill, post, department)' => 'ಕೀವರ್ಡ್‌ಗಳು (ಕೌಶಲ್ಯ, ಹುದ್ದೆ, ವಿಭಾಗ)',
  'City / State' => 'ನಗರ / ರಾಜ್ಯ',
  'Candidates matching your requirement: ' => 'ನಿಮ್ಮ ಅವಶ್ಯಕತೆಗೆ ಹೊಂದುವ ಅಭ್ಯರ್ಥಿಗಳು: ',
  'No matching candidate yet. Try other keywords or a city.' => 'ಇನ್ನೂ ಹೊಂದುವ ಅಭ್ಯರ್ಥಿ ಇಲ್ಲ. ಬೇರೆ ಕೀವರ್ಡ್‌ಗಳು ಅಥವಾ ನಗರವನ್ನು ಪ್ರಯತ್ನಿಸಿ.',
  'See all candidates' => 'ಎಲ್ಲಾ ಅಭ್ಯರ್ಥಿಗಳನ್ನು ನೋಡಿ',
  'Prefers: ' => 'ಆದ್ಯತೆ: ',
  'Min' => 'ಕನಿಷ್ಠ',
  'day' => 'ದಿನ',
  'hrs/day' => 'ಗಂಟೆ/ದಿನ',
  'Expects' => 'ನಿರೀಕ್ಷೆ',
  'Resume' => 'ರೆಸ್ಯೂಮ್',
  'Resume available' => 'ರೆಸ್ಯೂಮ್ ಲಭ್ಯವಿದೆ',
  ' Always check identity and documents before hiring.' => ' ನೇಮಿಸುವ ಮೊದಲು ಯಾವಾಗಲೂ ಗುರುತು ಮತ್ತು ದಾಖಲೆಗಳನ್ನು ಪರಿಶೀಲಿಸಿ.',
  'Login – choose who you are' => 'ಲಾಗಿನ್ – ನೀವು ಯಾರು ಎಂದು ಆಯ್ಕೆಮಾಡಿ',
  'Giving skill is punya – a good deed for humankind' => 'ಕೌಶಲ್ಯ ನೀಡುವುದು ಪುಣ್ಯ – ಮಾನವಕುಲಕ್ಕೆ ಒಂದು ಸತ್ಕಾರ್ಯ',
  'Meaning in' => 'ಅರ್ಥ:',
  'For Young India' => 'ಯುವ ಭಾರತಕ್ಕಾಗಿ',
  'a Jobsence initiative' => 'Jobsence ನ ಒಂದು ಉಪಕ್ರಮ',
  'Mentors, institutes & internship companies register free · see who wants to learn what · connect with a tripartite agreement' => 'ಮಾರ್ಗದರ್ಶಕರು, ಸಂಸ್ಥೆಗಳು ಮತ್ತು ಇಂಟರ್ನ್‌ಶಿಪ್ ಕಂಪನಿಗಳು ಉಚಿತವಾಗಿ ನೋಂದಾಯಿಸುತ್ತಾರೆ · ಯಾರು ಏನನ್ನು ಕಲಿಯಲು ಬಯಸುತ್ತಾರೆ ಎಂದು ನೋಡಿ · ತ್ರಿಪಕ್ಷೀಯ ಒಪ್ಪಂದದ ಮೂಲಕ ಸಂಪರ್ಕಿಸಿ',
  'Open mentoring →' => 'ಮಾರ್ಗದರ್ಶನ ತೆರೆಯಿರಿ →',
  'Skill Development Registration' => 'ಕೌಶಲ್ಯ ಅಭಿವೃದ್ಧಿ ನೋಂದಣಿ',
  'Candidates for Skill Development – Apply Here' => 'ಕೌಶಲ್ಯ ಅಭಿವೃದ್ಧಿಗಾಗಿ ಅಭ್ಯರ್ಥಿಗಳು – ಇಲ್ಲಿ ಅರ್ಜಿ ಸಲ್ಲಿಸಿ',
  'First become skilled – online video classes (Pan-India) or offline (Delhi-NCR).' => 'ಮೊದಲು ಕೌಶಲ್ಯವಂತರಾಗಿ – ಆನ್‌ಲೈನ್ ವೀಡಿಯೊ ತರಗತಿಗಳು (ಭಾರತದಾದ್ಯಂತ) ಅಥವಾ ಆಫ್‌ಲೈನ್ (ದೆಹಲಿ-NCR).',
  'Your skill choices – up to 5, in order of preference (search 3000+ list)' => 'ನಿಮ್ಮ ಕೌಶಲ್ಯ ಆಯ್ಕೆಗಳು – 5 ರವರೆಗೆ, ಆದ್ಯತೆಯ ಕ್ರಮದಲ್ಲಿ (3000+ ಪಟ್ಟಿಯಲ್ಲಿ ಹುಡುಕಿ)',
  'Education & Current Status' => 'ಶಿಕ್ಷಣ ಮತ್ತು ಪ್ರಸ್ತುತ ಸ್ಥಿತಿ',
  'Stream / Specialisation / Other (e.g. B.Com, Engineer, Doctor)' => 'ವಿಭಾಗ / ವಿಶೇಷತೆ / ಇತರೆ (ಉದಾ. B.Com, ಇಂಜಿನಿಯರ್, ವೈದ್ಯರು)',
  'Current Status' => 'ಪ್ರಸ್ತುತ ಸ್ಥಿತಿ',
  'Do you have any work experience?' => 'ನಿಮಗೆ ಯಾವುದಾದರೂ ಕೆಲಸದ ಅನುಭವವಿದೆಯೇ?',
  'Yes' => 'ಹೌದು',
  'No' => 'ಇಲ್ಲ',
  'If yes, describe briefly (job role + years)' => 'ಹೌದು ಎಂದಾದರೆ, ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಿ (ಉದ್ಯೋಗ ಹುದ್ದೆ + ವರ್ಷಗಳು)',
  'Skill Preference' => 'ಕೌಶಲ್ಯ ಆದ್ಯತೆ',
  'Preferred Mode of Training' => 'ಆದ್ಯತೆಯ ತರಬೇತಿ ವಿಧಾನ',
  'Online / Video classes (Pan-India)' => 'ಆನ್‌ಲೈನ್ / ವೀಡಿಯೊ ತರಗತಿಗಳು (ಭಾರತದಾದ್ಯಂತ)',
  'Offline classes – Delhi-NCR only' => 'ಆಫ್‌ಲೈನ್ ತರಗತಿಗಳು – ದೆಹಲಿ-NCR ನಲ್ಲಿ ಮಾತ್ರ',
  'Preferred Language of Training' => 'ಆದ್ಯತೆಯ ತರಬೇತಿ ಭಾಷೆ',
  'Preferred city / location (for offline)' => 'ಆದ್ಯತೆಯ ನಗರ / ಸ್ಥಳ (ಆಫ್‌ಲೈನ್‌ಗಾಗಿ)',
  'Any other skill you want to learn' => 'ನೀವು ಕಲಿಯಲು ಬಯಸುವ ಬೇರೆ ಯಾವುದೇ ಕೌಶಲ್ಯ',
  'Brief description about yourself (education, work, goals)' => 'ನಿಮ್ಮ ಬಗ್ಗೆ ಸಂಕ್ಷಿಪ್ತ ವಿವರ (ಶಿಕ್ಷಣ, ಕೆಲಸ, ಗುರಿಗಳು)',
  'Upload resume if any (PDF/DOC, max 5MB)' => 'ರೆಸ್ಯೂಮ್ ಇದ್ದರೆ ಅಪ್‌ಲೋಡ್ ಮಾಡಿ (PDF/DOC, ಗರಿಷ್ಠ 5MB)',
  'The information provided by me is true and correct.' => 'ನಾನು ನೀಡಿರುವ ಮಾಹಿತಿ ಸತ್ಯ ಮತ್ತು ಸರಿಯಾಗಿದೆ.',
  'The one-time processing fee of ₹155 (including GST) is non-refundable.' => '₹155 (GST ಸೇರಿ) ಒಂದು ಬಾರಿಯ ಪ್ರಕ್ರಿಯಾ ಶುಲ್ಕವನ್ನು ಮರುಪಾವತಿಸಲಾಗುವುದಿಲ್ಲ.',
  'I will be trained only in the skills I chose (up to 5).' => 'ನಾನು ಆಯ್ಕೆ ಮಾಡಿದ ಕೌಶಲ್ಯಗಳಲ್ಲಿ (5 ರವರೆಗೆ) ಮಾತ್ರ ನನಗೆ ತರಬೇತಿ ನೀಡಲಾಗುತ್ತದೆ.',
  'After selection, the total course fee of ₹12,000 + 18% GST is also non-refundable.' => 'ಆಯ್ಕೆಯ ನಂತರ, ₹12,000 + 18% GST ಒಟ್ಟು ಕೋರ್ಸ್ ಶುಲ್ಕವನ್ನೂ ಮರುಪಾವತಿಸಲಾಗುವುದಿಲ್ಲ.',
  'Classes will be 2 hours per day, 3 days a week, including practical training.' => 'ತರಗತಿಗಳು ದಿನಕ್ಕೆ 2 ಗಂಟೆ, ವಾರಕ್ಕೆ 3 ದಿನ ಇರುತ್ತವೆ, ಪ್ರಾಯೋಗಿಕ ತರಬೇತಿ ಸೇರಿ.',
  'Minimum 3 to 6 months is required for scrutiny of forms and resumes.' => 'ಫಾರ್ಮ್‌ಗಳು ಮತ್ತು ರೆಸ್ಯೂಮ್‌ಗಳ ಪರಿಶೀಲನೆಗೆ ಕನಿಷ್ಠ 3 ರಿಂದ 6 ತಿಂಗಳು ಬೇಕಾಗುತ್ತದೆ.',
  'Jobsence will try to push my resume to interested companies, make me job-ready, or guide me towards self-employment.' => 'Jobsence ನನ್ನ ರೆಸ್ಯೂಮ್ ಅನ್ನು ಆಸಕ್ತ ಕಂಪನಿಗಳಿಗೆ ತಲುಪಿಸಲು, ನನ್ನನ್ನು ಉದ್ಯೋಗಕ್ಕೆ ಸಿದ್ಧಗೊಳಿಸಲು ಅಥವಾ ಸ್ವಯಂ ಉದ್ಯೋಗದ ಕಡೆಗೆ ಮಾರ್ಗದರ್ಶನ ನೀಡಲು ಪ್ರಯತ್ನಿಸುತ್ತದೆ.',
  'Jobsence does not take any responsibility or guarantee of job / placement.' => 'ಉದ್ಯೋಗ / ನಿಯೋಜನೆಯ ಯಾವುದೇ ಜವಾಬ್ದಾರಿ ಅಥವಾ ಖಾತರಿಯನ್ನು Jobsence ತೆಗೆದುಕೊಳ್ಳುವುದಿಲ್ಲ.',
  'Training will be conducted through third-party skill development partners, in local language / Hindi / English depending on mentor availability.' => 'ತರಬೇತಿಯನ್ನು ಮೂರನೇ ವ್ಯಕ್ತಿ ಕೌಶಲ್ಯ ಅಭಿವೃದ್ಧಿ ಪಾಲುದಾರರ ಮೂಲಕ, ಮಾರ್ಗದರ್ಶಕರ ಲಭ್ಯತೆಯನ್ನು ಅವಲಂಬಿಸಿ ಸ್ಥಳೀಯ ಭಾಷೆ / ಹಿಂದಿ / ಇಂಗ್ಲಿಷ್‌ನಲ್ಲಿ ನಡೆಸಲಾಗುತ್ತದೆ.',
  'Scrutiny of forms takes minimum 3 to 6 months.' => 'ಫಾರ್ಮ್‌ಗಳ ಪರಿಶೀಲನೆಗೆ ಕನಿಷ್ಠ 3 ರಿಂದ 6 ತಿಂಗಳು ಬೇಕಾಗುತ್ತದೆ.',
  'After selection, you will be informed about the course fee of ₹12,000 + 18% GST (non-refundable).' => 'ಆಯ್ಕೆಯ ನಂತರ, ₹12,000 + 18% GST ಕೋರ್ಸ್ ಶುಲ್ಕದ (ಮರುಪಾವತಿ ಇಲ್ಲ) ಬಗ್ಗೆ ನಿಮಗೆ ತಿಳಿಸಲಾಗುತ್ತದೆ.',
  'Classes will be 2 hours per day, 3 days a week, with practical training.' => 'ತರಗತಿಗಳು ದಿನಕ್ಕೆ 2 ಗಂಟೆ, ವಾರಕ್ಕೆ 3 ದಿನ, ಪ್ರಾಯೋಗಿಕ ತರಬೇತಿಯೊಂದಿಗೆ ಇರುತ್ತವೆ.',
  'Internship Registration' => 'ಇಂಟರ್ನ್‌ಶಿಪ್ ನೋಂದಣಿ',
  'Candidates for Internship – Apply Here' => 'ಇಂಟರ್ನ್‌ಶಿಪ್‌ಗಾಗಿ ಅಭ್ಯರ್ಥಿಗಳು – ಇಲ್ಲಿ ಅರ್ಜಿ ಸಲ್ಲಿಸಿ',
  'Get practical experience – 3000+ domains, on-site or work from home.' => 'ಪ್ರಾಯೋಗಿಕ ಅನುಭವ ಪಡೆಯಿರಿ – 3000+ ಕ್ಷೇತ್ರಗಳು, ಸ್ಥಳದಲ್ಲೇ ಅಥವಾ ಮನೆಯಿಂದ ಕೆಲಸ.',
  'Preferred internship domain (search 3000+ categories)' => 'ಆದ್ಯತೆಯ ಇಂಟರ್ನ್‌ಶಿಪ್ ಕ್ಷೇತ್ರ (3000+ ವರ್ಗಗಳಲ್ಲಿ ಹುಡುಕಿ)',
  'Education' => 'ಶಿಕ್ಷಣ',
  'Current Course (e.g. B.Tech CSE, BBA, ITI Electrician)' => 'ಪ್ರಸ್ತುತ ಕೋರ್ಸ್ (ಉದಾ. B.Tech CSE, BBA, ITI ಎಲೆಕ್ಟ್ರಿಷಿಯನ್)',
  'College / Institute Name' => 'ಕಾಲೇಜು / ಸಂಸ್ಥೆಯ ಹೆಸರು',
  'Year of Course' => 'ಕೋರ್ಸ್‌ನ ವರ್ಷ',
  '1st Year' => '1ನೇ ವರ್ಷ',
  '2nd Year' => '2ನೇ ವರ್ಷ',
  '3rd Year' => '3ನೇ ವರ್ಷ',
