  'Paid internships pay ₹8,000 – ₹5,00,000 per month. Leave empty for unpaid.' => 'ಪಾವತಿಸಿದ ಇಂಟರ್ನ್‌ಶಿಪ್‌ಗಳು ತಿಂಗಳಿಗೆ ₹8,000 – ₹5,00,000 ನೀಡುತ್ತವೆ. ಪಾವತಿರಹಿತಕ್ಕೆ ಖಾಲಿ ಬಿಡಿ.',
