  'Get regular work – 3000+ job categories across India.' => 'ನಿಯಮಿತ ಕೆಲಸ ಪಡೆಯಿರಿ – ಭಾರತದಾದ್ಯಂತ 3000+ ಉದ್ಯೋಗ ವರ್ಗಗಳು.',
