  'Work on your own schedule – a few hours, a few days.' => 'ನಿಮ್ಮ ಸ್ವಂತ ವೇಳಾಪಟ್ಟಿಯಲ್ಲಿ ಕೆಲಸ ಮಾಡಿ – ಕೆಲವು ಗಂಟೆಗಳು, ಕೆಲವು ದಿನಗಳು.',
