  'Work from home – data entry, digital marketing, customer support and more.' => 'ಮನೆಯಿಂದ ಕೆಲಸ – ಡೇಟಾ ಎಂಟ್ರಿ, ಡಿಜಿಟಲ್ ಮಾರ್ಕೆಟಿಂಗ್, ಗ್ರಾಹಕ ಬೆಂಬಲ ಮತ್ತು ಇನ್ನಷ್ಟು.',
