  'Your Key Skills' => 'ನಿಮ್ಮ ಪ್ರಮುಖ ಕೌಶಲ್ಯಗಳು',
  'Exhibition manpower, models, bouncers, drivers, laundry services and 30,000+ part-time roles. One-time ₹250 + GST (₹295), valid for 3 months.' => 'ಪ್ರದರ್ಶನ ಸಿಬ್ಬಂದಿ, ಮಾಡೆಲ್‌ಗಳು, ಬೌನ್ಸರ್‌ಗಳು, ಚಾಲಕರು, ಲಾಂಡ್ರಿ ಸೇವೆಗಳು ಮತ್ತು 30,000+ ಅರೆಕಾಲಿಕ ಹುದ್ದೆಗಳು. ಒಂದು ಬಾರಿ ₹250 + GST (₹295), 3 ತಿಂಗಳವರೆಗೆ ಮಾನ್ಯ.',
  'Part-time work you want – minimum 2, maximum 5 options (search 30,000+ list)' => 'ನೀವು ಬಯಸುವ ಅರೆಕಾಲಿಕ ಕೆಲಸ – ಕನಿಷ್ಠ 2, ಗರಿಷ್ಠ 5 ಆಯ್ಕೆಗಳು (30,000+ ಪಟ್ಟಿಯಲ್ಲಿ ಹುಡುಕಿ)',
  'Preferred job category (search 30,000+ categories)' => 'ಆದ್ಯತೆಯ ಉದ್ಯೋಗ ವರ್ಗ (30,000+ ವರ್ಗಗಳಲ್ಲಿ ಹುಡುಕಿ)',
  'Important' => 'ಪ್ರಮುಖ',
  'One-time fee ₹250 + 18% GST = ₹295 – registration valid for 3 months from payment.' => 'ಒಂದು ಬಾರಿಯ ಶುಲ್ಕ ₹250 + 18% GST = ₹295 – ಪಾವತಿಯ ದಿನದಿಂದ 3 ತಿಂಗಳವರೆಗೆ ನೋಂದಣಿ ಮಾನ್ಯ.',
  'Choose 2 to 5 kinds of work, with your minimum expected pay per day, hours, dates and timings.' => 'ನಿಮ್ಮ ದಿನದ ಕನಿಷ್ಠ ನಿರೀಕ್ಷಿತ ವೇತನ, ಗಂಟೆಗಳು, ದಿನಾಂಕಗಳು ಮತ್ತು ಸಮಯದೊಂದಿಗೆ 2 ರಿಂದ 5 ಬಗೆಯ ಕೆಲಸಗಳನ್ನು ಆಯ್ಕೆಮಾಡಿ.',
  'Qualification & Experience' => 'ವಿದ್ಯಾರ್ಹತೆ ಮತ್ತು ಅನುಭವ',
  'Total Experience' => 'ಒಟ್ಟು ಅನುಭವ',
  'Fresher' => 'ಹೊಸಬರು (ಫ್ರೆಶರ್)',
  'Less than 1 year' => '1 ವರ್ಷಕ್ಕಿಂತ ಕಡಿಮೆ',
  '1–3 years' => '1–3 ವರ್ಷಗಳು',
  '3–5 years' => '3–5 ವರ್ಷಗಳು',
  '5–10 years' => '5–10 ವರ್ಷಗಳು',
  '10+ years' => '10+ ವರ್ಷಗಳು',
  'Degree / Stream / Certificate' => 'ಪದವಿ / ವಿಭಾಗ / ಪ್ರಮಾಣಪತ್ರ',
  'Current / Last Job Role & Company' => 'ಪ್ರಸ್ತುತ / ಕೊನೆಯ ಉದ್ಯೋಗ ಹುದ್ದೆ ಮತ್ತು ಕಂಪನಿ',
  'Job Preference' => 'ಉದ್ಯೋಗ ಆದ್ಯತೆ',
  'job' => 'ಉದ್ಯೋಗ',
  'My registration is valid for 3 months from the date of payment.' => 'ನನ್ನ ನೋಂದಣಿ ಪಾವತಿಯ ದಿನಾಂಕದಿಂದ 3 ತಿಂಗಳವರೆಗೆ ಮಾನ್ಯ.',
  'Jobs in India Pass (1 month)' => 'ಭಾರತದಲ್ಲಿ ಉದ್ಯೋಗಗಳ ಪಾಸ್ (1 ತಿಂಗಳು)',
  'See all Govt, PSU & top company jobs' => 'ಎಲ್ಲಾ ಸರ್ಕಾರಿ, PSU ಮತ್ತು ಪ್ರಮುಖ ಕಂಪನಿಗಳ ಉದ್ಯೋಗಗಳನ್ನು ನೋಡಿ',
  'Railways, Army, Police, State Govts, PSUs (GAIL, BHEL…) and top company jobs in one place. ₹150 + GST (₹177) unlocks full details and official apply links for 1 month.' => 'ರೈಲ್ವೆ, ಸೇನೆ, ಪೊಲೀಸ್, ರಾಜ್ಯ ಸರ್ಕಾರಗಳು, PSU ಗಳು (GAIL, BHEL…) ಮತ್ತು ಪ್ರಮುಖ ಕಂಪನಿಗಳ ಉದ್ಯೋಗಗಳು ಒಂದೇ ಕಡೆ. ₹150 + GST (₹177) 1 ತಿಂಗಳವರೆಗೆ ಪೂರ್ಣ ವಿವರಗಳು ಮತ್ತು ಅಧಿಕೃತ ಅರ್ಜಿ ಲಿಂಕ್‌ಗಳನ್ನು ತೆರೆಯುತ್ತದೆ.',
  'One pass = one email + one mobile number, for 1 month. Email OTP verification is required.' => 'ಒಂದು ಪಾಸ್ = ಒಂದು ಇಮೇಲ್ + ಒಂದು ಮೊಬೈಲ್ ಸಂಖ್ಯೆ, 1 ತಿಂಗಳವರೆಗೆ. ಇಮೇಲ್ OTP ಪರಿಶೀಲನೆ ಕಡ್ಡಾಯ.',
  'This fee is for Jobsence’s job-listing service – it is NOT a government fee. Always apply for government jobs on the official website only.' => 'ಈ ಶುಲ್ಕವು Jobsence ನ ಉದ್ಯೋಗ ಪಟ್ಟಿ ಸೇವೆಗಾಗಿ – ಇದು ಸರ್ಕಾರಿ ಶುಲ್ಕವಲ್ಲ. ಸರ್ಕಾರಿ ಉದ್ಯೋಗಗಳಿಗೆ ಯಾವಾಗಲೂ ಅಧಿಕೃತ ವೆಬ್‌ಸೈಟ್‌ನಲ್ಲಿ ಮಾತ್ರ ಅರ್ಜಿ ಸಲ್ಲಿಸಿ.',
  'Jobsence is not affiliated with these departments / companies; every job links to its official source.' => 'Jobsence ಈ ಇಲಾಖೆಗಳು / ಕಂಪನಿಗಳೊಂದಿಗೆ ಸಂಬಂಧ ಹೊಂದಿಲ್ಲ; ಪ್ರತಿ ಉದ್ಯೋಗವೂ ಅದರ ಅಧಿಕೃತ ಮೂಲಕ್ಕೆ ಲಿಂಕ್ ಆಗಿದೆ.',
  'Your Details' => 'ನಿಮ್ಮ ವಿವರಗಳು',
  'Full Name' => 'ಪೂರ್ಣ ಹೆಸರು',
  'Mobile Number' => 'ಮೊಬೈಲ್ ಸಂಖ್ಯೆ',
  'Email (same as your login)' => 'ಇಮೇಲ್ (ನಿಮ್ಮ ಲಾಗಿನ್‌ನಂತೆಯೇ)',
  'OTP and pass confirmation will be sent here.' => 'OTP ಮತ್ತು ಪಾಸ್ ದೃಢೀಕರಣವನ್ನು ಇಲ್ಲಿಗೆ ಕಳುಹಿಸಲಾಗುತ್ತದೆ.',
  'State / UT' => 'ರಾಜ್ಯ / ಕೇಂದ್ರಾಡಳಿತ ಪ್ರದೇಶ',
  'Jobs you are interested in' => 'ನಿಮಗೆ ಆಸಕ್ತಿಯಿರುವ ಉದ್ಯೋಗಗಳು',
  'The fee of ₹177 (₹150 + GST) is non-refundable and the pass is valid for 1 month from payment.' => '₹177 (₹150 + GST) ಶುಲ್ಕವನ್ನು ಮರುಪಾವತಿಸಲಾಗುವುದಿಲ್ಲ ಮತ್ತು ಪಾಸ್ ಪಾವತಿಯ ದಿನದಿಂದ 1 ತಿಂಗಳವರೆಗೆ ಮಾನ್ಯ.',
  'The pass is only for my email and mobile; I will not share it with anyone.' => 'ಪಾಸ್ ನನ್ನ ಇಮೇಲ್ ಮತ್ತು ಮೊಬೈಲ್‌ಗೆ ಮಾತ್ರ; ನಾನು ಅದನ್ನು ಯಾರೊಂದಿಗೂ ಹಂಚಿಕೊಳ್ಳುವುದಿಲ್ಲ.',
  'This is not a government fee. Jobsence does not guarantee any job and is not affiliated with the hiring departments / companies.' => 'ಇದು ಸರ್ಕಾರಿ ಶುಲ್ಕವಲ್ಲ. Jobsence ಯಾವುದೇ ಉದ್ಯೋಗದ ಖಾತರಿ ನೀಡುವುದಿಲ್ಲ ಮತ್ತು ನೇಮಕಾತಿ ಮಾಡುವ ಇಲಾಖೆಗಳು / ಕಂಪನಿಗಳೊಂದಿಗೆ ಸಂಬಂಧ ಹೊಂದಿಲ್ಲ.',
  'Now open the “See Jobs in India” page to see full details and official apply links of all jobs.' => 'ಈಗ “ಭಾರತದಲ್ಲಿ ಉದ್ಯೋಗಗಳನ್ನು ನೋಡಿ” ಪುಟವನ್ನು ತೆರೆದು ಎಲ್ಲಾ ಉದ್ಯೋಗಗಳ ಪೂರ್ಣ ವಿವರಗಳು ಮತ್ತು ಅಧಿಕೃತ ಅರ್ಜಿ ಲಿಂಕ್‌ಗಳನ್ನು ನೋಡಿ.',
  'Always apply on the official website. Beware of anyone asking for money in exchange for a job.' => 'ಯಾವಾಗಲೂ ಅಧಿಕೃತ ವೆಬ್‌ಸೈಟ್‌ನಲ್ಲಿ ಅರ್ಜಿ ಸಲ್ಲಿಸಿ. ಉದ್ಯೋಗಕ್ಕೆ ಬದಲಾಗಿ ಹಣ ಕೇಳುವ ಯಾರ ಬಗ್ಗೆಯೂ ಎಚ್ಚರದಿಂದಿರಿ.',
  'Plumber' => 'ಪ್ಲಂಬರ್',
  'Electrician' => 'ಎಲೆಕ್ಟ್ರಿಷಿಯನ್',
  'Carpenter' => 'ಬಡಗಿ',
  'Welder' => 'ವೆಲ್ಡರ್',
  'House Painter' => 'ಮನೆ ಪೇಂಟರ್',
  'Mason (Raj Mistri)' => 'ಮೇಸ್ತ್ರಿ (ಗಾರೆ ಕೆಲಸ)',
