  'Tap the button – PIN, city and state fill in automatically and customers see you by distance. Or type your address below.' => 'ಬಟನ್ ಒತ್ತಿ – PIN, ನಗರ ಮತ್ತು ರಾಜ್ಯ ತಾನಾಗಿಯೇ ಭರ್ತಿಯಾಗುತ್ತವೆ ಮತ್ತು ಗ್ರಾಹಕರು ನಿಮ್ಮನ್ನು ದೂರದ ಆಧಾರದಲ್ಲಿ ನೋಡುತ್ತಾರೆ. ಅಥವಾ ಕೆಳಗೆ ನಿಮ್ಮ ವಿಳಾಸವನ್ನು ಟೈಪ್ ಮಾಡಿ.',
  'House / Shop No., Street, Area' => 'ಮನೆ / ಅಂಗಡಿ ಸಂಖ್ಯೆ, ರಸ್ತೆ, ಪ್ರದೇಶ',
