  'Nearest Landmark' => 'ಹತ್ತಿರದ ಹೆಗ್ಗುರುತು',
  'Near Me Service Provider Registration' => 'ನಿಯರ್ ಮಿ ಸೇವಾ ಒದಗಿಸುವವರ ನೋಂದಣಿ',
  'Plumber, electrician, carpenter, hair dresser, salon – enrol as a service provider' => 'ಪ್ಲಂಬರ್, ಎಲೆಕ್ಟ್ರಿಷಿಯನ್, ಬಡಗಿ, ಹೇರ್ ಡ್ರೆಸ್ಸರ್, ಸಲೂನ್ – ಸೇವಾ ಒದಗಿಸುವವರಾಗಿ ನೋಂದಾಯಿಸಿ',
  'Reach customers near you. ₹150 + GST (₹177) for 3 months. Photo and a live selfie are mandatory for identity verification.' => 'ನಿಮ್ಮ ಹತ್ತಿರದ ಗ್ರಾಹಕರನ್ನು ತಲುಪಿ. 3 ತಿಂಗಳಿಗೆ ₹150 + GST (₹177). ಗುರುತು ಪರಿಶೀಲನೆಗಾಗಿ ಫೋಟೋ ಮತ್ತು ಲೈವ್ ಸೆಲ್ಫಿ ಕಡ್ಡಾಯ.',
  'Other services (optional) – up to 5, from a 47,000+ list' => 'ಇತರ ಸೇವೆಗಳು (ಐಚ್ಛಿಕ) – 47,000+ ಪಟ್ಟಿಯಿಂದ 5 ರವರೆಗೆ',
  'Fee ₹150 + 18% GST = ₹177, valid for 3 months from payment.' => 'ಶುಲ್ಕ ₹150 + 18% GST = ₹177, ಪಾವತಿಯ ದಿನದಿಂದ 3 ತಿಂಗಳವರೆಗೆ ಮಾನ್ಯ.',
  'Your name / shop name, mobile number and address will be shown to paying customers.' => 'ನಿಮ್ಮ ಹೆಸರು / ಅಂಗಡಿಯ ಹೆಸರು, ಮೊಬೈಲ್ ಸಂಖ್ಯೆ ಮತ್ತು ವಿಳಾಸವನ್ನು ಪಾವತಿಸುವ ಗ್ರಾಹಕರಿಗೆ ತೋರಿಸಲಾಗುತ್ತದೆ.',
  'A clear photo and a live selfie are mandatory – the Jobsence team verifies your identity.' => 'ಸ್ಪಷ್ಟ ಫೋಟೋ ಮತ್ತು ಲೈವ್ ಸೆಲ್ಫಿ ಕಡ್ಡಾಯ – Jobsence ತಂಡ ನಿಮ್ಮ ಗುರುತನ್ನು ಪರಿಶೀಲಿಸುತ್ತದೆ.',
  'Your Identity' => 'ನಿಮ್ಮ ಗುರುತು',
