  'If other, write your profession' => 'ಇತರೆ ಆಗಿದ್ದರೆ, ನಿಮ್ಮ ವೃತ್ತಿಯನ್ನು ಬರೆಯಿರಿ',
  'You are' => 'ನೀವು',
