  'Photo & Live Selfie (mandatory)' => 'ಫೋಟೋ ಮತ್ತು ಲೈವ್ ಸೆಲ್ಫಿ (ಕಡ್ಡಾಯ)',
  'Your clear photo / shop photo (JPG/PNG, max 5MB)' => 'ನಿಮ್ಮ ಸ್ಪಷ್ಟ ಫೋಟೋ / ಅಂಗಡಿಯ ಫೋಟೋ (JPG/PNG, ಗರಿಷ್ಠ 5MB)',
  'This photo is shown to customers.' => 'ಈ ಫೋಟೋವನ್ನು ಗ್ರಾಹಕರಿಗೆ ತೋರಿಸಲಾಗುತ್ತದೆ.',
