  'The selfie is seen only by the Jobsence team for verification – never shown to customers.' => 'ಸೆಲ್ಫಿಯನ್ನು ಪರಿಶೀಲನೆಗಾಗಿ Jobsence ತಂಡ ಮಾತ್ರ ನೋಡುತ್ತದೆ – ಗ್ರಾಹಕರಿಗೆ ಎಂದಿಗೂ ತೋರಿಸುವುದಿಲ್ಲ.',
  'Service Details' => 'ಸೇವೆಯ ವಿವರಗಳು',
  'Minimum visit / service charge (₹)' => 'ಕನಿಷ್ಠ ಭೇಟಿ / ಸೇವಾ ಶುಲ್ಕ (₹)',
  'How far do you travel for work' => 'ಕೆಲಸಕ್ಕಾಗಿ ನೀವು ಎಷ್ಟು ದೂರ ಪ್ರಯಾಣಿಸುತ್ತೀರಿ',
  '2 km' => '2 km',
  '5 km' => '5 km',
  '10 km' => '10 km',
  '25 km' => '25 km',
  'At my shop only' => 'ನನ್ನ ಅಂಗಡಿಯಲ್ಲಿ ಮಾತ್ರ',
  'Working hours (e.g. 9am – 7pm)' => 'ಕೆಲಸದ ಸಮಯ (ಉದಾ. ಬೆಳಿಗ್ಗೆ 9 – ಸಂಜೆ 7)',
  'About your service (optional)' => 'ನಿಮ್ಮ ಸೇವೆಯ ಬಗ್ಗೆ (ಐಚ್ಛಿಕ)',
  'Your Address & PIN Code' => 'ನಿಮ್ಮ ವಿಳಾಸ ಮತ್ತು PIN ಕೋಡ್',
  'The information, photo and selfie provided are true and my own.' => 'ನೀಡಿರುವ ಮಾಹಿತಿ, ಫೋಟೋ ಮತ್ತು ಸೆಲ್ಫಿ ಸತ್ಯ ಮತ್ತು ನನ್ನದೇ ಆಗಿವೆ.',
  'The fee of ₹177 (₹150 + GST) is non-refundable; registration is valid for 3 months from payment.' => '₹177 (₹150 + GST) ಶುಲ್ಕವನ್ನು ಮರುಪಾವತಿಸಲಾಗುವುದಿಲ್ಲ; ನೋಂದಣಿ ಪಾವತಿಯ ದಿನದಿಂದ 3 ತಿಂಗಳವರೆಗೆ ಮಾನ್ಯ.',
  'I agree that my name, mobile number and address are shown to paying customers.' => 'ನನ್ನ ಹೆಸರು, ಮೊಬೈಲ್ ಸಂಖ್ಯೆ ಮತ್ತು ವಿಳಾಸವನ್ನು ಪಾವತಿಸುವ ಗ್ರಾಹಕರಿಗೆ ತೋರಿಸಲು ನಾನು ಒಪ್ಪುತ್ತೇನೆ.',
  'I will charge customers fairly and behave properly.' => 'ನಾನು ಗ್ರಾಹಕರಿಂದ ನ್ಯಾಯಯುತ ಶುಲ್ಕ ಪಡೆಯುತ್ತೇನೆ ಮತ್ತು ಸರಿಯಾಗಿ ವರ್ತಿಸುತ್ತೇನೆ.',
  'The Jobsence team will verify your identity from your photo and selfie; after verification your profile shows “Verified”.' => 'Jobsence ತಂಡ ನಿಮ್ಮ ಫೋಟೋ ಮತ್ತು ಸೆಲ್ಫಿಯಿಂದ ನಿಮ್ಮ ಗುರುತನ್ನು ಪರಿಶೀಲಿಸುತ್ತದೆ; ಪರಿಶೀಲನೆಯ ನಂತರ ನಿಮ್ಮ ಪ್ರೊಫೈಲ್‌ನಲ್ಲಿ “ಪರಿಶೀಲಿತ” ಎಂದು ತೋರಿಸುತ್ತದೆ.',
  'Customers looking for your service in your PIN code area will call / WhatsApp you directly.' => 'ನಿಮ್ಮ PIN ಕೋಡ್ ಪ್ರದೇಶದಲ್ಲಿ ನಿಮ್ಮ ಸೇವೆಯನ್ನು ಹುಡುಕುತ್ತಿರುವ ಗ್ರಾಹಕರು ನಿಮಗೆ ನೇರವಾಗಿ ಕರೆ / WhatsApp ಮಾಡುತ್ತಾರೆ.',
  'Near Me – Find a Service Provider' => 'ನಿಯರ್ ಮಿ – ಸೇವಾ ಒದಗಿಸುವವರನ್ನು ಹುಡುಕಿ',
  'Find a plumber, electrician, carpenter or salon near you' => 'ನಿಮ್ಮ ಹತ್ತಿರದ ಪ್ಲಂಬರ್, ಎಲೆಕ್ಟ್ರಿಷಿಯನ್, ಬಡಗಿ ಅಥವಾ ಸಲೂನ್ ಹುಡುಕಿ',
  'Pay a platform fee of ₹150 + GST (₹177) and choose verified service providers near your PIN code for 3 months; their mobile number and address appear once both of you sign the agreement.' => '₹150 + GST (₹177) ಪ್ಲಾಟ್‌ಫಾರ್ಮ್ ಶುಲ್ಕ ಪಾವತಿಸಿ ಮತ್ತು 3 ತಿಂಗಳವರೆಗೆ ನಿಮ್ಮ PIN ಕೋಡ್ ಹತ್ತಿರದ ಪರಿಶೀಲಿತ ಸೇವಾ ಒದಗಿಸುವವರನ್ನು ಆಯ್ಕೆಮಾಡಿ; ನೀವಿಬ್ಬರೂ ಒಪ್ಪಂದಕ್ಕೆ ಸಹಿ ಮಾಡಿದ ನಂತರ ಅವರ ಮೊಬೈಲ್ ಸಂಖ್ಯೆ ಮತ್ತು ವಿಳಾಸ ಕಾಣಿಸುತ್ತದೆ.',
  'Services you need – up to 5' => 'ನಿಮಗೆ ಬೇಕಾದ ಸೇವೆಗಳು – 5 ರವರೆಗೆ',
  'Platform fee ₹150 + 18% GST = ₹177, valid for 3 months from payment.' => 'ಪ್ಲಾಟ್‌ಫಾರ್ಮ್ ಶುಲ್ಕ ₹150 + 18% GST = ₹177, ಪಾವತಿಯ ದಿನದಿಂದ 3 ತಿಂಗಳವರೆಗೆ ಮಾನ್ಯ.',
  'You pay the service provider directly for the work – Jobsence only connects you.' => 'ಕೆಲಸಕ್ಕಾಗಿ ನೀವು ಸೇವಾ ಒದಗಿಸುವವರಿಗೆ ನೇರವಾಗಿ ಪಾವತಿಸುತ್ತೀರಿ – Jobsence ಕೇವಲ ಸಂಪರ್ಕ ಕಲ್ಪಿಸುತ್ತದೆ.',
  'Your OTP and access link will be sent here.' => 'ನಿಮ್ಮ OTP ಮತ್ತು ಪ್ರವೇಶ ಲಿಂಕ್ ಅನ್ನು ಇಲ್ಲಿಗೆ ಕಳುಹಿಸಲಾಗುತ್ತದೆ.',
  'What You Need' => 'ನಿಮಗೆ ಏನು ಬೇಕು',
  'When do you need it' => 'ನಿಮಗೆ ಯಾವಾಗ ಬೇಕು',
  'Today / urgent' => 'ಇಂದು / ತುರ್ತು',
  'This week' => 'ಈ ವಾರ',
  'Flexible' => 'ಯಾವಾಗಲಾದರೂ',
  'Briefly describe the work (optional)' => 'ಕೆಲಸವನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಿ (ಐಚ್ಛಿಕ)',
  'The platform fee of ₹177 (₹150 + GST) is non-refundable; access is valid for 3 months from payment.' => '₹177 (₹150 + GST) ಪ್ಲಾಟ್‌ಫಾರ್ಮ್ ಶುಲ್ಕವನ್ನು ಮರುಪಾವತಿಸಲಾಗುವುದಿಲ್ಲ; ಪ್ರವೇಶವು ಪಾವತಿಯ ದಿನದಿಂದ 3 ತಿಂಗಳವರೆಗೆ ಮಾನ್ಯ.',
  'I will use service providers’ details only for my own work and will not share or sell them.' => 'ನಾನು ಸೇವಾ ಒದಗಿಸುವವರ ವಿವರಗಳನ್ನು ನನ್ನ ಸ್ವಂತ ಕೆಲಸಕ್ಕೆ ಮಾತ್ರ ಬಳಸುತ್ತೇನೆ ಮತ್ತು ಅವುಗಳನ್ನು ಹಂಚಿಕೊಳ್ಳುವುದಿಲ್ಲ ಅಥವಾ ಮಾರಾಟ ಮಾಡುವುದಿಲ್ಲ.',
  'Enter your PIN code on the “Near Me” page, choose a provider and sign the agreement with an email OTP – the number appears as soon as the provider signs.' => '“ನಿಯರ್ ಮಿ” ಪುಟದಲ್ಲಿ ನಿಮ್ಮ PIN ಕೋಡ್ ನಮೂದಿಸಿ, ಒದಗಿಸುವವರನ್ನು ಆಯ್ಕೆಮಾಡಿ ಮತ್ತು ಇಮೇಲ್ OTP ಮೂಲಕ ಒಪ್ಪಂದಕ್ಕೆ ಸಹಿ ಮಾಡಿ – ಒದಗಿಸುವವರು ಸಹಿ ಮಾಡಿದ ತಕ್ಷಣ ಸಂಖ್ಯೆ ಕಾಣಿಸುತ್ತದೆ.',
  'Agree on the price and check identity before work starts.' => 'ಕೆಲಸ ಪ್ರಾರಂಭವಾಗುವ ಮೊದಲು ಬೆಲೆಯನ್ನು ಒಪ್ಪಿಕೊಳ್ಳಿ ಮತ್ತು ಗುರುತನ್ನು ಪರಿಶೀಲಿಸಿ.',
  'Restaurant & Chef Jobs Registration' => 'ರೆಸ್ಟೋರೆಂಟ್ ಮತ್ತು ಬಾಣಸಿಗ ಉದ್ಯೋಗಗಳ ನೋಂದಣಿ',
  'Restaurant, hotel & chef jobs – near you, in another city or abroad' => 'ರೆಸ್ಟೋರೆಂಟ್, ಹೋಟೆಲ್ ಮತ್ತು ಬಾಣಸಿಗ ಉದ್ಯೋಗಗಳು – ನಿಮ್ಮ ಹತ್ತಿರ, ಬೇರೆ ನಗರದಲ್ಲಿ ಅಥವಾ ವಿದೇಶದಲ್ಲಿ',
  'Chef, cook, tandoor, waiter, captain, bartender, steward – enrol first for jobs near you, in another city or abroad. ₹250 + 18% GST (₹295) for 3 months.' => 'ಬಾಣಸಿಗ, ಅಡುಗೆಯವರು, ತಂದೂರ್, ವೇಟರ್, ಕ್ಯಾಪ್ಟನ್, ಬಾರ್‌ಟೆಂಡರ್, ಸ್ಟೀವರ್ಡ್ – ನಿಮ್ಮ ಹತ್ತಿರ, ಬೇರೆ ನಗರದಲ್ಲಿ ಅಥವಾ ವಿದೇಶದಲ್ಲಿ ಉದ್ಯೋಗಗಳಿಗಾಗಿ ಮೊದಲು ನೋಂದಾಯಿಸಿ. 3 ತಿಂಗಳಿಗೆ ₹250 + 18% GST (₹295).',
  'Roles you want – up to 5 (e.g. Tandoor Chef, Commis Chef, Waiter)' => 'ನೀವು ಬಯಸುವ ಹುದ್ದೆಗಳು – 5 ರವರೆಗೆ (ಉದಾ. ತಂದೂರ್ ಬಾಣಸಿಗ, ಕಮಿ ಬಾಣಸಿಗ, ವೇಟರ್)',
  'One-time fee ₹250 + 18% GST = ₹295 – valid for 3 months from payment.' => 'ಒಂದು ಬಾರಿಯ ಶುಲ್ಕ ₹250 + 18% GST = ₹295 – ಪಾವತಿಯ ದಿನದಿಂದ 3 ತಿಂಗಳವರೆಗೆ ಮಾನ್ಯ.',
  'For jobs abroad, go only through recruiting agents registered on the Government of India eMigrate portal; never pay anyone in cash.' => 'ವಿದೇಶಿ ಉದ್ಯೋಗಗಳಿಗೆ, ಭಾರತ ಸರ್ಕಾರದ eMigrate ಪೋರ್ಟಲ್‌ನಲ್ಲಿ ನೋಂದಾಯಿತ ನೇಮಕಾತಿ ಏಜೆಂಟ್‌ಗಳ ಮೂಲಕ ಮಾತ್ರ ಹೋಗಿ; ಯಾರಿಗೂ ಎಂದಿಗೂ ನಗದು ಪಾವತಿಸಬೇಡಿ.',
  'Experience & Cuisine' => 'ಅನುಭವ ಮತ್ತು ಪಾಕಪದ್ಧತಿ',
  'Cuisines / specialisation' => 'ಪಾಕಪದ್ಧತಿಗಳು / ವಿಶೇಷತೆ',
  'North Indian' => 'ಉತ್ತರ ಭಾರತೀಯ',
  'South Indian' => 'ದಕ್ಷಿಣ ಭಾರತೀಯ',
  'Chinese' => 'ಚೈನೀಸ್',
  'Tandoor' => 'ತಂದೂರ್',
  'Mughlai' => 'ಮೊಘಲಾಯಿ',
  'Continental' => 'ಕಾಂಟಿನೆಂಟಲ್',
  'Italian / Pizza' => 'ಇಟಾಲಿಯನ್ / ಪಿಜ್ಜಾ',
  'Bakery / Pastry' => 'ಬೇಕರಿ / ಪೇಸ್ಟ್ರಿ',
  'Halwai / Sweets' => 'ಹಲ್ವಾಯಿ / ಸಿಹಿತಿಂಡಿಗಳು',
  'Arabic / Shawarma' => 'ಅರೇಬಿಕ್ / ಶವರ್ಮಾ',
  'Thai / Asian' => 'ಥಾಯ್ / ಏಷ್ಯನ್',
  'Fast Food' => 'ಫಾಸ್ಟ್ ಫುಡ್',
  'Service (waiter / captain)' => 'ಸೇವೆ (ವೇಟರ್ / ಕ್ಯಾಪ್ಟನ್)',
  'Bar / bartender' => 'ಬಾರ್ / ಬಾರ್‌ಟೆಂಡರ್',
  'Current / last role and hotel / restaurant' => 'ಪ್ರಸ್ತುತ / ಕೊನೆಯ ಹುದ್ದೆ ಮತ್ತು ಹೋಟೆಲ್ / ರೆಸ್ಟೋರೆಂಟ್',
  'Where You Want to Work' => 'ನೀವು ಎಲ್ಲಿ ಕೆಲಸ ಮಾಡಲು ಬಯಸುತ್ತೀರಿ',
  'Work location' => 'ಕೆಲಸದ ಸ್ಥಳ',
  'Near me' => 'ನನ್ನ ಹತ್ತಿರ',
  'In another city' => 'ಬೇರೆ ನಗರದಲ್ಲಿ',
  'Abroad' => 'ವಿದೇಶದಲ್ಲಿ',
  'Preferred city / cities' => 'ಆದ್ಯತೆಯ ನಗರ / ನಗರಗಳು',
  'Countries abroad (if chosen)' => 'ವಿದೇಶಿ ದೇಶಗಳು (ಆಯ್ಕೆ ಮಾಡಿದ್ದರೆ)',
  'Passport' => 'ಪಾಸ್‌ಪೋರ್ಟ್',
  'Yes, I have' => 'ಹೌದು, ನನ್ನ ಬಳಿ ಇದೆ',
  'Applied' => 'ಅರ್ಜಿ ಸಲ್ಲಿಸಲಾಗಿದೆ',
  'Expected salary (₹ per month)' => 'ನಿರೀಕ್ಷಿತ ವೇತನ (ತಿಂಗಳಿಗೆ ₹)',
  'Resume (optional – PDF/DOC, max 5MB)' => 'ರೆಸ್ಯೂಮ್ (ಐಚ್ಛಿಕ – PDF/DOC, ಗರಿಷ್ಠ 5MB)',
  'Your photo (optional)' => 'ನಿಮ್ಮ ಫೋಟೋ (ಐಚ್ಛಿಕ)',
  'Jobsence is not a recruiting agent and charges nothing for sending anyone abroad.' => 'Jobsence ನೇಮಕಾತಿ ಏಜೆಂಟ್ ಅಲ್ಲ ಮತ್ತು ಯಾರನ್ನೂ ವಿದೇಶಕ್ಕೆ ಕಳುಹಿಸಲು ಯಾವುದೇ ಶುಲ್ಕ ವಿಧಿಸುವುದಿಲ್ಲ.',
  'Doctor' => 'ವೈದ್ಯರು',
  'Front Desk / Reception' => 'ಫ್ರಂಟ್ ಡೆಸ್ಕ್ / ಸ್ವಾಗತ',
  'Sales & Marketing' => 'ಮಾರಾಟ ಮತ್ತು ಮಾರ್ಕೆಟಿಂಗ್',
  'Sweeper / Housekeeping' => 'ಸ್ವೀಪರ್ / ಹೌಸ್‌ಕೀಪಿಂಗ್',
  'Other hospital staff (nurse, technician, pharmacist, ward boy…)' => 'ಇತರ ಆಸ್ಪತ್ರೆ ಸಿಬ್ಬಂದಿ (ನರ್ಸ್, ತಂತ್ರಜ್ಞ, ಫಾರ್ಮಸಿಸ್ಟ್, ವಾರ್ಡ್ ಬಾಯ್…)',
  'Doctor & Hospital Staff Job Registration' => 'ವೈದ್ಯರು ಮತ್ತು ಆಸ್ಪತ್ರೆ ಸಿಬ್ಬಂದಿ ಉದ್ಯೋಗ ನೋಂದಣಿ',
  'Doctors, nurses, front desk & hospital staff – register for jobs' => 'ವೈದ್ಯರು, ನರ್ಸ್‌ಗಳು, ಫ್ರಂಟ್ ಡೆಸ್ಕ್ ಮತ್ತು ಆಸ್ಪತ್ರೆ ಸಿಬ್ಬಂದಿ – ಉದ್ಯೋಗಗಳಿಗಾಗಿ ನೋಂದಾಯಿಸಿ',
  'Jobs in hospitals, clinics and nursing homes. Keywords from your brief and resume are matched with what hospitals need. Registration is valid for 1 month.' => 'ಆಸ್ಪತ್ರೆಗಳು, ಕ್ಲಿನಿಕ್‌ಗಳು ಮತ್ತು ನರ್ಸಿಂಗ್ ಹೋಮ್‌ಗಳಲ್ಲಿ ಉದ್ಯೋಗಗಳು. ನಿಮ್ಮ ಸಂಕ್ಷಿಪ್ತ ವಿವರ ಮತ್ತು ರೆಸ್ಯೂಮ್‌ನ ಕೀವರ್ಡ್‌ಗಳನ್ನು ಆಸ್ಪತ್ರೆಗಳ ಅವಶ್ಯಕತೆಯೊಂದಿಗೆ ಹೊಂದಿಸಲಾಗುತ್ತದೆ. ನೋಂದಣಿ 1 ತಿಂಗಳವರೆಗೆ ಮಾನ್ಯ.',
  'Specialisation / post – up to 5 (e.g. MD Medicine, Staff Nurse, Lab Technician)' => 'ವಿಶೇಷತೆ / ಹುದ್ದೆ – 5 ರವರೆಗೆ (ಉದಾ. MD ಮೆಡಿಸಿನ್, ಸ್ಟಾಫ್ ನರ್ಸ್, ಲ್ಯಾಬ್ ತಂತ್ರಜ್ಞ)',
  'Fees (by role, 1 month)' => 'ಶುಲ್ಕಗಳು (ಹುದ್ದೆಯ ಪ್ರಕಾರ, 1 ತಿಂಗಳು)',
  'Doctor: ₹4,500 + GST = ₹5,310' => 'ವೈದ್ಯರು: ₹4,500 + GST = ₹5,310',
  'Front desk / Sales & marketing: ₹1,500 + GST = ₹1,770' => 'ಫ್ರಂಟ್ ಡೆಸ್ಕ್ / ಮಾರಾಟ ಮತ್ತು ಮಾರ್ಕೆಟಿಂಗ್: ₹1,500 + GST = ₹1,770',
  'Sweeper / Housekeeping: ₹500 + GST = ₹590 (one-time)' => 'ಸ್ವೀಪರ್ / ಹೌಸ್‌ಕೀಪಿಂಗ್: ₹500 + GST = ₹590 (ಒಂದು ಬಾರಿ)',
  'Other hospital staff: ₹600 + GST = ₹708' => 'ಇತರ ಆಸ್ಪತ್ರೆ ಸಿಬ್ಬಂದಿ: ₹600 + GST = ₹708',
  'Your Role' => 'ನಿಮ್ಮ ಹುದ್ದೆ',
  'Role you are registering for' => 'ನೀವು ನೋಂದಾಯಿಸುತ್ತಿರುವ ಹುದ್ದೆ',
  'Medical / Nursing Council registration no. (for doctors / nurses)' => 'ವೈದ್ಯಕೀಯ / ನರ್ಸಿಂಗ್ ಕೌನ್ಸಿಲ್ ನೋಂದಣಿ ಸಂಖ್ಯೆ (ವೈದ್ಯರು / ನರ್ಸ್‌ಗಳಿಗೆ)',
  'Brief – your skills, departments, shifts (these keywords are matched)' => 'ಸಂಕ್ಷಿಪ್ತ ವಿವರ – ನಿಮ್ಮ ಕೌಶಲ್ಯಗಳು, ವಿಭಾಗಗಳು, ಶಿಫ್ಟ್‌ಗಳು (ಈ ಕೀವರ್ಡ್‌ಗಳನ್ನು ಹೊಂದಿಸಲಾಗುತ್ತದೆ)',
  'Resume (PDF/DOC, max 5MB) – its keywords are matched too' => 'ರೆಸ್ಯೂಮ್ (PDF/DOC, ಗರಿಷ್ಠ 5MB) – ಅದರ ಕೀವರ್ಡ್‌ಗಳನ್ನೂ ಹೊಂದಿಸಲಾಗುತ್ತದೆ',
  'The fee is non-refundable and the registration is valid for 1 month from payment.' => 'ಶುಲ್ಕವನ್ನು ಮರುಪಾವತಿಸಲಾಗುವುದಿಲ್ಲ ಮತ್ತು ನೋಂದಣಿ ಪಾವತಿಯ ದಿನದಿಂದ 1 ತಿಂಗಳವರೆಗೆ ಮಾನ್ಯ.',
  'I agree that paying hospitals / clinics can see my profile, resume and contact details.' => 'ಪಾವತಿಸುವ ಆಸ್ಪತ್ರೆಗಳು / ಕ್ಲಿನಿಕ್‌ಗಳು ನನ್ನ ಪ್ರೊಫೈಲ್, ರೆಸ್ಯೂಮ್ ಮತ್ತು ಸಂಪರ್ಕ ವಿವರಗಳನ್ನು ನೋಡಬಹುದು ಎಂಬುದಕ್ಕೆ ನಾನು ಒಪ್ಪುತ್ತೇನೆ.',
  'For 1 month your profile is shown to hospitals whose needs match your keywords.' => '1 ತಿಂಗಳವರೆಗೆ, ನಿಮ್ಮ ಕೀವರ್ಡ್‌ಗಳಿಗೆ ಹೊಂದುವ ಅವಶ್ಯಕತೆಯಿರುವ ಆಸ್ಪತ್ರೆಗಳಿಗೆ ನಿಮ್ಮ ಪ್ರೊಫೈಲ್ ತೋರಿಸಲಾಗುತ್ತದೆ.',
  'Hospitals will contact you directly by call / email.' => 'ಆಸ್ಪತ್ರೆಗಳು ನಿಮ್ಮನ್ನು ನೇರವಾಗಿ ಕರೆ / ಇಮೇಲ್ ಮೂಲಕ ಸಂಪರ್ಕಿಸುತ್ತವೆ.',
  'Hospital / Clinic – Hire Doctors & Staff' => 'ಆಸ್ಪತ್ರೆ / ಕ್ಲಿನಿಕ್ – ವೈದ್ಯರು ಮತ್ತು ಸಿಬ್ಬಂದಿಯನ್ನು ನೇಮಿಸಿ',
  'Need doctors or hospital staff? Register here' => 'ವೈದ್ಯರು ಅಥವಾ ಆಸ್ಪತ್ರೆ ಸಿಬ್ಬಂದಿ ಬೇಕೇ? ಇಲ್ಲಿ ನೋಂದಾಯಿಸಿ',
  'Describe your need – we match your keywords with candidates’ briefs and resumes. One-time fee; see names, numbers, emails and resumes for 15 days.' => 'ನಿಮ್ಮ ಅವಶ್ಯಕತೆಯನ್ನು ವಿವರಿಸಿ – ನಿಮ್ಮ ಕೀವರ್ಡ್‌ಗಳನ್ನು ಅಭ್ಯರ್ಥಿಗಳ ಸಂಕ್ಷಿಪ್ತ ವಿವರ ಮತ್ತು ರೆಸ್ಯೂಮ್‌ಗಳೊಂದಿಗೆ ಹೊಂದಿಸುತ್ತೇವೆ. ಒಂದು ಬಾರಿಯ ಶುಲ್ಕ; 15 ದಿನಗಳವರೆಗೆ ಹೆಸರುಗಳು, ಸಂಖ್ಯೆಗಳು, ಇಮೇಲ್‌ಗಳು ಮತ್ತು ರೆಸ್ಯೂಮ್‌ಗಳನ್ನು ನೋಡಿ.',
  'Specialisation / post needed – up to 5' => 'ಅಗತ್ಯವಿರುವ ವಿಶೇಷತೆ / ಹುದ್ದೆ – 5 ರವರೆಗೆ',
  'Fees (one-time, valid 15 days)' => 'ಶುಲ್ಕಗಳು (ಒಂದು ಬಾರಿ, 15 ದಿನಗಳವರೆಗೆ ಮಾನ್ಯ)',
  'Doctors: ₹11,000 + 18% GST = ₹12,980' => 'ವೈದ್ಯರು: ₹11,000 + 18% GST = ₹12,980',
  'Sweeper / Housekeeping: ₹5,000 + GST = ₹5,900' => 'ಸ್ವೀಪರ್ / ಹೌಸ್‌ಕೀಪಿಂಗ್: ₹5,000 + GST = ₹5,900',
  'Hospital / Clinic' => 'ಆಸ್ಪತ್ರೆ / ಕ್ಲಿನಿಕ್',
  'Type of organisation' => 'ಸಂಸ್ಥೆಯ ಪ್ರಕಾರ',
  'Hospital' => 'ಆಸ್ಪತ್ರೆ',
  'Clinic' => 'ಕ್ಲಿನಿಕ್',
  'Nursing Home' => 'ನರ್ಸಿಂಗ್ ಹೋಮ್',
  'Diagnostic / Lab' => 'ರೋಗನಿರ್ಣಯ / ಲ್ಯಾಬ್',
  'Pharmacy' => 'ಔಷಧಾಲಯ (ಫಾರ್ಮಸಿ)',
  'Hospital / Clinic Name' => 'ಆಸ್ಪತ್ರೆ / ಕ್ಲಿನಿಕ್ ಹೆಸರು',
  'Clinical establishment / registration no.' => 'ಕ್ಲಿನಿಕಲ್ ಸಂಸ್ಥೆ / ನೋಂದಣಿ ಸಂಖ್ಯೆ',
  'Contact Person Name' => 'ಸಂಪರ್ಕ ವ್ಯಕ್ತಿಯ ಹೆಸರು',
  'Designation' => 'ಹುದ್ದೆ (ಪದನಾಮ)',
  'Address & PIN Code' => 'ವಿಳಾಸ ಮತ್ತು PIN ಕೋಡ್',
  'Who You Need' => 'ನಿಮಗೆ ಯಾರು ಬೇಕು',
  'Role to hire' => 'ನೇಮಿಸಬೇಕಾದ ಹುದ್ದೆ',
  'Number of positions' => 'ಹುದ್ದೆಗಳ ಸಂಖ್ಯೆ',
  'Brief requirement – department, qualification, shift (these keywords are matched)' => 'ಸಂಕ್ಷಿಪ್ತ ಅವಶ್ಯಕತೆ – ವಿಭಾಗ, ವಿದ್ಯಾರ್ಹತೆ, ಶಿಫ್ಟ್ (ಈ ಕೀವರ್ಡ್‌ಗಳನ್ನು ಹೊಂದಿಸಲಾಗುತ್ತದೆ)',
  'Salary offered (₹ per month)' => 'ನೀಡುವ ವೇತನ (ತಿಂಗಳಿಗೆ ₹)',
  'The information is true and I am authorised on behalf of this organisation.' => 'ಮಾಹಿತಿ ಸತ್ಯವಾಗಿದೆ ಮತ್ತು ಈ ಸಂಸ್ಥೆಯ ಪರವಾಗಿ ನಾನು ಅಧಿಕೃತನಾಗಿದ್ದೇನೆ.',
  'The fee is non-refundable; access is valid for 15 days from payment.' => 'ಶುಲ್ಕವನ್ನು ಮರುಪಾವತಿಸಲಾಗುವುದಿಲ್ಲ; ಪ್ರವೇಶವು ಪಾವತಿಯ ದಿನದಿಂದ 15 ದಿನಗಳವರೆಗೆ ಮಾನ್ಯ.',
  'Candidates’ details will be used only for hiring and never shared or sold.' => 'ಅಭ್ಯರ್ಥಿಗಳ ವಿವರಗಳನ್ನು ನೇಮಕಾತಿಗೆ ಮಾತ್ರ ಬಳಸಲಾಗುತ್ತದೆ ಮತ್ತು ಎಂದಿಗೂ ಹಂಚಿಕೊಳ್ಳುವುದಿಲ್ಲ ಅಥವಾ ಮಾರಾಟ ಮಾಡುವುದಿಲ್ಲ.',
  'See matching candidates now – with name, mobile, email and resume (15 days).' => 'ಈಗಲೇ ಹೊಂದುವ ಅಭ್ಯರ್ಥಿಗಳನ್ನು ನೋಡಿ – ಹೆಸರು, ಮೊಬೈಲ್, ಇಮೇಲ್ ಮತ್ತು ರೆಸ್ಯೂಮ್‌ನೊಂದಿಗೆ (15 ದಿನಗಳು).',
  'Hire Part-time People – Talent Pass (2 days)' => 'ಅರೆಕಾಲಿಕ ಸಿಬ್ಬಂದಿಯನ್ನು ನೇಮಿಸಿ – ಟ್ಯಾಲೆಂಟ್ ಪಾಸ್ (2 ದಿನಗಳು)',
  'Need exhibition staff, models, bouncers, drivers? 2-day pass' => 'ಪ್ರದರ್ಶನ ಸಿಬ್ಬಂದಿ, ಮಾಡೆಲ್‌ಗಳು, ಬೌನ್ಸರ್‌ಗಳು, ಚಾಲಕರು ಬೇಕೇ? 2-ದಿನದ ಪಾಸ್',
  'For ₹5,000 + 18% GST (₹5,900), search part-time candidates by resume keywords for 2 days and contact them directly.' => '₹5,000 + 18% GST (₹5,900) ಗೆ, 2 ದಿನಗಳವರೆಗೆ ರೆಸ್ಯೂಮ್ ಕೀವರ್ಡ್‌ಗಳ ಮೂಲಕ ಅರೆಕಾಲಿಕ ಅಭ್ಯರ್ಥಿಗಳನ್ನು ಹುಡುಕಿ ಮತ್ತು ಅವರನ್ನು ನೇರವಾಗಿ ಸಂಪರ್ಕಿಸಿ.',
  'Work you are hiring for – up to 5' => 'ನೀವು ನೇಮಿಸುತ್ತಿರುವ ಕೆಲಸ – 5 ರವರೆಗೆ',
  '₹5,000 + 18% GST = ₹5,900, valid for 2 days (48 hours) from payment.' => '₹5,000 + 18% GST = ₹5,900, ಪಾವತಿಯ ಸಮಯದಿಂದ 2 ದಿನಗಳವರೆಗೆ (48 ಗಂಟೆಗಳು) ಮಾನ್ಯ.',
  'Search by work, city / PIN, hours, days and resume keywords.' => 'ಕೆಲಸ, ನಗರ / PIN, ಗಂಟೆಗಳು, ದಿನಗಳು ಮತ್ತು ರೆಸ್ಯೂಮ್ ಕೀವರ್ಡ್‌ಗಳ ಮೂಲಕ ಹುಡುಕಿ.',
  'Individual' => 'ವೈಯಕ್ತಿಕ',
  'Institution' => 'ಸಂಸ್ಥೆ',
  'Event / exhibition agency' => 'ಕಾರ್ಯಕ್ರಮ / ಪ್ರದರ್ಶನ ಏಜೆನ್ಸಿ',
  'Company / institution name (if any)' => 'ಕಂಪನಿ / ಸಂಸ್ಥೆಯ ಹೆಸರು (ಇದ್ದರೆ)',
  'Your Name' => 'ನಿಮ್ಮ ಹೆಸರು',
  'PIN Code' => 'PIN ಕೋಡ್',
  'Your Requirement' => 'ನಿಮ್ಮ ಅವಶ್ಯಕತೆ',
  'Brief – dates, hours, venue, how many people' => 'ಸಂಕ್ಷಿಪ್ತ ವಿವರ – ದಿನಾಂಕಗಳು, ಗಂಟೆಗಳು, ಸ್ಥಳ, ಎಷ್ಟು ಜನರು',
  '₹5,900 (₹5,000 + GST) is non-refundable; access lasts 2 days from payment.' => '₹5,900 (₹5,000 + GST) ಮರುಪಾವತಿಸಲಾಗುವುದಿಲ್ಲ; ಪ್ರವೇಶವು ಪಾವತಿಯ ಸಮಯದಿಂದ 2 ದಿನಗಳವರೆಗೆ ಇರುತ್ತದೆ.',
  'Open “Talent Search” now and find candidates by keyword (2 days).' => 'ಈಗಲೇ “ಟ್ಯಾಲೆಂಟ್ ಸರ್ಚ್” ತೆರೆಯಿರಿ ಮತ್ತು ಕೀವರ್ಡ್ ಮೂಲಕ ಅಭ್ಯರ್ಥಿಗಳನ್ನು ಹುಡುಕಿ (2 ದಿನಗಳು).',
  'Indian Railways' => 'ಭಾರತೀಯ ರೈಲ್ವೆ',
  'Army / Navy / Air Force' => 'ಭೂಸೇನೆ / ನೌಕಾಪಡೆ / ವಾಯುಪಡೆ',
  'Police / Paramilitary' => 'ಪೊಲೀಸ್ / ಅರೆಸೇನಾ ಪಡೆ',
  'Central Govt (UPSC, SSC…)' => 'ಕೇಂದ್ರ ಸರ್ಕಾರ (UPSC, SSC…)',
  'State Govts' => 'ರಾಜ್ಯ ಸರ್ಕಾರಗಳು',
  'Banks' => 'ಬ್ಯಾಂಕುಗಳು',
  'Top private companies (Reliance, Tata…)' => 'ಪ್ರಮುಖ ಖಾಸಗಿ ಕಂಪನಿಗಳು (Reliance, Tata…)',
  'Prominent Person 1 (President / Secretary / Director)' => 'ಪ್ರಮುಖ ವ್ಯಕ್ತಿ 1 (ಅಧ್ಯಕ್ಷರು / ಕಾರ್ಯದರ್ಶಿ / ನಿರ್ದೇಶಕರು)',
  'NGO / Social Organisation Registration' => 'NGO / ಸಾಮಾಜಿಕ ಸಂಸ್ಥೆ ನೋಂದಣಿ',
  'For NGOs looking for Social Service People – Register Here' => 'ಸಮಾಜ ಸೇವಕರನ್ನು ಹುಡುಕುತ್ತಿರುವ NGO ಗಳಿಗೆ – ಇಲ್ಲಿ ನೋಂದಾಯಿಸಿ',
  'Organisations looking for social service people register once for ₹155. After payment our team verifies your details. Social service applicants pay nothing.' => 'ಸಮಾಜ ಸೇವಕರನ್ನು ಹುಡುಕುತ್ತಿರುವ ಸಂಸ್ಥೆಗಳು ₹155 ಕ್ಕೆ ಒಮ್ಮೆ ನೋಂದಾಯಿಸುತ್ತವೆ. ಪಾವತಿಯ ನಂತರ ನಮ್ಮ ತಂಡ ನಿಮ್ಮ ವಿವರಗಳನ್ನು ಪರಿಶೀಲಿಸುತ್ತದೆ. ಸಮಾಜ ಸೇವೆಯ ಅರ್ಜಿದಾರರು ಏನನ್ನೂ ಪಾವತಿಸುವುದಿಲ್ಲ.',
  'Social service job applicants never pay any fee.' => 'ಸಮಾಜ ಸೇವಾ ಉದ್ಯೋಗ ಅರ್ಜಿದಾರರು ಎಂದಿಗೂ ಯಾವುದೇ ಶುಲ್ಕ ಪಾವತಿಸುವುದಿಲ್ಲ.',
  'One organisation = one email + one mobile + one registration / GST number.' => 'ಒಂದು ಸಂಸ್ಥೆ = ಒಂದು ಇಮೇಲ್ + ಒಂದು ಮೊಬೈಲ್ + ಒಂದು ನೋಂದಣಿ / GST ಸಂಖ್ಯೆ.',
  'After payment the Jobsence team verifies your organisation’s details and documents; your profile shows “Verified” only after verification.' => 'ಪಾವತಿಯ ನಂತರ Jobsence ತಂಡ ನಿಮ್ಮ ಸಂಸ್ಥೆಯ ವಿವರಗಳು ಮತ್ತು ದಾಖಲೆಗಳನ್ನು ಪರಿಶೀಲಿಸುತ್ತದೆ; ಪರಿಶೀಲನೆಯ ನಂತರವೇ ನಿಮ್ಮ ಪ್ರೊಫೈಲ್‌ನಲ್ಲಿ “ಪರಿಶೀಲಿತ” ಎಂದು ತೋರಿಸುತ್ತದೆ.',
  'Social service roles you need people for (search the list)' => 'ನಿಮಗೆ ಜನರು ಬೇಕಾಗಿರುವ ಸಮಾಜ ಸೇವಾ ಹುದ್ದೆಗಳು (ಪಟ್ಟಿಯಲ್ಲಿ ಹುಡುಕಿ)',
  'Organisation Details' => 'ಸಂಸ್ಥೆಯ ವಿವರಗಳು',
  'Organisation Name (as registered)' => 'ಸಂಸ್ಥೆಯ ಹೆಸರು (ನೋಂದಾಯಿಸಿದಂತೆ)',
  'Type of Organisation' => 'ಸಂಸ್ಥೆಯ ಪ್ರಕಾರ',
  'Trust' => 'ಟ್ರಸ್ಟ್',
  'Society' => 'ಸೊಸೈಟಿ',
  'Section 8 Company' => 'ಸೆಕ್ಷನ್ 8 ಕಂಪನಿ',
