  'Women Empowerment' => 'ಮಹಿಳಾ ಸಬಲೀಕರಣ',
  'Child Welfare' => 'ಮಕ್ಕಳ ಕಲ್ಯಾಣ',
  'Elderly Care' => 'ವೃದ್ಧರ ಆರೈಕೆ',
  'Disability Support' => 'ಅಂಗವಿಕಲರ ಬೆಂಬಲ',
  'Environment' => 'ಪರಿಸರ',
  'Rural Development' => 'ಗ್ರಾಮೀಣಾಭಿವೃದ್ಧಿ',
  'Livelihood / Skills' => 'ಜೀವನೋಪಾಯ / ಕೌಶಲ್ಯಗಳು',
  'Animal Welfare' => 'ಪ್ರಾಣಿ ಕಲ್ಯಾಣ',
  'Disaster Relief' => 'ವಿಪತ್ತು ಪರಿಹಾರ',
  'Registration Number (Trust / Society / CIN)' => 'ನೋಂದಣಿ ಸಂಖ್ಯೆ (ಟ್ರಸ್ಟ್ / ಸೊಸೈಟಿ / CIN)',
  'NGO Darpan ID (if any)' => 'NGO ದರ್ಪಣ್ ID (ಇದ್ದರೆ)',
  'GST Number' => 'GST ಸಂಖ್ಯೆ',
  'Organisation PAN (if any)' => 'ಸಂಸ್ಥೆಯ PAN (ಇದ್ದರೆ)',
  'Tax Registrations' => 'ತೆರಿಗೆ ನೋಂದಣಿಗಳು',
  'Year Established' => 'ಸ್ಥಾಪನೆಯ ವರ್ಷ',
  'Website / Social media (if any)' => 'ವೆಬ್‌ಸೈಟ್ / ಸಾಮಾಜಿಕ ಮಾಧ್ಯಮ (ಇದ್ದರೆ)',
  'About the organisation (work, reach, beneficiaries)' => 'ಸಂಸ್ಥೆಯ ಬಗ್ಗೆ (ಕೆಲಸ, ವ್ಯಾಪ್ತಿ, ಫಲಾನುಭವಿಗಳು)',
  'Contact (OTP will be sent to email)' => 'ಸಂಪರ್ಕ (OTP ಅನ್ನು ಇಮೇಲ್‌ಗೆ ಕಳುಹಿಸಲಾಗುತ್ತದೆ)',
  'Mobile Number (WhatsApp)' => 'ಮೊಬೈಲ್ ಸಂಖ್ಯೆ (WhatsApp)',
  'Organisation Email' => 'ಸಂಸ್ಥೆಯ ಇಮೇಲ್',
  'Prominent Persons' => 'ಪ್ರಮುಖ ವ್ಯಕ್ತಿಗಳು',
  'People You Are Looking For' => 'ನೀವು ಹುಡುಕುತ್ತಿರುವ ಜನರು',
  'Where the work is (cities / districts)' => 'ಕೆಲಸ ಎಲ್ಲಿದೆ (ನಗರಗಳು / ಜಿಲ್ಲೆಗಳು)',
  'All organisation details are true and I am authorised to register on behalf of the organisation.' => 'ಸಂಸ್ಥೆಯ ಎಲ್ಲಾ ವಿವರಗಳು ಸತ್ಯವಾಗಿವೆ ಮತ್ತು ಸಂಸ್ಥೆಯ ಪರವಾಗಿ ನೋಂದಾಯಿಸಲು ನಾನು ಅಧಿಕೃತನಾಗಿದ್ದೇನೆ.',
  'The one-time registration fee of ₹155 (including GST) is non-refundable.' => '₹155 (GST ಸೇರಿ) ಒಂದು ಬಾರಿಯ ನೋಂದಣಿ ಶುಲ್ಕವನ್ನು ಮರುಪಾವತಿಸಲಾಗುವುದಿಲ್ಲ.',
  'After payment Jobsence will verify the documents; registrations with false information may be cancelled.' => 'ಪಾವತಿಯ ನಂತರ Jobsence ದಾಖಲೆಗಳನ್ನು ಪರಿಶೀಲಿಸುತ್ತದೆ; ತಪ್ಪು ಮಾಹಿತಿಯಿರುವ ನೋಂದಣಿಗಳನ್ನು ರದ್ದುಗೊಳಿಸಬಹುದು.',
  'We will not charge social service applicants any fee.' => 'ಸಮಾಜ ಸೇವಾ ಅರ್ಜಿದಾರರಿಂದ ನಾವು ಯಾವುದೇ ಶುಲ್ಕ ಪಡೆಯುವುದಿಲ್ಲ.',
  'The Jobsence team will verify your organisation’s details and documents.' => 'Jobsence ತಂಡ ನಿಮ್ಮ ಸಂಸ್ಥೆಯ ವಿವರಗಳು ಮತ್ತು ದಾಖಲೆಗಳನ್ನು ಪರಿಶೀಲಿಸುತ್ತದೆ.',
  'Once verified you will receive an email and can start connecting with social service people.' => 'ಪರಿಶೀಲನೆಯಾದ ನಂತರ ನಿಮಗೆ ಇಮೇಲ್ ಬರುತ್ತದೆ ಮತ್ತು ನೀವು ಸಮಾಜ ಸೇವಕರೊಂದಿಗೆ ಸಂಪರ್ಕ ಸಾಧಿಸಲು ಪ್ರಾರಂಭಿಸಬಹುದು.',
  'Full Name / Contact Person' => 'ಪೂರ್ಣ ಹೆಸರು / ಸಂಪರ್ಕ ವ್ಯಕ್ತಿ',
  'Aadhaar Number (individual mentor / contact person)' => 'ಆಧಾರ್ ಸಂಖ್ಯೆ (ವೈಯಕ್ತಿಕ ಮಾರ್ಗದರ್ಶಕರು / ಸಂಪರ್ಕ ವ್ಯಕ್ತಿ)',
  'Mandatory only for an individual mentor / trainer; optional for groups, institutes, PSUs and Govt bodies. We store only the last 4 digits.' => 'ವೈಯಕ್ತಿಕ ಮಾರ್ಗದರ್ಶಕರು / ತರಬೇತುದಾರರಿಗೆ ಮಾತ್ರ ಕಡ್ಡಾಯ; ಗುಂಪುಗಳು, ಸಂಸ್ಥೆಗಳು, PSU ಗಳು ಮತ್ತು ಸರ್ಕಾರಿ ಸಂಸ್ಥೆಗಳಿಗೆ ಐಚ್ಛಿಕ. ನಾವು ಕೊನೆಯ 4 ಅಂಕಿಗಳನ್ನು ಮಾತ್ರ ಸಂಗ್ರಹಿಸುತ್ತೇವೆ.',
  'Mentor Enrolment Form – Jobsence Skill Development Team' => 'ಮಾರ್ಗದರ್ಶಕರ ನೋಂದಣಿ ಫಾರ್ಮ್ – Jobsence ಕೌಶಲ್ಯ ಅಭಿವೃದ್ಧಿ ತಂಡ',
  'For Skill Providers / Mentors / Training Institutes – Register Here' => 'ಕೌಶಲ್ಯ ಒದಗಿಸುವವರು / ಮಾರ್ಗದರ್ಶಕರು / ತರಬೇತಿ ಸಂಸ್ಥೆಗಳಿಗೆ – ಇಲ್ಲಿ ನೋಂದಾಯಿಸಿ',
  'What You Will Get & Important Conditions' => 'ನಿಮಗೆ ಏನು ಸಿಗುತ್ತದೆ ಮತ್ತು ಪ್ರಮುಖ ಷರತ್ತುಗಳು',
  'Fixed emolument (fixed payment) per candidate – for video / online classes and for offline classes (Delhi-NCR).' => 'ಪ್ರತಿ ಅಭ್ಯರ್ಥಿಗೆ ನಿಗದಿತ ಗೌರವಧನ (ನಿಗದಿತ ಪಾವತಿ) – ವೀಡಿಯೊ / ಆನ್‌ಲೈನ್ ತರಗತಿಗಳಿಗೆ ಮತ್ತು ಆಫ್‌ಲೈನ್ ತರಗತಿಗಳಿಗೆ (ದೆಹಲಿ-NCR).',
  'Payment is given only after successful completion of the candidate’s training.' => 'ಅಭ್ಯರ್ಥಿಯ ತರಬೇತಿ ಯಶಸ್ವಿಯಾಗಿ ಪೂರ್ಣಗೊಂಡ ನಂತರವೇ ಪಾವತಿ ನೀಡಲಾಗುತ್ತದೆ.',
  'You must send your details with a demo video. The video must clearly mention: “This video is for Jobsence Skill Development”.' => 'ನೀವು ನಿಮ್ಮ ವಿವರಗಳನ್ನು ಡೆಮೊ ವೀಡಿಯೊದೊಂದಿಗೆ ಕಳುಹಿಸಬೇಕು. ವೀಡಿಯೊದಲ್ಲಿ ಸ್ಪಷ್ಟವಾಗಿ ಹೀಗೆ ಉಲ್ಲೇಖಿಸಬೇಕು: “ಈ ವೀಡಿಯೊ Jobsence ಕೌಶಲ್ಯ ಅಭಿವೃದ್ಧಿಗಾಗಿ”.',
  'All videos will be the property of Jobsence – you cannot use them anywhere else.' => 'ಎಲ್ಲಾ ವೀಡಿಯೊಗಳು Jobsence ನ ಸ್ವತ್ತು ಆಗಿರುತ್ತವೆ – ನೀವು ಅವುಗಳನ್ನು ಬೇರೆಲ್ಲೂ ಬಳಸುವಂತಿಲ್ಲ.',
  'You must follow Jobsence rules & guidelines.' => 'ನೀವು Jobsence ನಿಯಮಗಳು ಮತ್ತು ಮಾರ್ಗಸೂಚಿಗಳನ್ನು ಪಾಲಿಸಬೇಕು.',
  '20% of what Jobsence receives from candidates goes to skill development agencies / mentors; the rest (after company operating expenses) is used to build Jobsence’s own skill development centre.' => 'ಅಭ್ಯರ್ಥಿಗಳಿಂದ Jobsence ಪಡೆಯುವ ಮೊತ್ತದ 20% ಕೌಶಲ್ಯ ಅಭಿವೃದ್ಧಿ ಏಜೆನ್ಸಿಗಳು / ಮಾರ್ಗದರ್ಶಕರಿಗೆ ಹೋಗುತ್ತದೆ; ಉಳಿದದ್ದನ್ನು (ಕಂಪನಿಯ ನಿರ್ವಹಣಾ ವೆಚ್ಚಗಳ ನಂತರ) Jobsence ನ ಸ್ವಂತ ಕೌಶಲ್ಯ ಅಭಿವೃದ್ಧಿ ಕೇಂದ್ರ ನಿರ್ಮಿಸಲು ಬಳಸಲಾಗುತ್ತದೆ.',
  'Training institutes, PSUs and government bodies can also offer skill development.' => 'ತರಬೇತಿ ಸಂಸ್ಥೆಗಳು, PSU ಗಳು ಮತ್ತು ಸರ್ಕಾರಿ ಸಂಸ್ಥೆಗಳು ಸಹ ಕೌಶಲ್ಯ ಅಭಿವೃದ್ಧಿ ನೀಡಬಹುದು.',
  'Skills you can teach (search 3000+ list, select multiple)' => 'ನೀವು ಕಲಿಸಬಹುದಾದ ಕೌಶಲ್ಯಗಳು (3000+ ಪಟ್ಟಿಯಲ್ಲಿ ಹುಡುಕಿ, ಹಲವು ಆಯ್ಕೆಮಾಡಿ)',
  'Who Are You' => 'ನೀವು ಯಾರು',
  'Registering As' => 'ಈ ರೂಪದಲ್ಲಿ ನೋಂದಾಯಿಸುತ್ತಿದ್ದೀರಿ',
  'Individual Mentor / Trainer' => 'ವೈಯಕ್ತಿಕ ಮಾರ್ಗದರ್ಶಕರು / ತರಬೇತುದಾರರು',
  'Group Mentoring' => 'ಗುಂಪು ಮಾರ್ಗದರ್ಶನ',
  'Training Institute / Skill Provider' => 'ತರಬೇತಿ ಸಂಸ್ಥೆ / ಕೌಶಲ್ಯ ಒದಗಿಸುವವರು',
  'PSU (Public Sector Undertaking)' => 'PSU (ಸಾರ್ವಜನಿಕ ವಲಯದ ಉದ್ಯಮ)',
  'Government Department / Body' => 'ಸರ್ಕಾರಿ ಇಲಾಖೆ / ಸಂಸ್ಥೆ',
  'Institute / PSU / Department name (not for individual mentors)' => 'ಸಂಸ್ಥೆ / PSU / ಇಲಾಖೆಯ ಹೆಸರು (ವೈಯಕ್ತಿಕ ಮಾರ್ಗದರ್ಶಕರಿಗೆ ಅಲ್ಲ)',
  'GST is not mandatory for an individual mentor / trainer or group mentoring.' => 'ವೈಯಕ್ತಿಕ ಮಾರ್ಗದರ್ಶಕರು / ತರಬೇತುದಾರರು ಅಥವಾ ಗುಂಪು ಮಾರ್ಗದರ್ಶನಕ್ಕೆ GST ಕಡ್ಡಾಯವಲ್ಲ.',
  'What You Can Teach' => 'ನೀವು ಏನನ್ನು ಕಲಿಸಬಹುದು',
  'Mode You Prefer' => 'ನಿಮ್ಮ ಆದ್ಯತೆಯ ವಿಧಾನ',
  'Only Online / Video' => 'ಆನ್‌ಲೈನ್ / ವೀಡಿಯೊ ಮಾತ್ರ',
  'Only Offline (Delhi-NCR)' => 'ಆಫ್‌ಲೈನ್ ಮಾತ್ರ (ದೆಹಲಿ-NCR)',
  'Both' => 'ಎರಡೂ',
  'Experience in Teaching / Working (Years)' => 'ಬೋಧನೆ / ಕೆಲಸದ ಅನುಭವ (ವರ್ಷಗಳು)',
  'Languages You Can Teach' => 'ನೀವು ಕಲಿಸಬಹುದಾದ ಭಾಷೆಗಳು',
  'Brief education & experience (qualification, where you worked / taught)' => 'ಸಂಕ್ಷಿಪ್ತ ಶಿಕ್ಷಣ ಮತ್ತು ಅನುಭವ (ವಿದ್ಯಾರ್ಹತೆ, ನೀವು ಎಲ್ಲಿ ಕೆಲಸ ಮಾಡಿದ್ದೀರಿ / ಕಲಿಸಿದ್ದೀರಿ)',
  'Certifications / Licences (if any)' => 'ಪ್ರಮಾಣಪತ್ರಗಳು / ಪರವಾನಗಿಗಳು (ಇದ್ದರೆ)',
  'Upload documents / certificates (PDF/JPG/PNG/DOC, max 5MB)' => 'ದಾಖಲೆಗಳು / ಪ್ರಮಾಣಪತ್ರಗಳನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಿ (PDF/JPG/PNG/DOC, ಗರಿಷ್ಠ 5MB)',
  'Expected Emolument per candidate ₹ (optional)' => 'ಪ್ರತಿ ಅಭ್ಯರ್ಥಿಗೆ ನಿರೀಕ್ಷಿತ ಗೌರವಧನ ₹ (ಐಚ್ಛಿಕ)',
  'Upload Demo Video (mandatory – MP4/MOV/WEBM, max 200MB)' => 'ಡೆಮೊ ವೀಡಿಯೊ ಅಪ್‌ಲೋಡ್ ಮಾಡಿ (ಕಡ್ಡಾಯ – MP4/MOV/WEBM, ಗರಿಷ್ಠ 200MB)',
  'The video must show / say “This video is for Jobsence”. If the file is too large, give a Google Drive / YouTube (Unlisted) link below.' => 'ವೀಡಿಯೊದಲ್ಲಿ “ಈ ವೀಡಿಯೊ Jobsence ಗಾಗಿ” ಎಂದು ತೋರಿಸಬೇಕು / ಹೇಳಬೇಕು. ಫೈಲ್ ತುಂಬಾ ದೊಡ್ಡದಾಗಿದ್ದರೆ, ಕೆಳಗೆ Google Drive / YouTube (Unlisted) ಲಿಂಕ್ ನೀಡಿ.',
  'Or video link (Google Drive / YouTube Unlisted)' => 'ಅಥವಾ ವೀಡಿಯೊ ಲಿಂಕ್ (Google Drive / YouTube Unlisted)',
  'Bank Details (for payment)' => 'ಬ್ಯಾಂಕ್ ವಿವರಗಳು (ಪಾವತಿಗಾಗಿ)',
  'Account Holder Name' => 'ಖಾತೆದಾರರ ಹೆಸರು',
  'Bank Account Number (outside India: account number / IBAN)' => 'ಬ್ಯಾಂಕ್ ಖಾತೆ ಸಂಖ್ಯೆ (ಭಾರತದ ಹೊರಗೆ: ಖಾತೆ ಸಂಖ್ಯೆ / IBAN)',
  'Your account number is stored encrypted.' => 'ನಿಮ್ಮ ಖಾತೆ ಸಂಖ್ಯೆಯನ್ನು ಎನ್‌ಕ್ರಿಪ್ಟ್ ಮಾಡಿ ಸಂಗ್ರಹಿಸಲಾಗುತ್ತದೆ.',
  'IFSC Code (outside India: SWIFT / BIC code)' => 'IFSC ಕೋಡ್ (ಭಾರತದ ಹೊರಗೆ: SWIFT / BIC ಕೋಡ್)',
  'I agree that all videos submitted by me will be the sole property of Jobsence.' => 'ನಾನು ಸಲ್ಲಿಸುವ ಎಲ್ಲಾ ವೀಡಿಯೊಗಳು Jobsence ನ ಏಕೈಕ ಸ್ವತ್ತು ಆಗಿರುತ್ತವೆ ಎಂಬುದಕ್ಕೆ ನಾನು ಒಪ್ಪುತ್ತೇನೆ.',
  'I will not use these videos anywhere else.' => 'ನಾನು ಈ ವೀಡಿಯೊಗಳನ್ನು ಬೇರೆಲ್ಲೂ ಬಳಸುವುದಿಲ್ಲ.',
  'I will follow all rules of Jobsence.' => 'ನಾನು Jobsence ನ ಎಲ್ಲಾ ನಿಯಮಗಳನ್ನು ಪಾಲಿಸುತ್ತೇನೆ.',
  'I understand that emolument will be paid per candidate only after successful training.' => 'ಯಶಸ್ವಿ ತರಬೇತಿಯ ನಂತರವೇ ಪ್ರತಿ ಅಭ್ಯರ್ಥಿಗೆ ಗೌರವಧನ ಪಾವತಿಸಲಾಗುತ್ತದೆ ಎಂದು ನಾನು ಅರ್ಥಮಾಡಿಕೊಂಡಿದ್ದೇನೆ.',
  'Registration is free. To connect with candidates (full profile, agreement, contact) a paid plan of ₹155 (incl. GST) is needed – 30 days, 3 profiles a day; USD 5 for mentors living outside India.' => 'ನೋಂದಣಿ ಉಚಿತ. ಅಭ್ಯರ್ಥಿಗಳೊಂದಿಗೆ ಸಂಪರ್ಕ ಸಾಧಿಸಲು (ಪೂರ್ಣ ಪ್ರೊಫೈಲ್, ಒಪ್ಪಂದ, ಸಂಪರ್ಕ) ₹155 (GST ಸೇರಿ) ಪಾವತಿ ಯೋಜನೆ ಅಗತ್ಯ – 30 ದಿನಗಳು, ದಿನಕ್ಕೆ 3 ಪ್ರೊಫೈಲ್‌ಗಳು; ಭಾರತದ ಹೊರಗೆ ವಾಸಿಸುವ ಮಾರ್ಗದರ್ಶಕರಿಗೆ USD 5.',
  'There is no guarantee of selection; work will be given as per requirement.' => 'ಆಯ್ಕೆಯ ಯಾವುದೇ ಖಾತರಿ ಇಲ್ಲ; ಅವಶ್ಯಕತೆಗೆ ಅನುಗುಣವಾಗಿ ಕೆಲಸ ನೀಡಲಾಗುತ್ತದೆ.',
  'The Jobsence team will review your form and video – after verification candidates can see you.' => 'Jobsence ತಂಡ ನಿಮ್ಮ ಫಾರ್ಮ್ ಮತ್ತು ವೀಡಿಯೊವನ್ನು ಪರಿಶೀಲಿಸುತ್ತದೆ – ಪರಿಶೀಲನೆಯ ನಂತರ ಅಭ್ಯರ್ಥಿಗಳು ನಿಮ್ಮನ್ನು ನೋಡಬಹುದು.',
  'Open “My mentoring dashboard” now: see who wants to learn which skill and get the ₹155 plan (USD 5 outside India).' => 'ಈಗಲೇ “ನನ್ನ ಮಾರ್ಗದರ್ಶನ ಡ್ಯಾಶ್‌ಬೋರ್ಡ್” ತೆರೆಯಿರಿ: ಯಾರು ಯಾವ ಕೌಶಲ್ಯ ಕಲಿಯಲು ಬಯಸುತ್ತಾರೆ ಎಂದು ನೋಡಿ ಮತ್ತು ₹155 ಯೋಜನೆ ಪಡೆಯಿರಿ (ಭಾರತದ ಹೊರಗೆ USD 5).',
  'If selected, you will be added to the Jobsence Mentor Team; work will be given as per requirement.' => 'ಆಯ್ಕೆಯಾದರೆ, ನಿಮ್ಮನ್ನು Jobsence ಮಾರ್ಗದರ್ಶಕರ ತಂಡಕ್ಕೆ ಸೇರಿಸಲಾಗುತ್ತದೆ; ಅವಶ್ಯಕತೆಗೆ ಅನುಗುಣವಾಗಿ ಕೆಲಸ ನೀಡಲಾಗುತ್ತದೆ.',
  'Payment will be released per candidate after training completion.' => 'ತರಬೇತಿ ಪೂರ್ಣಗೊಂಡ ನಂತರ ಪ್ರತಿ ಅಭ್ಯರ್ಥಿಗೆ ಪಾವತಿ ಬಿಡುಗಡೆ ಮಾಡಲಾಗುತ್ತದೆ.',
  'Morning' => 'ಬೆಳಿಗ್ಗೆ',
  'Afternoon' => 'ಮಧ್ಯಾಹ್ನ',
  'Evening' => 'ಸಂಜೆ',
  'Weekends only' => 'ವಾರಾಂತ್ಯದಲ್ಲಿ ಮಾತ್ರ',
  '3 days – ₹216 (₹183 + GST)' => '3 ದಿನಗಳು – ₹216 (₹183 + GST)',
  '7 days – ₹504 (₹427 + GST)' => '7 ದಿನಗಳು – ₹504 (₹427 + GST)',
  '15 days – ₹1,080 (₹915 + GST)' => '15 ದಿನಗಳು – ₹1,080 (₹915 + GST)',
  '1 month – ₹2,158 (₹1,829 + GST)' => '1 ತಿಂಗಳು – ₹2,158 (₹1,829 + GST)',
  '6 months (half-yearly) – ₹10,791 (₹9,145 + GST)' => '6 ತಿಂಗಳು (ಅರ್ಧವಾರ್ಷಿಕ) – ₹10,791 (₹9,145 + GST)',
  '1 year – ₹19,424 (₹16,461 + GST)' => '1 ವರ್ಷ – ₹19,424 (₹16,461 + GST)',
  '1 day – USD 12' => '1 ದಿನ – USD 12',
  '3 days – USD 30' => '3 ದಿನಗಳು – USD 30',
  '7 days – USD 60' => '7 ದಿನಗಳು – USD 60',
  '15 days – USD 110' => '15 ದಿನಗಳು – USD 110',
  '1 month – USD 200' => '1 ತಿಂಗಳು – USD 200',
  '6 months (half-yearly) – USD 1,000' => '6 ತಿಂಗಳು (ಅರ್ಧವಾರ್ಷಿಕ) – USD 1,000',
  '1 year – USD 1,800' => '1 ವರ್ಷ – USD 1,800',
  'My registration stays valid until I get a suitable mentor / internship provider.' => 'ನನಗೆ ಸೂಕ್ತ ಮಾರ್ಗದರ್ಶಕರು / ಇಂಟರ್ನ್‌ಶಿಪ್ ಒದಗಿಸುವವರು ಸಿಗುವವರೆಗೆ ನನ್ನ ನೋಂದಣಿ ಮಾನ್ಯವಾಗಿರುತ್ತದೆ.',
  'If I reject my mentor / provider after the agreement is signed, I must pay the form fee again for a new registration.' => 'ಒಪ್ಪಂದಕ್ಕೆ ಸಹಿ ಮಾಡಿದ ನಂತರ ನಾನು ನನ್ನ ಮಾರ್ಗದರ್ಶಕರು / ಒದಗಿಸುವವರನ್ನು ತಿರಸ್ಕರಿಸಿದರೆ, ಹೊಸ ನೋಂದಣಿಗಾಗಿ ನಾನು ಫಾರ್ಮ್ ಶುಲ್ಕವನ್ನು ಮತ್ತೆ ಪಾವತಿಸಬೇಕು.',
  'Phone numbers and emails are shown only after a tripartite agreement between candidate, provider and Jobsence (signed with email OTP).' => 'ಅಭ್ಯರ್ಥಿ, ಒದಗಿಸುವವರು ಮತ್ತು Jobsence ನಡುವಿನ ತ್ರಿಪಕ್ಷೀಯ ಒಪ್ಪಂದದ (ಇಮೇಲ್ OTP ಮೂಲಕ ಸಹಿ) ನಂತರವೇ ಫೋನ್ ಸಂಖ್ಯೆಗಳು ಮತ್ತು ಇಮೇಲ್‌ಗಳನ್ನು ತೋರಿಸಲಾಗುತ್ತದೆ.',
  'Internship Provider Registration (free)' => 'ಇಂಟರ್ನ್‌ಶಿಪ್ ಒದಗಿಸುವವರ ನೋಂದಣಿ (ಉಚಿತ)',
  'Companies offering Internship – Register free' => 'ಇಂಟರ್ನ್‌ಶಿಪ್ ನೀಡುವ ಕಂಪನಿಗಳು – ಉಚಿತವಾಗಿ ನೋಂದಾಯಿಸಿ',
  'Register free and see who wants an internship in which domain. To connect: ₹155 plan (USD 5 outside India) – 10 days, 3 profiles a day, up to 20 candidates.' => 'ಉಚಿತವಾಗಿ ನೋಂದಾಯಿಸಿ ಮತ್ತು ಯಾರು ಯಾವ ಕ್ಷೇತ್ರದಲ್ಲಿ ಇಂಟರ್ನ್‌ಶಿಪ್ ಬಯಸುತ್ತಾರೆ ಎಂದು ನೋಡಿ. ಸಂಪರ್ಕಕ್ಕಾಗಿ: ₹155 ಯೋಜನೆ (ಭಾರತದ ಹೊರಗೆ USD 5) – 10 ದಿನಗಳು, ದಿನಕ್ಕೆ 3 ಪ್ರೊಫೈಲ್‌ಗಳು, ಗರಿಷ್ಠ 20 ಅಭ್ಯರ್ಥಿಗಳು.',
  'Internship domains you offer (search the list)' => 'ನೀವು ನೀಡುವ ಇಂಟರ್ನ್‌ಶಿಪ್ ಕ್ಷೇತ್ರಗಳು (ಪಟ್ಟಿಯಲ್ಲಿ ಹುಡುಕಿ)',
  'Organisation' => 'ಸಂಸ್ಥೆ',
  'Institute' => 'ಸಂಸ್ಥೆ (ಶಿಕ್ಷಣ ಸಂಸ್ಥೆ)',
  'Individual / Professional' => 'ವೈಯಕ್ತಿಕ / ವೃತ್ತಿಪರ',
  'Company / Organisation name' => 'ಕಂಪನಿ / ಸಂಸ್ಥೆಯ ಹೆಸರು',
  'Website (if any)' => 'ವೆಬ್‌ಸೈಟ್ (ಇದ್ದರೆ)',
  'Internships' => 'ಇಂಟರ್ನ್‌ಶಿಪ್‌ಗಳು',
  'Where' => 'ಎಲ್ಲಿ',
  'Paid or unpaid' => 'ಪಾವತಿಸಿದ ಅಥವಾ ಪಾವತಿರಹಿತ',
  'Paid' => 'ಪಾವತಿಸಿದ',
  'Stipend (₹ per month) – ₹8,000 to ₹5,00,000 for paid' => 'ಸ್ಟೈಪೆಂಡ್ (ತಿಂಗಳಿಗೆ ₹) – ಪಾವತಿಸಿದ್ದಕ್ಕೆ ₹8,000 ರಿಂದ ₹5,00,000',
  'Number of interns' => 'ಇಂಟರ್ನ್‌ಗಳ ಸಂಖ್ಯೆ',
  'About the internship (work, skills needed, duration)' => 'ಇಂಟರ್ನ್‌ಶಿಪ್ ಬಗ್ಗೆ (ಕೆಲಸ, ಅಗತ್ಯವಿರುವ ಕೌಶಲ್ಯಗಳು, ಅವಧಿ)',
  'Paid internships will pay a stipend of ₹8,000 to ₹5,00,000 per month.' => 'ಪಾವತಿಸಿದ ಇಂಟರ್ನ್‌ಶಿಪ್‌ಗಳು ತಿಂಗಳಿಗೆ ₹8,000 ರಿಂದ ₹5,00,000 ಸ್ಟೈಪೆಂಡ್ ನೀಡುತ್ತವೆ.',
  'Candidates’ details will be used only for the internship and never shared or sold.' => 'ಅಭ್ಯರ್ಥಿಗಳ ವಿವರಗಳನ್ನು ಇಂಟರ್ನ್‌ಶಿಪ್‌ಗೆ ಮಾತ್ರ ಬಳಸಲಾಗುತ್ತದೆ ಮತ್ತು ಎಂದಿಗೂ ಹಂಚಿಕೊಳ್ಳುವುದಿಲ್ಲ ಅಥವಾ ಮಾರಾಟ ಮಾಡುವುದಿಲ್ಲ.',
  'The Jobsence team will verify your details – after that candidates can see you.' => 'Jobsence ತಂಡ ನಿಮ್ಮ ವಿವರಗಳನ್ನು ಪರಿಶೀಲಿಸುತ್ತದೆ – ಅದರ ನಂತರ ಅಭ್ಯರ್ಥಿಗಳು ನಿಮ್ಮನ್ನು ನೋಡಬಹುದು.',
  'Open “My mentoring dashboard” now and get the ₹155 plan (USD 5 outside India; 10 days, 3 profiles a day, up to 20).' => 'ಈಗಲೇ “ನನ್ನ ಮಾರ್ಗದರ್ಶನ ಡ್ಯಾಶ್‌ಬೋರ್ಡ್” ತೆರೆಯಿರಿ ಮತ್ತು ₹155 ಯೋಜನೆ ಪಡೆಯಿರಿ (ಭಾರತದ ಹೊರಗೆ USD 5; 10 ದಿನಗಳು, ದಿನಕ್ಕೆ 3 ಪ್ರೊಫೈಲ್‌ಗಳು, ಗರಿಷ್ಠ 20).',
  'Companies Hiring – Free Registration' => 'ನೇಮಕಾತಿ ಮಾಡುತ್ತಿರುವ ಕಂಪನಿಗಳು – ಉಚಿತ ನೋಂದಣಿ',
  'Companies & shops offering jobs – Register free' => 'ಉದ್ಯೋಗ ನೀಡುವ ಕಂಪನಿಗಳು ಮತ್ತು ಅಂಗಡಿಗಳು – ಉಚಿತವಾಗಿ ನೋಂದಾಯಿಸಿ',
  'Register free and see who is ready for which job. To connect, a hiring plan: from ₹216 (3 days) to ₹19,424 (1 year) – 3, 7, 15 days, 1 month, 6 months or 1 year; outside India from USD 12 (1 day) – 3 full profiles with resume a day.' => 'ಉಚಿತವಾಗಿ ನೋಂದಾಯಿಸಿ ಮತ್ತು ಯಾರು ಯಾವ ಉದ್ಯೋಗಕ್ಕೆ ಸಿದ್ಧರಿದ್ದಾರೆ ಎಂದು ನೋಡಿ. ಸಂಪರ್ಕಕ್ಕಾಗಿ ನೇಮಕಾತಿ ಯೋಜನೆ: ₹216 (3 ದಿನಗಳು) ರಿಂದ ₹19,424 (1 ವರ್ಷ) ವರೆಗೆ – 3, 7, 15 ದಿನಗಳು, 1 ತಿಂಗಳು, 6 ತಿಂಗಳು ಅಥವಾ 1 ವರ್ಷ; ಭಾರತದ ಹೊರಗೆ USD 12 (1 ದಿನ) ರಿಂದ – ದಿನಕ್ಕೆ ರೆಸ್ಯೂಮ್ ಸಹಿತ 3 ಪೂರ್ಣ ಪ್ರೊಫೈಲ್‌ಗಳು.',
  'Roles you hire for (search the list)' => 'ನೀವು ನೇಮಿಸುವ ಹುದ್ದೆಗಳು (ಪಟ್ಟಿಯಲ್ಲಿ ಹುಡುಕಿ)',
  'Shop / MSME / Factory' => 'ಅಂಗಡಿ / MSME / ಕಾರ್ಖಾನೆ',
  'School / College / Institute' => 'ಶಾಲೆ / ಕಾಲೇಜು / ಸಂಸ್ಥೆ',
  'Individual / Household' => 'ವೈಯಕ್ತಿಕ / ಮನೆ',
  'Company / shop / organisation name' => 'ಕಂಪನಿ / ಅಂಗಡಿ / ಸಂಸ್ಥೆಯ ಹೆಸರು',
  'Where are these jobs located' => 'ಈ ಉದ್ಯೋಗಗಳು ಎಲ್ಲಿವೆ',
  'In India (fees in ₹)' => 'ಭಾರತದಲ್ಲಿ (ಶುಲ್ಕ ₹ ನಲ್ಲಿ)',
  'Outside India (fees in USD – payable in ₹ too)' => 'ಭಾರತದ ಹೊರಗೆ (ಶುಲ್ಕ USD ನಲ್ಲಿ – ₹ ನಲ್ಲೂ ಪಾವತಿಸಬಹುದು)',
  'Country of the jobs (for jobs outside India)' => 'ಉದ್ಯೋಗಗಳ ದೇಶ (ಭಾರತದ ಹೊರಗಿನ ಉದ್ಯೋಗಗಳಿಗೆ)',
  'Company / workplace address' => 'ಕಂಪನಿ / ಕೆಲಸದ ಸ್ಥಳದ ವಿಳಾಸ',
  'Jobs' => 'ಉದ್ಯೋಗಗಳು',
  'Job types' => 'ಉದ್ಯೋಗದ ಪ್ರಕಾರಗಳು',
  'Full-time' => 'ಪೂರ್ಣಕಾಲಿಕ',
  'Part-time' => 'ಅರೆಕಾಲಿಕ',
  'One-time work' => 'ಒಂದು ಬಾರಿಯ ಕೆಲಸ',
  'Number of people needed' => 'ಅಗತ್ಯವಿರುವ ಜನರ ಸಂಖ್ಯೆ',
  'Salary (₹ per month / per day)' => 'ವೇತನ (ತಿಂಗಳಿಗೆ / ದಿನಕ್ಕೆ ₹)',
  'About the jobs (work, timings, skills needed)' => 'ಉದ್ಯೋಗಗಳ ಬಗ್ಗೆ (ಕೆಲಸ, ಸಮಯ, ಅಗತ್ಯವಿರುವ ಕೌಶಲ್ಯಗಳು)',
  'I will not take any money from candidates in return for a job.' => 'ಉದ್ಯೋಗಕ್ಕೆ ಬದಲಾಗಿ ನಾನು ಅಭ್ಯರ್ಥಿಗಳಿಂದ ಯಾವುದೇ ಹಣ ಪಡೆಯುವುದಿಲ್ಲ.',
  'The Jobsence team will verify your details – after that job seekers can see you.' => 'Jobsence ತಂಡ ನಿಮ್ಮ ವಿವರಗಳನ್ನು ಪರಿಶೀಲಿಸುತ್ತದೆ – ಅದರ ನಂತರ ಉದ್ಯೋಗಾಕಾಂಕ್ಷಿಗಳು ನಿಮ್ಮನ್ನು ನೋಡಬಹುದು.',
  'Your details have been sent to Jobsence (gm@jobsence.com); companies outside India can write to this email with any questions.' => 'ನಿಮ್ಮ ವಿವರಗಳನ್ನು Jobsence ಗೆ (gm@jobsence.com) ಕಳುಹಿಸಲಾಗಿದೆ; ಭಾರತದ ಹೊರಗಿನ ಕಂಪನಿಗಳು ಯಾವುದೇ ಪ್ರಶ್ನೆಗಳಿಗೆ ಈ ಇಮೇಲ್‌ಗೆ ಬರೆಯಬಹುದು.',
  'Open “My dashboard” now and get a hiring plan – from ₹216 (3 days) to ₹19,424 (1 year) – 3, 7, 15 days, 1 month, 6 months or 1 year; outside India from USD 12 (1 day).' => 'ಈಗಲೇ “ನನ್ನ ಡ್ಯಾಶ್‌ಬೋರ್ಡ್” ತೆರೆಯಿರಿ ಮತ್ತು ನೇಮಕಾತಿ ಯೋಜನೆ ಪಡೆಯಿರಿ – ₹216 (3 ದಿನಗಳು) ರಿಂದ ₹19,424 (1 ವರ್ಷ) ವರೆಗೆ – 3, 7, 15 ದಿನಗಳು, 1 ತಿಂಗಳು, 6 ತಿಂಗಳು ಅಥವಾ 1 ವರ್ಷ; ಭಾರತದ ಹೊರಗೆ USD 12 (1 ದಿನ) ರಿಂದ.',
  'Knowledge cannot be stolen by a thief, seized by a king or divided among brothers, and it is no burden. The more you give it, the more it grows – the wealth of knowledge is the greatest of all wealth.' => 'ವಿದ್ಯೆಯನ್ನು ಕಳ್ಳನು ಕದಿಯಲಾರ, ರಾಜನು ಕಸಿಯಲಾರ, ಸಹೋದರರು ಹಂಚಿಕೊಳ್ಳಲಾರರು, ಮತ್ತು ಅದು ಭಾರವೂ ಅಲ್ಲ. ಅದನ್ನು ಎಷ್ಟು ನೀಡಿದರೂ ಅಷ್ಟು ಬೆಳೆಯುತ್ತದೆ – ವಿದ್ಯಾಧನವೇ ಎಲ್ಲಾ ಧನಗಳಲ್ಲಿ ಶ್ರೇಷ್ಠ.',
  'Sanskrit Subhashita (traditional verse)' => 'ಸಂಸ್ಕೃತ ಸುಭಾಷಿತ (ಸಾಂಪ್ರದಾಯಿಕ ಶ್ಲೋಕ)',
  'Of all gifts, the gift of knowledge is the highest.' => 'ಎಲ್ಲಾ ದಾನಗಳಲ್ಲಿ ವಿದ್ಯಾದಾನವೇ ಶ್ರೇಷ್ಠ.',
  'Manusmriti 4.233' => 'ಮನುಸ್ಮೃತಿ 4.233',
  'In this world there is nothing as purifying as knowledge.' => 'ಈ ಜಗತ್ತಿನಲ್ಲಿ ಜ್ಞಾನದಷ್ಟು ಪವಿತ್ರಗೊಳಿಸುವುದು ಬೇರೆ ಯಾವುದೂ ಇಲ್ಲ.',
  'Bhagavad Gita 4.38' => 'ಭಗವದ್ಗೀತೆ 4.38',
  'Were the whole earth paper, every forest a pen and the seven seas ink, the virtues of a teacher still could not be written.' => 'ಇಡೀ ಭೂಮಿಯೇ ಕಾಗದವಾಗಿ, ಎಲ್ಲಾ ಕಾಡುಗಳು ಲೇಖನಿಯಾಗಿ, ಏಳು ಸಮುದ್ರಗಳು ಮಸಿಯಾದರೂ, ಗುರುವಿನ ಗುಣಗಳನ್ನು ಬರೆದು ಮುಗಿಸಲಾಗದು.',
  'Sant Kabir, Sakhi (Gurudev ko Ang)' => 'ಸಂತ ಕಬೀರ, ಸಾಖಿ (ಗುರುದೇವ್ ಕೋ ಅಂಗ್)',
  'True giving blesses both the one who gives and the one who receives.' => 'ನಿಜವಾದ ದಾನವು ನೀಡುವವರನ್ನೂ ಪಡೆಯುವವರನ್ನೂ ಹರಸುತ್ತದೆ.',
  'William Shakespeare, The Merchant of Venice, Act IV Scene 1 (Portia)' => 'ವಿಲಿಯಂ ಶೇಕ್ಸ್‌ಪಿಯರ್, ದಿ ಮರ್ಚೆಂಟ್ ಆಫ್ ವೆನಿಸ್, ಅಂಕ IV ದೃಶ್ಯ 1 (ಪೋರ್ಷಿಯಾ)',
  'Sharing knowledge takes nothing from the giver – like lighting another candle from your own.' => 'ಜ್ಞಾನವನ್ನು ಹಂಚಿಕೊಳ್ಳುವುದರಿಂದ ನೀಡುವವರಿಗೆ ಏನೂ ಕಡಿಮೆಯಾಗುವುದಿಲ್ಲ – ನಿಮ್ಮ ದೀಪದಿಂದ ಇನ್ನೊಂದು ದೀಪ ಹಚ್ಚಿದಂತೆ.',
  'Thomas Jefferson, letter to Isaac McPherson, 13 August 1813' => 'ಥಾಮಸ್ ಜೆಫರ್ಸನ್, ಐಸಾಕ್ ಮ್ಯಾಕ್‌ಫರ್ಸನ್‌ಗೆ ಬರೆದ ಪತ್ರ, 13 ಆಗಸ್ಟ್ 1813',
  'Never tire of learning, never weary of teaching others.' => 'ಕಲಿಯುವುದರಲ್ಲಿ ಎಂದಿಗೂ ದಣಿಯಬೇಡಿ, ಇತರರಿಗೆ ಕಲಿಸುವುದರಲ್ಲಿ ಎಂದಿಗೂ ಬೇಸರಗೊಳ್ಳಬೇಡಿ.',
  'Confucius, Analects (論語) 7.2 – Shu Er' => 'ಕನ್ಫ್ಯೂಷಿಯಸ್, ಅನಲೆಕ್ಟ್ಸ್ (論語) 7.2 – ಶು ಎರ್',
  'Giving someone a fish is not as good as teaching them to fish.' => 'ಯಾರಿಗಾದರೂ ಮೀನು ಕೊಡುವುದಕ್ಕಿಂತ ಮೀನು ಹಿಡಿಯಲು ಕಲಿಸುವುದು ಉತ್ತಮ.',
  'Traditional Chinese proverb' => 'ಸಾಂಪ್ರದಾಯಿಕ ಚೀನೀ ಗಾದೆ',
  'Iqbal does not despair of his barren field – with a little moisture this soil is very fertile. (Give our youth a little guidance and they will flourish.)' => 'ಇಕ್ಬಾಲ್ ತನ್ನ ಬಂಜರು ಹೊಲದ ಬಗ್ಗೆ ನಿರಾಶನಲ್ಲ – ಸ್ವಲ್ಪ ತೇವಾಂಶ ಸಿಕ್ಕರೆ ಈ ಮಣ್ಣು ಬಹಳ ಫಲವತ್ತಾಗುತ್ತದೆ. (ನಮ್ಮ ಯುವಕರಿಗೆ ಸ್ವಲ್ಪ ಮಾರ್ಗದರ್ಶನ ನೀಡಿ, ಅವರು ಅರಳುತ್ತಾರೆ.)',
  'Allama Iqbal' => 'ಅಲ್ಲಾಮಾ ಇಕ್ಬಾಲ್',
  'When a person dies, their deeds end except three: a continuing charity, knowledge that others keep benefiting from, and a righteous child who prays for them.' => 'ಒಬ್ಬ ವ್ಯಕ್ತಿ ಮರಣ ಹೊಂದಿದಾಗ, ಮೂರನ್ನು ಹೊರತುಪಡಿಸಿ ಅವರ ಎಲ್ಲಾ ಕರ್ಮಗಳು ಕೊನೆಗೊಳ್ಳುತ್ತವೆ: ನಿರಂತರ ದಾನ, ಇತರರಿಗೆ ಪ್ರಯೋಜನ ನೀಡುತ್ತಲೇ ಇರುವ ಜ್ಞಾನ, ಮತ್ತು ಅವರಿಗಾಗಿ ಪ್ರಾರ್ಥಿಸುವ ಸದ್ಗುಣಶೀಲ ಮಗು.',
  'Hadith, Sahih Muslim 1631' => 'ಹದೀಸ್, ಸಹೀಹ್ ಮುಸ್ಲಿಂ 1631',
  'India' => 'ಭಾರತ',
  'Country of residence' => 'ವಾಸದ ದೇಶ',
  'Outside India: give your mobile with country code (e.g. +977) and pick your country instead of a state.' => 'ಭಾರತದ ಹೊರಗೆ: ದೇಶದ ಕೋಡ್‌ನೊಂದಿಗೆ ನಿಮ್ಮ ಮೊಬೈಲ್ ನೀಡಿ (ಉದಾ. +977) ಮತ್ತು ರಾಜ್ಯದ ಬದಲು ನಿಮ್ಮ ದೇಶವನ್ನು ಆಯ್ಕೆಮಾಡಿ.',
  'Jobsence is only a platform. The candidate will double-check every job and employer abroad personally – with that country’s embassy / consulate in India, or directly with that country’s government / labour ministry, and on India’s eMigrate (emigrate.gov.in). Jobsence is not liable for any cheating or fraud.' => 'Jobsence ಕೇವಲ ಒಂದು ವೇದಿಕೆ. ಅಭ್ಯರ್ಥಿಯು ವಿದೇಶದ ಪ್ರತಿ ಉದ್ಯೋಗ ಮತ್ತು ಉದ್ಯೋಗದಾತರನ್ನು ಸ್ವತಃ ಮರುಪರಿಶೀಲಿಸಬೇಕು – ಭಾರತದಲ್ಲಿರುವ ಆ ದೇಶದ ರಾಯಭಾರ ಕಚೇರಿ / ಕಾನ್ಸುಲೇಟ್‌ನೊಂದಿಗೆ, ಅಥವಾ ನೇರವಾಗಿ ಆ ದೇಶದ ಸರ್ಕಾರ / ಕಾರ್ಮಿಕ ಸಚಿವಾಲಯದೊಂದಿಗೆ, ಮತ್ತು ಭಾರತದ eMigrate (emigrate.gov.in) ನಲ್ಲಿ. ಯಾವುದೇ ಮೋಸ ಅಥವಾ ವಂಚನೆಗೆ Jobsence ಹೊಣೆಯಲ್ಲ.',
  'For a job in India, a foreign national must hold a valid Indian employment visa and the mandatory government clearance. The visa, work permit and clearances for any other country are solely the responsibility of the job seeker or the job giver – Jobsence has no role or responsibility in them.' => 'ಭಾರತದಲ್ಲಿ ಉದ್ಯೋಗಕ್ಕಾಗಿ, ವಿದೇಶಿ ಪ್ರಜೆಯು ಮಾನ್ಯವಾದ ಭಾರತೀಯ ಉದ್ಯೋಗ ವೀಸಾ ಮತ್ತು ಕಡ್ಡಾಯ ಸರ್ಕಾರಿ ಅನುಮತಿಯನ್ನು ಹೊಂದಿರಬೇಕು. ಬೇರೆ ಯಾವುದೇ ದೇಶದ ವೀಸಾ, ಕೆಲಸದ ಪರವಾನಗಿ ಮತ್ತು ಅನುಮತಿಗಳು ಸಂಪೂರ್ಣವಾಗಿ ಉದ್ಯೋಗಾಕಾಂಕ್ಷಿ ಅಥವಾ ಉದ್ಯೋಗದಾತರ ಜವಾಬ್ದಾರಿ – ಅವುಗಳಲ್ಲಿ Jobsence ಗೆ ಯಾವುದೇ ಪಾತ್ರ ಅಥವಾ ಜವಾಬ್ದಾರಿ ಇಲ್ಲ.',
  'Jobs Abroad – Free Registration' => 'ವಿದೇಶದಲ್ಲಿ ಉದ್ಯೋಗಗಳು – ಉಚಿತ ನೋಂದಣಿ',
  'Looking for a job abroad? Register free' => 'ವಿದೇಶದಲ್ಲಿ ಉದ್ಯೋಗ ಹುಡುಕುತ್ತಿದ್ದೀರಾ? ಉಚಿತವಾಗಿ ನೋಂದಾಯಿಸಿ',
  'Registration is free. For each country whose employers should see your profile, pay once: ₹1,000 + GST (₹1,180) or USD 10.' => 'ನೋಂದಣಿ ಉಚಿತ. ಯಾವ ದೇಶದ ಉದ್ಯೋಗದಾತರು ನಿಮ್ಮ ಪ್ರೊಫೈಲ್ ನೋಡಬೇಕೋ ಆ ಪ್ರತಿ ದೇಶಕ್ಕೆ ಒಮ್ಮೆ ಪಾವತಿಸಿ: ₹1,000 + GST (₹1,180) ಅಥವಾ USD 10.',
  'Jobs you want – up to 5' => 'ನೀವು ಬಯಸುವ ಉದ್ಯೋಗಗಳು – 5 ರವರೆಗೆ',
  'Each country: one-time ₹1,180 (₹1,000 + 18% GST) or USD 10 – non-refundable in any condition.' => 'ಪ್ರತಿ ದೇಶಕ್ಕೆ: ಒಂದು ಬಾರಿ ₹1,180 (₹1,000 + 18% GST) ಅಥವಾ USD 10 – ಯಾವುದೇ ಸಂದರ್ಭದಲ್ಲೂ ಮರುಪಾವತಿ ಇಲ್ಲ.',
  'A valid passport is mandatory – enter its number and expiry date.' => 'ಮಾನ್ಯವಾದ ಪಾಸ್‌ಪೋರ್ಟ್ ಕಡ್ಡಾಯ – ಅದರ ಸಂಖ್ಯೆ ಮತ್ತು ಮುಕ್ತಾಯ ದಿನಾಂಕವನ್ನು ನಮೂದಿಸಿ.',
  'Jobsence is a platform, not a recruiting agent. ECR passport holders must emigrate only through agents registered on eMigrate (emigrate.gov.in), and should verify every employer there.' => 'Jobsence ಒಂದು ವೇದಿಕೆ, ನೇಮಕಾತಿ ಏಜೆಂಟ್ ಅಲ್ಲ. ECR ಪಾಸ್‌ಪೋರ್ಟ್ ಹೊಂದಿರುವವರು eMigrate (emigrate.gov.in) ನಲ್ಲಿ ನೋಂದಾಯಿತ ಏಜೆಂಟ್‌ಗಳ ಮೂಲಕ ಮಾತ್ರ ವಲಸೆ ಹೋಗಬೇಕು ಮತ್ತು ಪ್ರತಿ ಉದ್ಯೋಗದಾತರನ್ನು ಅಲ್ಲಿ ಪರಿಶೀಲಿಸಬೇಕು.',
  'Residence' => 'ವಾಸಸ್ಥಳ',
  'Full Name (as per passport)' => 'ಪೂರ್ಣ ಹೆಸರು (ಪಾಸ್‌ಪೋರ್ಟ್ ಪ್ರಕಾರ)',
  'Job Abroad' => 'ವಿದೇಶದಲ್ಲಿ ಉದ್ಯೋಗ',
  'Preferred countries (comma separated)' => 'ಆದ್ಯತೆಯ ದೇಶಗಳು (ಅಲ್ಪವಿರಾಮದಿಂದ ಬೇರ್ಪಡಿಸಿ)',
  'e.g. UAE, Saudi Arabia, Canada, Germany' => 'ಉದಾ. UAE, ಸೌದಿ ಅರೇಬಿಯಾ, ಕೆನಡಾ, ಜರ್ಮನಿ',
  'Passport (mandatory)' => 'ಪಾಸ್‌ಪೋರ್ಟ್ (ಕಡ್ಡಾಯ)',
  'Valid passport – ECNR' => 'ಮಾನ್ಯವಾದ ಪಾಸ್‌ಪೋರ್ಟ್ – ECNR',
  'Valid passport – ECR' => 'ಮಾನ್ಯವಾದ ಪಾಸ್‌ಪೋರ್ಟ್ – ECR',
  'Passport number' => 'ಪಾಸ್‌ಪೋರ್ಟ್ ಸಂಖ್ಯೆ',
  'Stored encrypted for your safety.' => 'ನಿಮ್ಮ ಸುರಕ್ಷತೆಗಾಗಿ ಎನ್‌ಕ್ರಿಪ್ಟ್ ಮಾಡಿ ಸಂಗ್ರಹಿಸಲಾಗಿದೆ.',
  'Passport expiry date' => 'ಪಾಸ್‌ಪೋರ್ಟ್ ಮುಕ್ತಾಯ ದಿನಾಂಕ',
  'Expected salary (USD per month)' => 'ನಿರೀಕ್ಷಿತ ವೇತನ (ತಿಂಗಳಿಗೆ USD)',
  'Languages you know' => 'ನಿಮಗೆ ತಿಳಿದಿರುವ ಭಾಷೆಗಳು',
  'About you (skills, experience, certificates)' => 'ನಿಮ್ಮ ಬಗ್ಗೆ (ಕೌಶಲ್ಯಗಳು, ಅನುಭವ, ಪ್ರಮಾಣಪತ್ರಗಳು)',
  'Resume / CV (PDF/DOC, max 5MB)' => 'ರೆಸ್ಯೂಮ್ / CV (PDF/DOC, ಗರಿಷ್ಠ 5MB)',
  'Registration is free; the one-time fee of ₹1,180 or USD 10 per country is non-refundable in any condition.' => 'ನೋಂದಣಿ ಉಚಿತ; ಪ್ರತಿ ದೇಶಕ್ಕೆ ₹1,180 ಅಥವಾ USD 10 ಒಂದು ಬಾರಿಯ ಶುಲ್ಕವನ್ನು ಯಾವುದೇ ಸಂದರ್ಭದಲ್ಲೂ ಮರುಪಾವತಿಸಲಾಗುವುದಿಲ್ಲ.',
  'Jobsence is not a recruiting agent and does not guarantee any job or visa abroad. I will verify the employer and any agent on eMigrate before travelling.' => 'Jobsence ನೇಮಕಾತಿ ಏಜೆಂಟ್ ಅಲ್ಲ ಮತ್ತು ವಿದೇಶದಲ್ಲಿ ಯಾವುದೇ ಉದ್ಯೋಗ ಅಥವಾ ವೀಸಾದ ಖಾತರಿ ನೀಡುವುದಿಲ್ಲ. ಪ್ರಯಾಣಿಸುವ ಮೊದಲು ನಾನು ಉದ್ಯೋಗದಾತರು ಮತ್ತು ಯಾವುದೇ ಏಜೆಂಟ್ ಅನ್ನು eMigrate ನಲ್ಲಿ ಪರಿಶೀಲಿಸುತ್ತೇನೆ.',
  'I will not pay anyone money for a job or visa and will report any such demand to Jobsence.' => 'ಉದ್ಯೋಗ ಅಥವಾ ವೀಸಾಗಾಗಿ ನಾನು ಯಾರಿಗೂ ಹಣ ಪಾವತಿಸುವುದಿಲ್ಲ ಮತ್ತು ಅಂತಹ ಯಾವುದೇ ಬೇಡಿಕೆಯನ್ನು Jobsence ಗೆ ವರದಿ ಮಾಡುತ್ತೇನೆ.',
  'Open “My dashboard” now and unlock the countries where your profile should be shown (₹1,180 or USD 10 each).' => 'ಈಗಲೇ “ನನ್ನ ಡ್ಯಾಶ್‌ಬೋರ್ಡ್” ತೆರೆಯಿರಿ ಮತ್ತು ನಿಮ್ಮ ಪ್ರೊಫೈಲ್ ತೋರಿಸಬೇಕಾದ ದೇಶಗಳನ್ನು ಅನ್‌ಲಾಕ್ ಮಾಡಿ (ಪ್ರತಿಯೊಂದಕ್ಕೆ ₹1,180 ಅಥವಾ USD 10).',
  'Companies hiring in that country see your profile and send a tripartite agreement.' => 'ಆ ದೇಶದಲ್ಲಿ ನೇಮಕಾತಿ ಮಾಡುತ್ತಿರುವ ಕಂಪನಿಗಳು ನಿಮ್ಮ ಪ್ರೊಫೈಲ್ ನೋಡಿ ತ್ರಿಪಕ್ಷೀಯ ಒಪ್ಪಂದ ಕಳುಹಿಸುತ್ತವೆ.',
  'Country unlock – Jobs Abroad' => 'ದೇಶ ಅನ್‌ಲಾಕ್ – ವಿದೇಶದಲ್ಲಿ ಉದ್ಯೋಗಗಳು',
  'Country unlock' => 'ದೇಶ ಅನ್‌ಲಾಕ್',
  'Employers in this country can see your profile.' => 'ಈ ದೇಶದ ಉದ್ಯೋಗದಾತರು ನಿಮ್ಮ ಪ್ರೊಫೈಲ್ ನೋಡಬಹುದು.',
  'Companies hiring in this country can now see your profile.' => 'ಈ ದೇಶದಲ್ಲಿ ನೇಮಕಾತಿ ಮಾಡುತ್ತಿರುವ ಕಂಪನಿಗಳು ಈಗ ನಿಮ್ಮ ಪ್ರೊಫೈಲ್ ನೋಡಬಹುದು.',
  'Open your dashboard to add more countries.' => 'ಇನ್ನಷ್ಟು ದೇಶಗಳನ್ನು ಸೇರಿಸಲು ನಿಮ್ಮ ಡ್ಯಾಶ್‌ಬೋರ್ಡ್ ತೆರೆಯಿರಿ.',
  'Hiring Plan' => 'ನೇಮಕಾತಿ ಯೋಜನೆ',
  'Full profile, resume and agreement for 3 job seekers a day – 3 days (₹216) to 1 year (₹19,424); outside India from USD 12.' => 'ದಿನಕ್ಕೆ 3 ಉದ್ಯೋಗಾಕಾಂಕ್ಷಿಗಳ ಪೂರ್ಣ ಪ್ರೊಫೈಲ್, ರೆಸ್ಯೂಮ್ ಮತ್ತು ಒಪ್ಪಂದ – 3 ದಿನಗಳು (₹216) ರಿಂದ 1 ವರ್ಷ (₹19,424); ಭಾರತದ ಹೊರಗೆ USD 12 ರಿಂದ.',
  'Open candidate profiles from your dashboard and send agreements.' => 'ನಿಮ್ಮ ಡ್ಯಾಶ್‌ಬೋರ್ಡ್‌ನಿಂದ ಅಭ್ಯರ್ಥಿ ಪ್ರೊಫೈಲ್‌ಗಳನ್ನು ತೆರೆಯಿರಿ ಮತ್ತು ಒಪ್ಪಂದಗಳನ್ನು ಕಳುಹಿಸಿ.',
  'Mentor Plan – 30 days' => 'ಮಾರ್ಗದರ್ಶಕರ ಯೋಜನೆ – 30 ದಿನಗಳು',
  'Internship Provider Plan – 10 days' => 'ಇಂಟರ್ನ್‌ಶಿಪ್ ಒದಗಿಸುವವರ ಯೋಜನೆ – 10 ದಿನಗಳು',
  'Mentor Plan' => 'ಮಾರ್ಗದರ್ಶಕರ ಯೋಜನೆ',
  'Internship Plan' => 'ಇಂಟರ್ನ್‌ಶಿಪ್ ಯೋಜನೆ',
  '₹155 (incl. GST; USD 5 outside India): full profile and agreement for 3 candidates a day for 30 days.' => '₹155 (GST ಸೇರಿ; ಭಾರತದ ಹೊರಗೆ USD 5): 30 ದಿನಗಳವರೆಗೆ ದಿನಕ್ಕೆ 3 ಅಭ್ಯರ್ಥಿಗಳ ಪೂರ್ಣ ಪ್ರೊಫೈಲ್ ಮತ್ತು ಒಪ್ಪಂದ.',
  '₹155 (incl. GST; USD 5 outside India): full profile for 3 candidates a day for 10 days, up to 20 in total.' => '₹155 (GST ಸೇರಿ; ಭಾರತದ ಹೊರಗೆ USD 5): 10 ದಿನಗಳವರೆಗೆ ದಿನಕ್ಕೆ 3 ಅಭ್ಯರ್ಥಿಗಳ ಪೂರ್ಣ ಪ್ರೊಫೈಲ್, ಒಟ್ಟು ಗರಿಷ್ಠ 20.',
  'Open candidate profiles from your mentoring dashboard and send agreements.' => 'ನಿಮ್ಮ ಮಾರ್ಗದರ್ಶನ ಡ್ಯಾಶ್‌ಬೋರ್ಡ್‌ನಿಂದ ಅಭ್ಯರ್ಥಿ ಪ್ರೊಫೈಲ್‌ಗಳನ್ನು ತೆರೆಯಿರಿ ಮತ್ತು ಒಪ್ಪಂದಗಳನ್ನು ಕಳುಹಿಸಿ.',
  '5th–8th' => '5ನೇ–8ನೇ ತರಗತಿ',
  'Graduate' => 'ಪದವೀಧರ',
  'Post Graduate / Professional' => 'ಸ್ನಾತಕೋತ್ತರ / ವೃತ್ತಿಪರ',
  'Unemployed' => 'ನಿರುದ್ಯೋಗಿ',
  'Student' => 'ವಿದ್ಯಾರ್ಥಿ',
  'Daily wage worker' => 'ದಿನಗೂಲಿ ಕಾರ್ಮಿಕ',
  'Self-employed (low income)' => 'ಸ್ವಯಂ ಉದ್ಯೋಗಿ (ಕಡಿಮೆ ಆದಾಯ)',
  'Homemaker' => 'ಗೃಹಿಣಿ',
  'Hindi' => 'ಹಿಂದಿ',
  'English' => 'ಇಂಗ್ಲಿಷ್',
  'Local / Regional language' => 'ಸ್ಥಳೀಯ / ಪ್ರಾದೇಶಿಕ ಭಾಷೆ',
  'Mix (as per mentor availability)' => 'ಮಿಶ್ರ (ಮಾರ್ಗದರ್ಶಕರ ಲಭ್ಯತೆಯ ಪ್ರಕಾರ)',
  'Father’s / Mother’s / Guardian’s Name' => 'ತಂದೆ / ತಾಯಿ / ಪೋಷಕರ ಹೆಸರು',
  'Date of Birth' => 'ಹುಟ್ಟಿದ ದಿನಾಂಕ',
  'Gender' => 'ಲಿಂಗ',
  'Male' => 'ಪುರುಷ',
  'Female' => 'ಮಹಿಳೆ',
  'Confirmation email will be sent here.' => 'ದೃಢೀಕರಣ ಇಮೇಲ್ ಅನ್ನು ಇಲ್ಲಿಗೆ ಕಳುಹಿಸಲಾಗುತ್ತದೆ.',
  'Personal Details' => 'ವೈಯಕ್ತಿಕ ವಿವರಗಳು',
  'House / Street / Landmark' => 'ಮನೆ / ರಸ್ತೆ / ಹೆಗ್ಗುರುತು',
  'Village / Town / Locality' => 'ಹಳ್ಳಿ / ಪಟ್ಟಣ / ಬಡಾವಣೆ',
  'Nearest Landmark / Police Station' => 'ಹತ್ತಿರದ ಹೆಗ್ಗುರುತು / ಪೊಲೀಸ್ ಠಾಣೆ',
  'Complete Address' => 'ಪೂರ್ಣ ವಿಳಾಸ',
  'Highest Qualification' => 'ಅತ್ಯುನ್ನತ ವಿದ್ಯಾರ್ಹತೆ',
  'Name of local language (e.g. Bhojpuri, Marathi, Tamil)' => 'ಸ್ಥಳೀಯ ಭಾಷೆಯ ಹೆಸರು (ಉದಾ. ಭೋಜ್‌ಪುರಿ, ಮರಾಠಿ, ತಮಿಳು)',
  'Work Mode' => 'ಕೆಲಸದ ವಿಧಾನ',
  'On-site / Office' => 'ಸ್ಥಳದಲ್ಲೇ / ಕಚೇರಿ',
  'Work from Home' => 'ಮನೆಯಿಂದ ಕೆಲಸ',
  'Preferred Working Hours' => 'ಆದ್ಯತೆಯ ಕೆಲಸದ ಸಮಯ',
  'Morning (6am–12pm)' => 'ಬೆಳಿಗ್ಗೆ (6am–12pm)',
  'Afternoon (12–5pm)' => 'ಮಧ್ಯಾಹ್ನ (12–5pm)',
  'Evening (5–10pm)' => 'ಸಂಜೆ (5–10pm)',
  'Night' => 'ರಾತ್ರಿ',
  'Jobsence is only a platform. We take utmost care to verify the credentials of candidates, but Jobsence will not take any responsibility for cheating, forgery or any mishappening between job seekers and job providers.' => 'Jobsence ಕೇವಲ ಒಂದು ವೇದಿಕೆ. ಅಭ್ಯರ್ಥಿಗಳ ವಿವರಗಳನ್ನು ಪರಿಶೀಲಿಸಲು ನಾವು ಅತ್ಯಂತ ಎಚ್ಚರ ವಹಿಸುತ್ತೇವೆ, ಆದರೆ ಉದ್ಯೋಗಾಕಾಂಕ್ಷಿಗಳು ಮತ್ತು ಉದ್ಯೋಗದಾತರ ನಡುವಿನ ಯಾವುದೇ ಮೋಸ, ನಕಲಿ ಅಥವಾ ಅವಘಡಕ್ಕೆ Jobsence ಯಾವುದೇ ಜವಾಬ್ದಾರಿ ತೆಗೆದುಕೊಳ್ಳುವುದಿಲ್ಲ.',
  'Jobsence will try to share my profile with suitable companies; matching may take time.' => 'Jobsence ನನ್ನ ಪ್ರೊಫೈಲ್ ಅನ್ನು ಸೂಕ್ತ ಕಂಪನಿಗಳೊಂದಿಗೆ ಹಂಚಿಕೊಳ್ಳಲು ಪ್ರಯತ್ನಿಸುತ್ತದೆ; ಹೊಂದಾಣಿಕೆಗೆ ಸಮಯ ತೆಗೆದುಕೊಳ್ಳಬಹುದು.',
  'I agree to be contacted by Jobsence or companies via call / WhatsApp / email.' => 'Jobsence ಅಥವಾ ಕಂಪನಿಗಳು ನನ್ನನ್ನು ಕರೆ / WhatsApp / ಇಮೇಲ್ ಮೂಲಕ ಸಂಪರ್ಕಿಸಲು ನಾನು ಒಪ್ಪುತ್ತೇನೆ.',
  'Our team will review your profile and try to share it with suitable companies.' => 'ನಮ್ಮ ತಂಡ ನಿಮ್ಮ ಪ್ರೊಫೈಲ್ ಅನ್ನು ಪರಿಶೀಲಿಸಿ ಸೂಕ್ತ ಕಂಪನಿಗಳೊಂದಿಗೆ ಹಂಚಿಕೊಳ್ಳಲು ಪ್ರಯತ್ನಿಸುತ್ತದೆ.',
  'Skill seekers' => 'ಕೌಶಲ್ಯ ಬಯಸುವವರು',
  'Mentors / institutes' => 'ಮಾರ್ಗದರ್ಶಕರು / ಸಂಸ್ಥೆಗಳು',
  'Skill Mentoring' => 'ಕೌಶಲ್ಯ ಮಾರ್ಗದರ್ಶನ',
  'Internship seekers' => 'ಇಂಟರ್ನ್‌ಶಿಪ್ ಬಯಸುವವರು',
  'Internship providers' => 'ಇಂಟರ್ನ್‌ಶಿಪ್ ಒದಗಿಸುವವರು',
  'Internship' => 'ಇಂಟರ್ನ್‌ಶಿಪ್',
  'Job seekers' => 'ಉದ್ಯೋಗಾಕಾಂಕ್ಷಿಗಳು',
  'Hiring companies' => 'ನೇಮಕಾತಿ ಕಂಪನಿಗಳು',
  'Job' => 'ಉದ್ಯೋಗ',
  'Service seekers' => 'ಸೇವೆ ಬಯಸುವವರು',
  'Near Me providers' => 'ನಿಯರ್ ಮಿ ಒದಗಿಸುವವರು',
  'Near Me service' => 'ನಿಯರ್ ಮಿ ಸೇವೆ',
  'Only for Jobs Abroad registrations' => 'ವಿದೇಶಿ ಉದ್ಯೋಗ ನೋಂದಣಿಗಳಿಗೆ ಮಾತ್ರ',
  'Enter a valid country other than your own country of residence' => 'ನಿಮ್ಮ ವಾಸದ ದೇಶವನ್ನು ಹೊರತುಪಡಿಸಿ ಮಾನ್ಯವಾದ ದೇಶವನ್ನು ನಮೂದಿಸಿ',
  'This country is already unlocked' => 'ಈ ದೇಶವನ್ನು ಈಗಾಗಲೇ ಅನ್‌ಲಾಕ್ ಮಾಡಲಾಗಿದೆ',
  'Server error, please retry' => 'ಸರ್ವರ್ ದೋಷ, ದಯವಿಟ್ಟು ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ',
  'This profile is not for your type of provider' => 'ಈ ಪ್ರೊಫೈಲ್ ನಿಮ್ಮ ಪ್ರಕಾರದ ಒದಗಿಸುವವರಿಗೆ ಅಲ್ಲ',
  'Your plan’s 20 profiles are used up. Get a new plan.' => 'ನಿಮ್ಮ ಯೋಜನೆಯ 20 ಪ್ರೊಫೈಲ್‌ಗಳು ಮುಗಿದಿವೆ. ಹೊಸ ಯೋಜನೆ ಪಡೆಯಿರಿ.',
  'Today’s 3 profiles are used up – open more tomorrow.' => 'ಇಂದಿನ 3 ಪ್ರೊಫೈಲ್‌ಗಳು ಮುಗಿದಿವೆ – ನಾಳೆ ಇನ್ನಷ್ಟು ತೆರೆಯಿರಿ.',
  'Get a plan to open full profiles and sign agreements (mentors / internships ₹155 – USD 5 outside India, hiring from ₹216)' => 'ಪೂರ್ಣ ಪ್ರೊಫೈಲ್‌ಗಳನ್ನು ತೆರೆಯಲು ಮತ್ತು ಒಪ್ಪಂದಗಳಿಗೆ ಸಹಿ ಮಾಡಲು ಯೋಜನೆ ಪಡೆಯಿರಿ (ಮಾರ್ಗದರ್ಶಕರು / ಇಂಟರ್ನ್‌ಶಿಪ್‌ಗಳು ₹155 – ಭಾರತದ ಹೊರಗೆ USD 5, ನೇಮಕಾತಿ ₹216 ರಿಂದ)',
  'This invite is not possible' => 'ಈ ಆಹ್ವಾನ ಸಾಧ್ಯವಿಲ್ಲ',
  'Your verification by the Jobsence team is pending' => 'Jobsence ತಂಡದಿಂದ ನಿಮ್ಮ ಪರಿಶೀಲನೆ ಬಾಕಿ ಇದೆ',
  'You have already invited this candidate' => 'ನೀವು ಈಗಾಗಲೇ ಈ ಅಭ್ಯರ್ಥಿಯನ್ನು ಆಹ್ವಾನಿಸಿದ್ದೀರಿ',
  'The candidate has been emailed to pay the form fee. Once paid, they appear in your list.' => 'ಫಾರ್ಮ್ ಶುಲ್ಕ ಪಾವತಿಸಲು ಅಭ್ಯರ್ಥಿಗೆ ಇಮೇಲ್ ಕಳುಹಿಸಲಾಗಿದೆ. ಪಾವತಿಸಿದ ನಂತರ, ಅವರು ನಿಮ್ಮ ಪಟ್ಟಿಯಲ್ಲಿ ಕಾಣಿಸುತ್ತಾರೆ.',
  'This request is not possible' => 'ಈ ವಿನಂತಿ ಸಾಧ್ಯವಿಲ್ಲ',
  'Your registration is not open, or you already have a mentor' => 'ನಿಮ್ಮ ನೋಂದಣಿ ತೆರೆದಿಲ್ಲ, ಅಥವಾ ನಿಮಗೆ ಈಗಾಗಲೇ ಮಾರ್ಗದರ್ಶಕರು ಇದ್ದಾರೆ',
  'This candidate is no longer available' => 'ಈ ಅಭ್ಯರ್ಥಿ ಇನ್ನು ಮುಂದೆ ಲಭ್ಯವಿಲ್ಲ',
  'This provider is not verified yet' => 'ಈ ಒದಗಿಸುವವರು ಇನ್ನೂ ಪರಿಶೀಲಿತರಲ್ಲ',
  'Customers request your service – you answer their requests' => 'ಗ್ರಾಹಕರು ನಿಮ್ಮ ಸೇವೆಯನ್ನು ವಿನಂತಿಸುತ್ತಾರೆ – ನೀವು ಅವರ ವಿನಂತಿಗಳಿಗೆ ಉತ್ತರಿಸುತ್ತೀರಿ',
  'Open the candidate’s full profile first' => 'ಮೊದಲು ಅಭ್ಯರ್ಥಿಯ ಪೂರ್ಣ ಪ್ರೊಫೈಲ್ ತೆರೆಯಿರಿ',
  'Agreement not available' => 'ಒಪ್ಪಂದ ಲಭ್ಯವಿಲ್ಲ',
  'This agreement is no longer open' => 'ಈ ಒಪ್ಪಂದ ಇನ್ನು ಮುಂದೆ ತೆರೆದಿಲ್ಲ',
  'This agreement request has expired' => 'ಈ ಒಪ್ಪಂದ ವಿನಂತಿಯ ಅವಧಿ ಮುಗಿದಿದೆ',
  'The candidate’s registration is no longer open' => 'ಅಭ್ಯರ್ಥಿಯ ನೋಂದಣಿ ಇನ್ನು ಮುಂದೆ ತೆರೆದಿಲ್ಲ',
  'Your Near Me listing has expired – renew it first' => 'ನಿಮ್ಮ ನಿಯರ್ ಮಿ ಪಟ್ಟಿಯ ಅವಧಿ ಮುಗಿದಿದೆ – ಮೊದಲು ಅದನ್ನು ನವೀಕರಿಸಿ',
  'Today’s 3 profiles are used up – sign tomorrow' => 'ಇಂದಿನ 3 ಪ್ರೊಫೈಲ್‌ಗಳು ಮುಗಿದಿವೆ – ನಾಳೆ ಸಹಿ ಮಾಡಿ',
  'Agreement complete! You can now see each other’s phone and email.' => 'ಒಪ್ಪಂದ ಪೂರ್ಣಗೊಂಡಿದೆ! ಈಗ ನೀವು ಪರಸ್ಪರರ ಫೋನ್ ಮತ್ತು ಇಮೇಲ್ ನೋಡಬಹುದು.',
  'You have signed. The other party has been emailed to sign.' => 'ನೀವು ಸಹಿ ಮಾಡಿದ್ದೀರಿ. ಸಹಿ ಮಾಡಲು ಇನ್ನೊಂದು ಪಕ್ಷಕ್ಕೆ ಇಮೇಲ್ ಕಳುಹಿಸಲಾಗಿದೆ.',
  'an internship' => 'ಇಂಟರ್ನ್‌ಶಿಪ್',
  'a job / employment' => 'ಉದ್ಯೋಗ / ನೌಕರಿ',
  'a Near Me service' => 'ನಿಯರ್ ಮಿ ಸೇವೆ',
  'skill training / mentoring' => 'ಕೌಶಲ್ಯ ತರಬೇತಿ / ಮಾರ್ಗದರ್ಶನ',
  '3. No guarantee – Jobsence does not guarantee any job, internship, placement, income, training result or quality of service.' => '3. ಖಾತರಿ ಇಲ್ಲ – Jobsence ಯಾವುದೇ ಉದ್ಯೋಗ, ಇಂಟರ್ನ್‌ಶಿಪ್, ನಿಯೋಜನೆ, ಆದಾಯ, ತರಬೇತಿಯ ಫಲಿತಾಂಶ ಅಥವಾ ಸೇವೆಯ ಗುಣಮಟ್ಟದ ಖಾತರಿ ನೀಡುವುದಿಲ್ಲ.',
  '4. Verification – Jobsence makes reasonable efforts to check identity and documents but does not warrant their accuracy. Both parties will make their own checks before work or training starts.' => '4. ಪರಿಶೀಲನೆ – Jobsence ಗುರುತು ಮತ್ತು ದಾಖಲೆಗಳನ್ನು ಪರಿಶೀಲಿಸಲು ಸಮಂಜಸ ಪ್ರಯತ್ನ ಮಾಡುತ್ತದೆ, ಆದರೆ ಅವುಗಳ ನಿಖರತೆಯನ್ನು ಖಾತರಿಪಡಿಸುವುದಿಲ್ಲ. ಕೆಲಸ ಅಥವಾ ತರಬೇತಿ ಪ್ರಾರಂಭವಾಗುವ ಮೊದಲು ಎರಡೂ ಪಕ್ಷಗಳು ತಮ್ಮದೇ ಆದ ಪರಿಶೀಲನೆ ಮಾಡಿಕೊಳ್ಳುತ್ತವೆ.',
  '5. Jobsence fees – no refunds – Every amount paid to Jobsence (form fee, pass, plan, renewal or late fee) is a platform fee for access and matching only and is non-refundable in any condition – including if no match, job, internship or training results, if either party ends the agreement or rejects the provider, if a plan or pass is not used, or if access is suspended for a breach. Only a duplicate or failed payment caused by a technical error (amount debited twice, or debited without a registration being created) is returned to the original payment method. This fee is not the price of any job or training; any salary, stipend, fee or service charge between the parties is agreed between them in writing, and Jobsence is not responsible for it.' => '5. Jobsence ಶುಲ್ಕಗಳು – ಮರುಪಾವತಿ ಇಲ್ಲ – Jobsence ಗೆ ಪಾವತಿಸಿದ ಪ್ರತಿ ಮೊತ್ತ (ಫಾರ್ಮ್ ಶುಲ್ಕ, ಪಾಸ್, ಯೋಜನೆ, ನವೀಕರಣ ಅಥವಾ ವಿಳಂಬ ಶುಲ್ಕ) ಕೇವಲ ಪ್ರವೇಶ ಮತ್ತು ಹೊಂದಾಣಿಕೆಗಾಗಿ ಇರುವ ಪ್ಲಾಟ್‌ಫಾರ್ಮ್ ಶುಲ್ಕವಾಗಿದ್ದು, ಯಾವುದೇ ಸಂದರ್ಭದಲ್ಲೂ ಮರುಪಾವತಿಸಲಾಗುವುದಿಲ್ಲ – ಯಾವುದೇ ಹೊಂದಾಣಿಕೆ, ಉದ್ಯೋಗ, ಇಂಟರ್ನ್‌ಶಿಪ್ ಅಥವಾ ತರಬೇತಿ ಫಲಿತಾಂಶ ಸಿಗದಿದ್ದರೂ, ಯಾವುದೇ ಪಕ್ಷ ಒಪ್ಪಂದವನ್ನು ಕೊನೆಗೊಳಿಸಿದರೂ ಅಥವಾ ಒದಗಿಸುವವರನ್ನು ತಿರಸ್ಕರಿಸಿದರೂ, ಯೋಜನೆ ಅಥವಾ ಪಾಸ್ ಬಳಸದಿದ್ದರೂ, ಅಥವಾ ಉಲ್ಲಂಘನೆಗಾಗಿ ಪ್ರವೇಶವನ್ನು ಅಮಾನತುಗೊಳಿಸಿದರೂ ಸಹ. ತಾಂತ್ರಿಕ ದೋಷದಿಂದ ಉಂಟಾದ ನಕಲಿ ಅಥವಾ ವಿಫಲ ಪಾವತಿ (ಮೊತ್ತ ಎರಡು ಬಾರಿ ಕಡಿತವಾದರೆ, ಅಥವಾ ನೋಂದಣಿ ಸೃಷ್ಟಿಯಾಗದೆ ಕಡಿತವಾದರೆ) ಮಾತ್ರ ಮೂಲ ಪಾವತಿ ವಿಧಾನಕ್ಕೆ ಹಿಂತಿರುಗಿಸಲಾಗುತ್ತದೆ. ಈ ಶುಲ್ಕವು ಯಾವುದೇ ಉದ್ಯೋಗ ಅಥವಾ ತರಬೇತಿಯ ಬೆಲೆಯಲ್ಲ; ಪಕ್ಷಗಳ ನಡುವಿನ ಯಾವುದೇ ವೇತನ, ಸ್ಟೈಪೆಂಡ್, ಶುಲ್ಕ ಅಥವಾ ಸೇವಾ ಶುಲ್ಕವನ್ನು ಅವರ ನಡುವೆ ಲಿಖಿತವಾಗಿ ಒಪ್ಪಿಕೊಳ್ಳಲಾಗುತ್ತದೆ, ಮತ್ತು ಅದಕ್ಕೆ Jobsence ಜವಾಬ್ದಾರಿಯಲ್ಲ.',
  '6. No unlawful charges – The Provider will not ask the Candidate for any money, security deposit or original documents in return for a job or internship, and will not charge more than what is agreed in writing. Report any such demand to Jobsence at once.' => '6. ಕಾನೂನುಬಾಹಿರ ಶುಲ್ಕಗಳಿಲ್ಲ – ಒದಗಿಸುವವರು ಉದ್ಯೋಗ ಅಥವಾ ಇಂಟರ್ನ್‌ಶಿಪ್‌ಗೆ ಬದಲಾಗಿ ಅಭ್ಯರ್ಥಿಯಿಂದ ಯಾವುದೇ ಹಣ, ಭದ್ರತಾ ಠೇವಣಿ ಅಥವಾ ಮೂಲ ದಾಖಲೆಗಳನ್ನು ಕೇಳುವುದಿಲ್ಲ, ಮತ್ತು ಲಿಖಿತವಾಗಿ ಒಪ್ಪಿದ್ದಕ್ಕಿಂತ ಹೆಚ್ಚು ಶುಲ್ಕ ವಿಧಿಸುವುದಿಲ್ಲ. ಅಂತಹ ಯಾವುದೇ ಬೇಡಿಕೆಯನ್ನು ತಕ್ಷಣ Jobsence ಗೆ ವರದಿ ಮಾಡಿ.',
  '7. Personal data – Each party will use the other’s details (phone, email, address, resume) only for this purpose, keep them confidential, never share or sell them, and delete them when no longer needed, in line with the Digital Personal Data Protection Act, 2023. Both parties consent to Jobsence processing their data to provide the service and to keep a record of this agreement.' => '7. ವೈಯಕ್ತಿಕ ಡೇಟಾ – ಪ್ರತಿ ಪಕ್ಷವು ಇನ್ನೊಂದು ಪಕ್ಷದ ವಿವರಗಳನ್ನು (ಫೋನ್, ಇಮೇಲ್, ವಿಳಾಸ, ರೆಸ್ಯೂಮ್) ಈ ಉದ್ದೇಶಕ್ಕೆ ಮಾತ್ರ ಬಳಸುತ್ತದೆ, ಅವುಗಳನ್ನು ಗೌಪ್ಯವಾಗಿಡುತ್ತದೆ, ಎಂದಿಗೂ ಹಂಚಿಕೊಳ್ಳುವುದಿಲ್ಲ ಅಥವಾ ಮಾರಾಟ ಮಾಡುವುದಿಲ್ಲ, ಮತ್ತು ಡಿಜಿಟಲ್ ವೈಯಕ್ತಿಕ ಡೇಟಾ ಸಂರಕ್ಷಣಾ ಕಾಯ್ದೆ, 2023 ಕ್ಕೆ ಅನುಗುಣವಾಗಿ ಅಗತ್ಯವಿಲ್ಲದಾಗ ಅವುಗಳನ್ನು ಅಳಿಸುತ್ತದೆ. ಸೇವೆ ಒದಗಿಸಲು ಮತ್ತು ಈ ಒಪ್ಪಂದದ ದಾಖಲೆ ಇಡಲು Jobsence ತಮ್ಮ ಡೇಟಾವನ್ನು ಸಂಸ್ಕರಿಸಲು ಎರಡೂ ಪಕ್ಷಗಳು ಸಮ್ಮತಿಸುತ್ತವೆ.',
  '8. Fair use of the platform – The Provider will not copy, scrape, bulk-download or reuse candidate information from Jobsence for any other purpose, and will not share its login or links. Breach leads to suspension without refund and, where needed, a report to the authorities.' => '8. ಪ್ಲಾಟ್‌ಫಾರ್ಮ್‌ನ ನ್ಯಾಯಯುತ ಬಳಕೆ – ಒದಗಿಸುವವರು Jobsence ನಿಂದ ಅಭ್ಯರ್ಥಿಗಳ ಮಾಹಿತಿಯನ್ನು ಬೇರೆ ಯಾವುದೇ ಉದ್ದೇಶಕ್ಕಾಗಿ ನಕಲು ಮಾಡುವುದಿಲ್ಲ, ಸ್ಕ್ರೇಪ್ ಮಾಡುವುದಿಲ್ಲ, ಸಾಮೂಹಿಕವಾಗಿ ಡೌನ್‌ಲೋಡ್ ಮಾಡುವುದಿಲ್ಲ ಅಥವಾ ಮರುಬಳಕೆ ಮಾಡುವುದಿಲ್ಲ, ಮತ್ತು ತನ್ನ ಲಾಗಿನ್ ಅಥವಾ ಲಿಂಕ್‌ಗಳನ್ನು ಹಂಚಿಕೊಳ್ಳುವುದಿಲ್ಲ. ಉಲ್ಲಂಘನೆಯಾದರೆ ಮರುಪಾವತಿಯಿಲ್ಲದೆ ಅಮಾನತು ಮತ್ತು ಅಗತ್ಯವಿದ್ದರೆ ಅಧಿಕಾರಿಗಳಿಗೆ ವರದಿ ಮಾಡಲಾಗುತ್ತದೆ.',
  '9. Conduct and safety – Both parties will behave respectfully, lawfully and without discrimination; no harassment. Where applicable, the Sexual Harassment of Women at Workplace Act, 2013 will be followed. First meetings should be at official or public places. A candidate under 18 needs parent / guardian consent, and child labour laws will be followed.' => '9. ನಡವಳಿಕೆ ಮತ್ತು ಸುರಕ್ಷತೆ – ಎರಡೂ ಪಕ್ಷಗಳು ಗೌರವಯುತವಾಗಿ, ಕಾನೂನುಬದ್ಧವಾಗಿ ಮತ್ತು ತಾರತಮ್ಯವಿಲ್ಲದೆ ವರ್ತಿಸುತ್ತವೆ; ಯಾವುದೇ ಕಿರುಕುಳ ಇರಬಾರದು. ಅನ್ವಯವಾಗುವಲ್ಲಿ, ಕೆಲಸದ ಸ್ಥಳದಲ್ಲಿ ಮಹಿಳೆಯರ ಮೇಲಿನ ಲೈಂಗಿಕ ಕಿರುಕುಳ ಕಾಯ್ದೆ, 2013 ಅನ್ನು ಪಾಲಿಸಲಾಗುತ್ತದೆ. ಮೊದಲ ಭೇಟಿಗಳು ಅಧಿಕೃತ ಅಥವಾ ಸಾರ್ವಜನಿಕ ಸ್ಥಳಗಳಲ್ಲಿ ಇರಬೇಕು. 18 ವರ್ಷಕ್ಕಿಂತ ಕಡಿಮೆ ವಯಸ್ಸಿನ ಅಭ್ಯರ್ಥಿಗೆ ಪೋಷಕರು / ರಕ್ಷಕರ ಸಮ್ಮತಿ ಅಗತ್ಯ, ಮತ್ತು ಬಾಲಕಾರ್ಮಿಕ ಕಾನೂನುಗಳನ್ನು ಪಾಲಿಸಲಾಗುತ್ತದೆ.',
  '10. Provider’s legal duties – Compliance with all laws for this work, training or service (labour, minimum wages, stipend, tax, licences, professional registrations, safety) is solely the Provider’s responsibility.' => '10. ಒದಗಿಸುವವರ ಕಾನೂನು ಕರ್ತವ್ಯಗಳು – ಈ ಕೆಲಸ, ತರಬೇತಿ ಅಥವಾ ಸೇವೆಗೆ ಸಂಬಂಧಿಸಿದ ಎಲ್ಲಾ ಕಾನೂನುಗಳ (ಕಾರ್ಮಿಕ, ಕನಿಷ್ಠ ವೇತನ, ಸ್ಟೈಪೆಂಡ್, ತೆರಿಗೆ, ಪರವಾನಗಿಗಳು, ವೃತ್ತಿಪರ ನೋಂದಣಿಗಳು, ಸುರಕ್ಷತೆ) ಪಾಲನೆ ಸಂಪೂರ್ಣವಾಗಿ ಒದಗಿಸುವವರ ಜವಾಬ್ದಾರಿ.',
  '11. Candidate’s duties – The Candidate has given true information, will attend as agreed, will follow the Provider’s reasonable rules, and will inform the Provider and Jobsence before leaving.' => '11. ಅಭ್ಯರ್ಥಿಯ ಕರ್ತವ್ಯಗಳು – ಅಭ್ಯರ್ಥಿಯು ಸತ್ಯ ಮಾಹಿತಿ ನೀಡಿದ್ದಾರೆ, ಒಪ್ಪಿದಂತೆ ಹಾಜರಾಗುತ್ತಾರೆ, ಒದಗಿಸುವವರ ಸಮಂಜಸ ನಿಯಮಗಳನ್ನು ಪಾಲಿಸುತ್ತಾರೆ, ಮತ್ತು ಬಿಟ್ಟು ಹೋಗುವ ಮೊದಲು ಒದಗಿಸುವವರು ಮತ್ತು Jobsence ಗೆ ತಿಳಿಸುತ್ತಾರೆ.',
  '12. Ending the agreement – Either party may end this agreement from the Jobsence dashboard. If the Candidate rejects the Provider after signing, the Candidate’s registration closes and a fresh form fee is payable; if the Provider ends it, the Candidate stays eligible. Jobsence may suspend or end any party’s access without refund for breach, fraud or serious complaints.' => '12. ಒಪ್ಪಂದದ ಮುಕ್ತಾಯ – ಯಾವುದೇ ಪಕ್ಷವು Jobsence ಡ್ಯಾಶ್‌ಬೋರ್ಡ್‌ನಿಂದ ಈ ಒಪ್ಪಂದವನ್ನು ಕೊನೆಗೊಳಿಸಬಹುದು. ಸಹಿ ಮಾಡಿದ ನಂತರ ಅಭ್ಯರ್ಥಿಯು ಒದಗಿಸುವವರನ್ನು ತಿರಸ್ಕರಿಸಿದರೆ, ಅಭ್ಯರ್ಥಿಯ ನೋಂದಣಿ ಮುಚ್ಚಲ್ಪಡುತ್ತದೆ ಮತ್ತು ಹೊಸ ಫಾರ್ಮ್ ಶುಲ್ಕ ಪಾವತಿಸಬೇಕಾಗುತ್ತದೆ; ಒದಗಿಸುವವರು ಕೊನೆಗೊಳಿಸಿದರೆ, ಅಭ್ಯರ್ಥಿ ಅರ್ಹರಾಗಿಯೇ ಉಳಿಯುತ್ತಾರೆ. ಉಲ್ಲಂಘನೆ, ವಂಚನೆ ಅಥವಾ ಗಂಭೀರ ದೂರುಗಳಿಗಾಗಿ Jobsence ಯಾವುದೇ ಪಕ್ಷದ ಪ್ರವೇಶವನ್ನು ಮರುಪಾವತಿಯಿಲ್ಲದೆ ಅಮಾನತುಗೊಳಿಸಬಹುದು ಅಥವಾ ಕೊನೆಗೊಳಿಸಬಹುದು.',
  '13. Limitation of liability – To the extent permitted by law, Jobsence is not liable for any act, omission, fraud, forgery, injury, loss or damage caused by either party. Jobsence’s total liability under this agreement will not exceed the platform fee the claiming party paid to Jobsence for this registration.' => '13. ಹೊಣೆಗಾರಿಕೆಯ ಮಿತಿ – ಕಾನೂನು ಅನುಮತಿಸುವ ಮಟ್ಟಿಗೆ, ಯಾವುದೇ ಪಕ್ಷದಿಂದ ಉಂಟಾದ ಯಾವುದೇ ಕೃತ್ಯ, ಲೋಪ, ವಂಚನೆ, ನಕಲಿ, ಗಾಯ, ನಷ್ಟ ಅಥವಾ ಹಾನಿಗೆ Jobsence ಹೊಣೆಯಲ್ಲ. ಈ ಒಪ್ಪಂದದ ಅಡಿಯಲ್ಲಿ Jobsence ನ ಒಟ್ಟು ಹೊಣೆಗಾರಿಕೆಯು, ಹಕ್ಕು ಮಂಡಿಸುವ ಪಕ್ಷವು ಈ ನೋಂದಣಿಗಾಗಿ Jobsence ಗೆ ಪಾವತಿಸಿದ ಪ್ಲಾಟ್‌ಫಾರ್ಮ್ ಶುಲ್ಕವನ್ನು ಮೀರುವುದಿಲ್ಲ.',
  '14. Indemnity – The Candidate and the Provider will each make good any claim, loss or penalty against Jobsence arising from their own breach, unlawful act or false information.' => '14. ನಷ್ಟಭರ್ತಿ – ಅಭ್ಯರ್ಥಿ ಮತ್ತು ಒದಗಿಸುವವರು ಪ್ರತಿಯೊಬ್ಬರೂ ತಮ್ಮದೇ ಉಲ್ಲಂಘನೆ, ಕಾನೂನುಬಾಹಿರ ಕೃತ್ಯ ಅಥವಾ ತಪ್ಪು ಮಾಹಿತಿಯಿಂದ Jobsence ವಿರುದ್ಧ ಉಂಟಾಗುವ ಯಾವುದೇ ಹಕ್ಕು, ನಷ್ಟ ಅಥವಾ ದಂಡವನ್ನು ಭರಿಸುತ್ತಾರೆ.',
  '16. Disputes and law – This agreement is governed by Indian law. The parties will first try to settle any dispute through the Jobsence grievance process for 30 days. If unresolved, a dispute involving Jobsence will go to a sole arbitrator appointed by agreement of the parties or under the Arbitration and Conciliation Act, 1996; the seat of arbitration is New Delhi. Subject to this, courts at New Delhi have jurisdiction. Rights that cannot be excluded by law (such as consumer rights) are not affected.' => '16. ವಿವಾದಗಳು ಮತ್ತು ಕಾನೂನು – ಈ ಒಪ್ಪಂದವು ಭಾರತೀಯ ಕಾನೂನಿಗೆ ಒಳಪಟ್ಟಿದೆ. ಪಕ್ಷಗಳು ಮೊದಲು ಯಾವುದೇ ವಿವಾದವನ್ನು 30 ದಿನಗಳವರೆಗೆ Jobsence ಕುಂದುಕೊರತೆ ಪ್ರಕ್ರಿಯೆಯ ಮೂಲಕ ಬಗೆಹರಿಸಲು ಪ್ರಯತ್ನಿಸುತ್ತವೆ. ಬಗೆಹರಿಯದಿದ್ದರೆ, Jobsence ಒಳಗೊಂಡ ವಿವಾದವು ಪಕ್ಷಗಳ ಒಪ್ಪಿಗೆಯಿಂದ ಅಥವಾ ಮಧ್ಯಸ್ಥಿಕೆ ಮತ್ತು ಸಂಧಾನ ಕಾಯ್ದೆ, 1996 ರ ಅಡಿಯಲ್ಲಿ ನೇಮಿಸಲಾದ ಏಕೈಕ ಮಧ್ಯಸ್ಥಗಾರರಿಗೆ ಹೋಗುತ್ತದೆ; ಮಧ್ಯಸ್ಥಿಕೆಯ ಸ್ಥಾನ ನವದೆಹಲಿ. ಇದಕ್ಕೆ ಒಳಪಟ್ಟು, ನವದೆಹಲಿಯ ನ್ಯಾಯಾಲಯಗಳಿಗೆ ವ್ಯಾಪ್ತಿ ಇರುತ್ತದೆ. ಕಾನೂನಿನ ಮೂಲಕ ಹೊರಗಿಡಲಾಗದ ಹಕ್ಕುಗಳ (ಗ್ರಾಹಕ ಹಕ್ಕುಗಳಂತಹ) ಮೇಲೆ ಇದು ಪರಿಣಾಮ ಬೀರುವುದಿಲ್ಲ.',
  '17. Electronic signature – This agreement, signed with an email OTP, is a valid electronic contract under Section 10A of the Information Technology Act, 2000. Jobsence countersigns automatically once both have signed and keeps the signing time, IP address and version as evidence.' => '17. ಎಲೆಕ್ಟ್ರಾನಿಕ್ ಸಹಿ – ಇಮೇಲ್ OTP ಮೂಲಕ ಸಹಿ ಮಾಡಿದ ಈ ಒಪ್ಪಂದವು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ಕಾಯ್ದೆ, 2000 ರ ಸೆಕ್ಷನ್ 10A ಅಡಿಯಲ್ಲಿ ಮಾನ್ಯವಾದ ಎಲೆಕ್ಟ್ರಾನಿಕ್ ಒಪ್ಪಂದವಾಗಿದೆ. ಇಬ್ಬರೂ ಸಹಿ ಮಾಡಿದ ನಂತರ Jobsence ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಪ್ರತಿಸಹಿ ಮಾಡುತ್ತದೆ ಮತ್ತು ಸಹಿಯ ಸಮಯ, IP ವಿಳಾಸ ಮತ್ತು ಆವೃತ್ತಿಯನ್ನು ಸಾಕ್ಷ್ಯವಾಗಿ ಇಟ್ಟುಕೊಳ್ಳುತ್ತದೆ.',
  '18. Entire agreement – This agreement, the Jobsence Terms of Use and the Privacy Policy together form the whole agreement for this connection. Jobsence may change the terms for future agreements; the version you signed applies to you. This is not a Government of India scheme.' => '18. ಸಂಪೂರ್ಣ ಒಪ್ಪಂದ – ಈ ಒಪ್ಪಂದ, Jobsence ಬಳಕೆಯ ನಿಯಮಗಳು ಮತ್ತು ಗೌಪ್ಯತಾ ನೀತಿ ಒಟ್ಟಾಗಿ ಈ ಸಂಪರ್ಕಕ್ಕಾಗಿ ಸಂಪೂರ್ಣ ಒಪ್ಪಂದವನ್ನು ರೂಪಿಸುತ್ತವೆ. ಭವಿಷ್ಯದ ಒಪ್ಪಂದಗಳಿಗಾಗಿ Jobsence ನಿಯಮಗಳನ್ನು ಬದಲಾಯಿಸಬಹುದು; ನೀವು ಸಹಿ ಮಾಡಿದ ಆವೃತ್ತಿಯೇ ನಿಮಗೆ ಅನ್ವಯಿಸುತ್ತದೆ. ಇದು ಭಾರತ ಸರ್ಕಾರದ ಯೋಜನೆ ಅಲ್ಲ.',
  '19. Training content – Training material belongs to the Provider / Jobsence; the Candidate will not record or share sessions without permission. Demo videos submitted by mentors are Jobsence property. Mentor emolument is per the Jobsence mentor terms, after successful training.' => '19. ತರಬೇತಿ ವಿಷಯ – ತರಬೇತಿ ಸಾಮಗ್ರಿಯು ಒದಗಿಸುವವರು / Jobsence ಗೆ ಸೇರಿದ್ದು; ಅಭ್ಯರ್ಥಿಯು ಅನುಮತಿಯಿಲ್ಲದೆ ಅವಧಿಗಳನ್ನು ರೆಕಾರ್ಡ್ ಮಾಡುವುದಿಲ್ಲ ಅಥವಾ ಹಂಚಿಕೊಳ್ಳುವುದಿಲ್ಲ. ಮಾರ್ಗದರ್ಶಕರು ಸಲ್ಲಿಸಿದ ಡೆಮೊ ವೀಡಿಯೊಗಳು Jobsence ನ ಸ್ವತ್ತು. ಮಾರ್ಗದರ್ಶಕರ ಗೌರವಧನವು Jobsence ಮಾರ್ಗದರ್ಶಕರ ನಿಯಮಗಳ ಪ್ರಕಾರ, ಯಶಸ್ವಿ ತರಬೇತಿಯ ನಂತರ ಇರುತ್ತದೆ.',
  '19. Internship – A paid internship’s stipend will be between ₹8,000 and ₹5,00,000 a month as declared; work, duration and certificate will be agreed in writing. No fee will be taken from the intern for the internship.' => '19. ಇಂಟರ್ನ್‌ಶಿಪ್ – ಪಾವತಿಸಿದ ಇಂಟರ್ನ್‌ಶಿಪ್‌ನ ಸ್ಟೈಪೆಂಡ್ ಘೋಷಿಸಿದಂತೆ ತಿಂಗಳಿಗೆ ₹8,000 ಮತ್ತು ₹5,00,000 ನಡುವೆ ಇರುತ್ತದೆ; ಕೆಲಸ, ಅವಧಿ ಮತ್ತು ಪ್ರಮಾಣಪತ್ರವನ್ನು ಲಿಖಿತವಾಗಿ ಒಪ್ಪಿಕೊಳ್ಳಲಾಗುತ್ತದೆ. ಇಂಟರ್ನ್‌ಶಿಪ್‌ಗಾಗಿ ಇಂಟರ್ನ್‌ನಿಂದ ಯಾವುದೇ ಶುಲ್ಕ ಪಡೆಯಲಾಗುವುದಿಲ್ಲ.',
  '19. Job – The Provider confirms the vacancy is genuine and lawful, the pay is not below the applicable minimum wage, and the appointment letter / terms will be given in writing.' => '19. ಉದ್ಯೋಗ – ಹುದ್ದೆಯು ನಿಜವಾದ ಮತ್ತು ಕಾನೂನುಬದ್ಧವಾಗಿದೆ, ವೇತನವು ಅನ್ವಯವಾಗುವ ಕನಿಷ್ಠ ವೇತನಕ್ಕಿಂತ ಕಡಿಮೆಯಿಲ್ಲ, ಮತ್ತು ನೇಮಕಾತಿ ಪತ್ರ / ನಿಯಮಗಳನ್ನು ಲಿಖಿತವಾಗಿ ನೀಡಲಾಗುತ್ತದೆ ಎಂದು ಒದಗಿಸುವವರು ದೃಢೀಕರಿಸುತ್ತಾರೆ.',
  '19. Service – Scope, price, materials and timing are agreed before work starts; the Customer pays the Provider directly; workmanship and safety are the Provider’s responsibility. Jobsence is not a party to the service contract itself.' => '19. ಸೇವೆ – ಕೆಲಸ ಪ್ರಾರಂಭವಾಗುವ ಮೊದಲು ವ್ಯಾಪ್ತಿ, ಬೆಲೆ, ಸಾಮಗ್ರಿಗಳು ಮತ್ತು ಸಮಯವನ್ನು ಒಪ್ಪಿಕೊಳ್ಳಲಾಗುತ್ತದೆ; ಗ್ರಾಹಕರು ಒದಗಿಸುವವರಿಗೆ ನೇರವಾಗಿ ಪಾವತಿಸುತ್ತಾರೆ; ಕೆಲಸದ ಗುಣಮಟ್ಟ ಮತ್ತು ಸುರಕ್ಷತೆ ಒದಗಿಸುವವರ ಜವಾಬ್ದಾರಿ. Jobsence ಸೇವಾ ಒಪ್ಪಂದದಲ್ಲಿ ಸ್ವತಃ ಪಕ್ಷವಲ್ಲ.',
  'Jobsence is only a platform and facilitator; Jobsence does not guarantee any job, placement or outcome.' => 'Jobsence ಕೇವಲ ಒಂದು ವೇದಿಕೆ ಮತ್ತು ಸಹಾಯಕ; Jobsence ಯಾವುದೇ ಉದ್ಯೋಗ, ನಿಯೋಜನೆ ಅಥವಾ ಫಲಿತಾಂಶದ ಖಾತರಿ ನೀಡುವುದಿಲ್ಲ.',
  'Both parties will use each other’s phone number and email only for this purpose and will not share them with anyone else.' => 'ಎರಡೂ ಪಕ್ಷಗಳು ಪರಸ್ಪರರ ಫೋನ್ ಸಂಖ್ಯೆ ಮತ್ತು ಇಮೇಲ್ ಅನ್ನು ಈ ಉದ್ದೇಶಕ್ಕೆ ಮಾತ್ರ ಬಳಸುತ್ತವೆ ಮತ್ತು ಬೇರೆ ಯಾರೊಂದಿಗೂ ಹಂಚಿಕೊಳ್ಳುವುದಿಲ್ಲ.',
  'The provider will not ask the candidate for any extra fee without Jobsence’s knowledge; all fees and payments will be agreed in writing.' => 'Jobsence ನ ಅರಿವಿಲ್ಲದೆ ಒದಗಿಸುವವರು ಅಭ್ಯರ್ಥಿಯಿಂದ ಯಾವುದೇ ಹೆಚ್ಚುವರಿ ಶುಲ್ಕ ಕೇಳುವುದಿಲ್ಲ; ಎಲ್ಲಾ ಶುಲ್ಕಗಳು ಮತ್ತು ಪಾವತಿಗಳನ್ನು ಲಿಖಿತವಾಗಿ ಒಪ್ಪಿಕೊಳ್ಳಲಾಗುತ್ತದೆ.',
  'Both parties will behave respectfully and safely; any complaint can be sent to gm@jobsence.com.' => 'ಎರಡೂ ಪಕ್ಷಗಳು ಗೌರವಯುತವಾಗಿ ಮತ್ತು ಸುರಕ್ಷಿತವಾಗಿ ವರ್ತಿಸುತ್ತವೆ; ಯಾವುದೇ ದೂರನ್ನು gm@jobsence.com ಗೆ ಕಳುಹಿಸಬಹುದು.',
  'If the candidate rejects the provider after this agreement, the candidate’s registration closes and a new form fee is payable. If the provider ends the agreement, the candidate’s registration stays open.' => 'ಈ ಒಪ್ಪಂದದ ನಂತರ ಅಭ್ಯರ್ಥಿಯು ಒದಗಿಸುವವರನ್ನು ತಿರಸ್ಕರಿಸಿದರೆ, ಅಭ್ಯರ್ಥಿಯ ನೋಂದಣಿ ಮುಚ್ಚಲ್ಪಡುತ್ತದೆ ಮತ್ತು ಹೊಸ ಫಾರ್ಮ್ ಶುಲ್ಕ ಪಾವತಿಸಬೇಕಾಗುತ್ತದೆ. ಒದಗಿಸುವವರು ಒಪ್ಪಂದವನ್ನು ಕೊನೆಗೊಳಿಸಿದರೆ, ಅಭ್ಯರ್ಥಿಯ ನೋಂದಣಿ ತೆರೆದೇ ಇರುತ್ತದೆ.',
  'All fees are non-refundable. This is not a Government of India scheme.' => 'ಎಲ್ಲಾ ಶುಲ್ಕಗಳು ಮರುಪಾವತಿಸಲಾಗುವುದಿಲ್ಲ. ಇದು ಭಾರತ ಸರ್ಕಾರದ ಯೋಜನೆ ಅಲ್ಲ.',
  'The candidate and the provider sign with an OTP sent to their email; Jobsence countersigns automatically when both have signed. Signing time and IP are recorded.' => 'ಅಭ್ಯರ್ಥಿ ಮತ್ತು ಒದಗಿಸುವವರು ತಮ್ಮ ಇಮೇಲ್‌ಗೆ ಕಳುಹಿಸಲಾದ OTP ಮೂಲಕ ಸಹಿ ಮಾಡುತ್ತಾರೆ; ಇಬ್ಬರೂ ಸಹಿ ಮಾಡಿದಾಗ Jobsence ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಪ್ರತಿಸಹಿ ಮಾಡುತ್ತದೆ. ಸಹಿಯ ಸಮಯ ಮತ್ತು IP ದಾಖಲಿಸಲಾಗುತ್ತದೆ.',
  'Skill mentoring' => 'ಕೌಶಲ್ಯ ಮಾರ್ಗದರ್ಶನ',
  ' (incl. GST)' => ' (GST ಸೇರಿ)',
  'The mentor we requested is not available right now.' => 'ನಾವು ವಿನಂತಿಸಿದ ಮಾರ್ಗದರ್ಶಕರು ಸದ್ಯಕ್ಕೆ ಲಭ್ಯವಿಲ್ಲ.',
  'The mentor we requested did not reply in time.' => 'ನಾವು ವಿನಂತಿಸಿದ ಮಾರ್ಗದರ್ಶಕರು ಸಮಯಕ್ಕೆ ಉತ್ತರಿಸಲಿಲ್ಲ.',
  'We could not automatically match a mentor for your chosen skills yet.' => 'ನೀವು ಆಯ್ಕೆ ಮಾಡಿದ ಕೌಶಲ್ಯಗಳಿಗೆ ನಾವು ಇನ್ನೂ ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಮಾರ್ಗದರ್ಶಕರನ್ನು ಹೊಂದಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ.',
  'Your organisation is verified ✓' => 'ನಿಮ್ಮ ಸಂಸ್ಥೆ ಪರಿಶೀಲಿತವಾಗಿದೆ ✓',
  'You can now connect with social service people on Jobsence.' => 'ಈಗ ನೀವು Jobsence ನಲ್ಲಿ ಸಮಾಜ ಸೇವಕರೊಂದಿಗೆ ಸಂಪರ್ಕ ಸಾಧಿಸಬಹುದು.',
  'You have been added to the Jobsence Mentor Team ✓' => 'ನಿಮ್ಮನ್ನು Jobsence ಮಾರ್ಗದರ್ಶಕರ ತಂಡಕ್ಕೆ ಸೇರಿಸಲಾಗಿದೆ ✓',
  'When a candidate needs you, you will get an email to accept or decline.' => 'ಅಭ್ಯರ್ಥಿಗೆ ನಿಮ್ಮ ಅಗತ್ಯವಿದ್ದಾಗ, ಸ್ವೀಕರಿಸಲು ಅಥವಾ ನಿರಾಕರಿಸಲು ನಿಮಗೆ ಇಮೇಲ್ ಬರುತ್ತದೆ.',
  'You have been selected ✓' => 'ನೀವು ಆಯ್ಕೆಯಾಗಿದ್ದೀರಿ ✓',
  'We are now matching you with a mentor for your chosen skills.' => 'ನೀವು ಆಯ್ಕೆ ಮಾಡಿದ ಕೌಶಲ್ಯಗಳಿಗೆ ನಾವು ಈಗ ನಿಮ್ಮನ್ನು ಮಾರ್ಗದರ್ಶಕರೊಂದಿಗೆ ಹೊಂದಿಸುತ್ತಿದ್ದೇವೆ.',
  'This Email is already registered with another company' => 'ಈ ಇಮೇಲ್ ಈಗಾಗಲೇ ಇನ್ನೊಂದು ಕಂಪನಿಯೊಂದಿಗೆ ನೋಂದಾಯಿತವಾಗಿದೆ',
  'This Mobile number is already registered' => 'ಈ ಮೊಬೈಲ್ ಸಂಖ್ಯೆ ಈಗಾಗಲೇ ನೋಂದಾಯಿತವಾಗಿದೆ',
  'This GST number is already registered' => 'ಈ GST ಸಂಖ್ಯೆ ಈಗಾಗಲೇ ನೋಂದಾಯಿತವಾಗಿದೆ',
  'This field is required' => 'ಈ ಕ್ಷೇತ್ರ ಕಡ್ಡಾಯ',
  'Enter a valid email' => 'ಮಾನ್ಯವಾದ ಇಮೇಲ್ ನಮೂದಿಸಿ',
  'Email is required' => 'ಇಮೇಲ್ ಕಡ್ಡಾಯ',
  'Enter a valid 10-digit mobile number' => 'ಮಾನ್ಯವಾದ 10-ಅಂಕಿಯ ಮೊಬೈಲ್ ಸಂಖ್ಯೆ ನಮೂದಿಸಿ',
  'Mobile number is required' => 'ಮೊಬೈಲ್ ಸಂಖ್ಯೆ ಕಡ್ಡಾಯ',
  'Enter a valid 12-digit Aadhaar number' => 'ಮಾನ್ಯವಾದ 12-ಅಂಕಿಯ ಆಧಾರ್ ಸಂಖ್ಯೆ ನಮೂದಿಸಿ',
  'Aadhaar number is required' => 'ಆಧಾರ್ ಸಂಖ್ಯೆ ಕಡ್ಡಾಯ',
  'Enter a valid, not-expired date' => 'ಮಾನ್ಯವಾದ, ಅವಧಿ ಮುಗಿಯದ ದಿನಾಂಕ ನಮೂದಿಸಿ',
  'Enter a date between today and one year ahead' => 'ಇಂದಿನಿಂದ ಒಂದು ವರ್ಷದೊಳಗಿನ ದಿನಾಂಕ ನಮೂದಿಸಿ',
  'Enter a valid date of birth (minimum age 14)' => 'ಮಾನ್ಯವಾದ ಹುಟ್ಟಿದ ದಿನಾಂಕ ನಮೂದಿಸಿ (ಕನಿಷ್ಠ ವಯಸ್ಸು 14)',
  'Enter an amount between ₹' => 'ಈ ಮಿತಿಯೊಳಗಿನ ಮೊತ್ತ ನಮೂದಿಸಿ: ₹',
  'Enter a valid number' => 'ಮಾನ್ಯವಾದ ಸಂಖ್ಯೆ ನಮೂದಿಸಿ',
  'Enter a valid 6-digit PIN code' => 'ಮಾನ್ಯವಾದ 6-ಅಂಕಿಯ PIN ಕೋಡ್ ನಮೂದಿಸಿ',
  'Select State / UT' => 'ರಾಜ್ಯ / ಕೇಂದ್ರಾಡಳಿತ ಪ್ರದೇಶ ಆಯ್ಕೆಮಾಡಿ',
  'Select an option' => 'ಒಂದು ಆಯ್ಕೆಯನ್ನು ಆರಿಸಿ',
  'Select at least one option' => 'ಕನಿಷ್ಠ ಒಂದು ಆಯ್ಕೆಯನ್ನು ಆರಿಸಿ',
  'Select or type at least one' => 'ಕನಿಷ್ಠ ಒಂದನ್ನು ಆರಿಸಿ ಅಥವಾ ಟೈಪ್ ಮಾಡಿ',
  'Please take a live selfie' => 'ದಯವಿಟ್ಟು ಲೈವ್ ಸೆಲ್ಫಿ ತೆಗೆಯಿರಿ',
  'Please upload a photo' => 'ದಯವಿಟ್ಟು ಫೋಟೋ ಅಪ್‌ಲೋಡ್ ಮಾಡಿ',
  'Enter a valid video link (https://…)' => 'ಮಾನ್ಯವಾದ ವೀಡಿಯೊ ಲಿಂಕ್ ನಮೂದಿಸಿ (https://…)',
  'Upload a demo video or give a video link' => 'ಡೆಮೊ ವೀಡಿಯೊ ಅಪ್‌ಲೋಡ್ ಮಾಡಿ ಅಥವಾ ವೀಡಿಯೊ ಲಿಂಕ್ ನೀಡಿ',
  'Enter GST number or tick “I don’t have GST”' => 'GST ಸಂಖ್ಯೆ ನಮೂದಿಸಿ ಅಥವಾ “ನನ್ನ ಬಳಿ GST ಇಲ್ಲ” ಎಂದು ಟಿಕ್ ಮಾಡಿ',
  'Enter a valid 15-character GST number' => 'ಮಾನ್ಯವಾದ 15-ಅಕ್ಷರದ GST ಸಂಖ್ಯೆ ನಮೂದಿಸಿ',
  'Enter your passport number' => 'ನಿಮ್ಮ ಪಾಸ್‌ಪೋರ್ಟ್ ಸಂಖ್ಯೆ ನಮೂದಿಸಿ',
  'Enter a valid passport number (e.g. K1234567)' => 'ಮಾನ್ಯವಾದ ಪಾಸ್‌ಪೋರ್ಟ್ ಸಂಖ್ಯೆ ನಮೂದಿಸಿ (ಉದಾ. K1234567)',
  'Enter bank account number' => 'ಬ್ಯಾಂಕ್ ಖಾತೆ ಸಂಖ್ಯೆ ನಮೂದಿಸಿ',
  'Enter a valid account number / IBAN' => 'ಮಾನ್ಯವಾದ ಖಾತೆ ಸಂಖ್ಯೆ / IBAN ನಮೂದಿಸಿ',
  'Enter a valid account number (9–18 digits)' => 'ಮಾನ್ಯವಾದ ಖಾತೆ ಸಂಖ್ಯೆ ನಮೂದಿಸಿ (9–18 ಅಂಕಿಗಳು)',
  'Enter IFSC code' => 'IFSC ಕೋಡ್ ನಮೂದಿಸಿ',
  'Enter a valid SWIFT / BIC code' => 'ಮಾನ್ಯವಾದ SWIFT / BIC ಕೋಡ್ ನಮೂದಿಸಿ',
  'Enter a valid IFSC code (e.g. SBIN0001234)' => 'ಮಾನ್ಯವಾದ IFSC ಕೋಡ್ ನಮೂದಿಸಿ (ಉದಾ. SBIN0001234)',
  'Enter the expected stipend for a paid internship (₹8,000 – ₹5,00,000)' => 'ಪಾವತಿಸಿದ ಇಂಟರ್ನ್‌ಶಿಪ್‌ಗಾಗಿ ನಿರೀಕ್ಷಿತ ಸ್ಟೈಪೆಂಡ್ ನಮೂದಿಸಿ (₹8,000 – ₹5,00,000)',
  'Please accept all terms & conditions' => 'ದಯವಿಟ್ಟು ಎಲ್ಲಾ ನಿಯಮ ಮತ್ತು ಷರತ್ತುಗಳನ್ನು ಒಪ್ಪಿಕೊಳ್ಳಿ',
  'File could not be uploaded' => 'ಫೈಲ್ ಅಪ್‌ಲೋಡ್ ಮಾಡಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ',
  'File is larger than 5MB' => 'ಫೈಲ್ 5MB ಗಿಂತ ದೊಡ್ಡದಾಗಿದೆ',
  'Only PDF, DOC, DOCX, JPG or PNG files' => 'PDF, DOC, DOCX, JPG ಅಥವಾ PNG ಫೈಲ್‌ಗಳು ಮಾತ್ರ',
  'Only PDF, DOC or DOCX files' => 'PDF, DOC ಅಥವಾ DOCX ಫೈಲ್‌ಗಳು ಮಾತ್ರ',
  'Photo could not be uploaded' => 'ಫೋಟೋ ಅಪ್‌ಲೋಡ್ ಮಾಡಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ',
  'Photo is larger than 5MB' => 'ಫೋಟೋ 5MB ಗಿಂತ ದೊಡ್ಡದಾಗಿದೆ',
  'Only a clear JPG, PNG or WEBP photo (at least 100×100)' => 'ಸ್ಪಷ್ಟವಾದ JPG, PNG ಅಥವಾ WEBP ಫೋಟೋ ಮಾತ್ರ (ಕನಿಷ್ಠ 100×100)',
  'Video is larger than 200MB – please give a link instead' => 'ವೀಡಿಯೊ 200MB ಗಿಂತ ದೊಡ್ಡದಾಗಿದೆ – ದಯವಿಟ್ಟು ಬದಲಿಗೆ ಲಿಂಕ್ ನೀಡಿ',
  'Video could not be uploaded – retry or give a link' => 'ವೀಡಿಯೊ ಅಪ್‌ಲೋಡ್ ಮಾಡಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ – ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ ಅಥವಾ ಲಿಂಕ್ ನೀಡಿ',
  'Only video files (MP4, MOV, WEBM, MKV, 3GP)' => 'ವೀಡಿಯೊ ಫೈಲ್‌ಗಳು ಮಾತ್ರ (MP4, MOV, WEBM, MKV, 3GP)',
  'Apply on Jobsence – Skill Development, Internship, Full-time, Part-time and Work from Home registration. 3000+ categories, Hindi + English forms, one-time fee ₹155 incl. GST. भारत को कुशल बनाने की Jobsence पहल.' => 'Jobsence ನಲ್ಲಿ ಅರ್ಜಿ ಸಲ್ಲಿಸಿ – ಕೌಶಲ್ಯ ಅಭಿವೃದ್ಧಿ, ಇಂಟರ್ನ್‌ಶಿಪ್, ಪೂರ್ಣಕಾಲಿಕ, ಅರೆಕಾಲಿಕ ಮತ್ತು ಮನೆಯಿಂದ ಕೆಲಸ ನೋಂದಣಿ. 3000+ ವರ್ಗಗಳು, ಹಿಂದಿ + ಇಂಗ್ಲಿಷ್ ಫಾರ್ಮ್‌ಗಳು, ಒಂದು ಬಾರಿಯ ಶುಲ್ಕ ₹155 GST ಸೇರಿ. ಭಾರತವನ್ನು ಕೌಶಲ್ಯಪೂರ್ಣಗೊಳಿಸುವ Jobsence ಉಪಕ್ರಮ.',
  'Enter the correct answer to the security question' => 'ಭದ್ರತಾ ಪ್ರಶ್ನೆಗೆ ಸರಿಯಾದ ಉತ್ತರ ನಮೂದಿಸಿ',
  'Write your profession' => 'ನಿಮ್ಮ ವೃತ್ತಿಯನ್ನು ಬರೆಯಿರಿ',
  'Please verify your email with OTP before continuing' => 'ಮುಂದುವರಿಯುವ ಮೊದಲು ದಯವಿಟ್ಟು OTP ಮೂಲಕ ನಿಮ್ಮ ಇಮೇಲ್ ಪರಿಶೀಲಿಸಿ',
  'File could not be saved, please retry' => 'ಫೈಲ್ ಉಳಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ, ದಯವಿಟ್ಟು ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ',
  'Photo could not be saved, please retry' => 'ಫೋಟೋ ಉಳಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ, ದಯವಿಟ್ಟು ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ',
  'Server error, please try again' => 'ಸರ್ವರ್ ದೋಷ, ದಯವಿಟ್ಟು ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ',
  'employer' => 'ಉದ್ಯೋಗದಾತ',
  'candidate' => 'ಅಭ್ಯರ್ಥಿ',
  'The two PINs do not match' => 'ಎರಡು PIN ಗಳು ಹೊಂದಿಕೆಯಾಗುತ್ತಿಲ್ಲ',
  'changed' => 'ಬದಲಾಯಿಸಲಾಗಿದೆ',
  'removed' => 'ತೆಗೆದುಹಾಕಲಾಗಿದೆ',
  'Skill Development – All Skills' => 'ಕೌಶಲ್ಯ ಅಭಿವೃದ್ಧಿ – ಎಲ್ಲಾ ಕೌಶಲ್ಯಗಳು',
  'Looking for skill development in this?' => 'ಇದರಲ್ಲಿ ಕೌಶಲ್ಯ ಅಭಿವೃದ್ಧಿ ಬಯಸುತ್ತೀರಾ?',
  'Can you provide skill in this?' => 'ಇದರಲ್ಲಿ ನೀವು ಕೌಶಲ್ಯ ನೀಡಬಲ್ಲಿರಾ?',
  'mentors' => 'ಮಾರ್ಗದರ್ಶಕರು',
  'skills' => 'ಕೌಶಲ್ಯಗಳು',
  'Internships – All Domains' => 'ಇಂಟರ್ನ್‌ಶಿಪ್‌ಗಳು – ಎಲ್ಲಾ ಕ್ಷೇತ್ರಗಳು',
  'Looking for an internship in this?' => 'ಇದರಲ್ಲಿ ಇಂಟರ್ನ್‌ಶಿಪ್ ಬಯಸುತ್ತೀರಾ?',
  'Can you offer internships in this?' => 'ಇದರಲ್ಲಿ ನೀವು ಇಂಟರ್ನ್‌ಶಿಪ್ ನೀಡಬಲ್ಲಿರಾ?',
  'seekers' => 'ಬಯಸುವವರು',
  'providers' => 'ಒದಗಿಸುವವರು',
  'domains' => 'ಕ್ಷೇತ್ರಗಳು',
  'Jobs – All Categories' => 'ಉದ್ಯೋಗಗಳು – ಎಲ್ಲಾ ವರ್ಗಗಳು',
  'Looking for a job in this?' => 'ಇದರಲ್ಲಿ ಉದ್ಯೋಗ ಹುಡುಕುತ್ತಿದ್ದೀರಾ?',
  'Hiring for this?' => 'ಇದಕ್ಕಾಗಿ ನೇಮಕಾತಿ ಮಾಡುತ್ತಿದ್ದೀರಾ?',
  'job seekers' => 'ಉದ್ಯೋಗಾಕಾಂಕ್ಷಿಗಳು',
  'open jobs' => 'ಖಾಲಿ ಉದ್ಯೋಗಗಳು',
  'Near Me – All Services' => 'ನಿಯರ್ ಮಿ – ಎಲ್ಲಾ ಸೇವೆಗಳು',
  'Need this service near you?' => 'ನಿಮ್ಮ ಹತ್ತಿರ ಈ ಸೇವೆ ಬೇಕೇ?',
  'Do you provide this service?' => 'ನೀವು ಈ ಸೇವೆಯನ್ನು ಒದಗಿಸುತ್ತೀರಾ?',
  'verified providers' => 'ಪರಿಶೀಲಿತ ಒದಗಿಸುವವರು',
  'services' => 'ಸೇವೆಗಳು',
  'Apprenticeships' => 'ಅಪ್ರೆಂಟಿಸ್‌ಶಿಪ್‌ಗಳು',
  'Skill development' => 'ಕೌಶಲ್ಯ ಅಭಿವೃದ್ಧಿ',
  'This link is not valid or payment is pending' => 'ಈ ಲಿಂಕ್ ಮಾನ್ಯವಾಗಿಲ್ಲ ಅಥವಾ ಪಾವತಿ ಬಾಕಿ ಇದೆ',
  'Choose a plan' => 'ಯೋಜನೆಯನ್ನು ಆಯ್ಕೆಮಾಡಿ',
  'Could not start the plan, please try again' => 'ಯೋಜನೆಯನ್ನು ಪ್ರಾರಂಭಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ, ದಯವಿಟ್ಟು ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ',
  'Use “Full profile” in the list to open this profile' => 'ಈ ಪ್ರೊಫೈಲ್ ತೆರೆಯಲು ಪಟ್ಟಿಯಲ್ಲಿರುವ “ಪೂರ್ಣ ಪ್ರೊಫೈಲ್” ಬಳಸಿ',
  'First open your dashboard from the link in your email / receipt' => 'ಮೊದಲು ನಿಮ್ಮ ಇಮೇಲ್ / ರಸೀದಿಯಲ್ಲಿರುವ ಲಿಂಕ್‌ನಿಂದ ನಿಮ್ಮ ಡ್ಯಾಶ್‌ಬೋರ್ಡ್ ತೆರೆಯಿರಿ',
  'OTP sent to your email (valid for 10 minutes)' => 'OTP ಅನ್ನು ನಿಮ್ಮ ಇಮೇಲ್‌ಗೆ ಕಳುಹಿಸಲಾಗಿದೆ (10 ನಿಮಿಷ ಮಾನ್ಯ)',
  'Accept the agreement terms before signing' => 'ಸಹಿ ಮಾಡುವ ಮೊದಲು ಒಪ್ಪಂದದ ನಿಯಮಗಳನ್ನು ಒಪ್ಪಿಕೊಳ್ಳಿ',
  'Request declined' => 'ವಿನಂತಿ ನಿರಾಕರಿಸಲಾಗಿದೆ',
  'Tick the box to confirm' => 'ದೃಢೀಕರಿಸಲು ಬಾಕ್ಸ್ ಟಿಕ್ ಮಾಡಿ',
  'Agreement ended. Your registration is closed – fill a new form for a new mentor / internship.' => 'ಒಪ್ಪಂದ ಕೊನೆಗೊಂಡಿದೆ. ನಿಮ್ಮ ನೋಂದಣಿ ಮುಚ್ಚಲಾಗಿದೆ – ಹೊಸ ಮಾರ್ಗದರ್ಶಕರು / ಇಂಟರ್ನ್‌ಶಿಪ್‌ಗಾಗಿ ಹೊಸ ಫಾರ್ಮ್ ಭರ್ತಿ ಮಾಡಿ.',
  'Agreement ended. The candidate’s registration stays open.' => 'ಒಪ್ಪಂದ ಕೊನೆಗೊಂಡಿದೆ. ಅಭ್ಯರ್ಥಿಯ ನೋಂದಣಿ ತೆರೆದೇ ಇರುತ್ತದೆ.',
  'An active Near Me pass is needed to rate' => 'ರೇಟ್ ಮಾಡಲು ಸಕ್ರಿಯ ನಿಯರ್ ಮಿ ಪಾಸ್ ಅಗತ್ಯವಿದೆ',
  'Choose 1 to 5 stars' => '1 ರಿಂದ 5 ಸ್ಟಾರ್‌ಗಳನ್ನು ಆಯ್ಕೆಮಾಡಿ',
  'Thank you! Your rating has been saved.' => 'ಧನ್ಯವಾದಗಳು! ನಿಮ್ಮ ರೇಟಿಂಗ್ ಉಳಿಸಲಾಗಿದೆ.',
  'No. This is Jobsence’s own initiative to make India skilled. It is NOT a Government of India scheme or programme.' => 'ಇಲ್ಲ. ಇದು ಭಾರತವನ್ನು ಕೌಶಲ್ಯಪೂರ್ಣಗೊಳಿಸಲು Jobsence ನ ಸ್ವಂತ ಉಪಕ್ರಮ. ಇದು ಭಾರತ ಸರ್ಕಾರದ ಯೋಜನೆ ಅಥವಾ ಕಾರ್ಯಕ್ರಮ ಅಲ್ಲ.',
  'What is the registration fee? Is it refundable?' => 'ನೋಂದಣಿ ಶುಲ್ಕ ಎಷ್ಟು? ಅದು ಮರುಪಾವತಿಯಾಗುತ್ತದೆಯೇ?',
  'What is the course fee after selection?' => 'ಆಯ್ಕೆಯ ನಂತರ ಕೋರ್ಸ್ ಶುಲ್ಕ ಎಷ್ಟು?',
  'Is a job guaranteed?' => 'ಉದ್ಯೋಗದ ಖಾತರಿ ಇದೆಯೇ?',
  'No. Jobsence does not guarantee any job or placement. We try to push your resume to interested companies, make you job-ready, or guide you towards self-employment.' => 'ಇಲ್ಲ. Jobsence ಯಾವುದೇ ಉದ್ಯೋಗ ಅಥವಾ ನಿಯೋಜನೆಯ ಖಾತರಿ ನೀಡುವುದಿಲ್ಲ. ನಾವು ನಿಮ್ಮ ರೆಸ್ಯೂಮ್ ಅನ್ನು ಆಸಕ್ತ ಕಂಪನಿಗಳಿಗೆ ತಲುಪಿಸಲು, ನಿಮ್ಮನ್ನು ಉದ್ಯೋಗಕ್ಕೆ ಸಿದ್ಧಗೊಳಿಸಲು ಅಥವಾ ಸ್ವಯಂ ಉದ್ಯೋಗದ ಕಡೆಗೆ ಮಾರ್ಗದರ್ಶನ ನೀಡಲು ಪ್ರಯತ್ನಿಸುತ್ತೇವೆ.',
  'When and how will classes happen?' => 'ತರಗತಿಗಳು ಯಾವಾಗ ಮತ್ತು ಹೇಗೆ ನಡೆಯುತ್ತವೆ?',
  'Classes are 2 hours per day, 3 days a week, including practical training. Online video classes are available Pan-India; offline classes only in Delhi-NCR.' => 'ತರಗತಿಗಳು ದಿನಕ್ಕೆ 2 ಗಂಟೆ, ವಾರಕ್ಕೆ 3 ದಿನ, ಪ್ರಾಯೋಗಿಕ ತರಬೇತಿ ಸೇರಿ ಇರುತ್ತವೆ. ಆನ್‌ಲೈನ್ ವೀಡಿಯೊ ತರಗತಿಗಳು ಭಾರತದಾದ್ಯಂತ ಲಭ್ಯ; ಆಫ್‌ಲೈನ್ ತರಗತಿಗಳು ದೆಹಲಿ-NCR ನಲ್ಲಿ ಮಾತ್ರ.',
  'How long after submitting the form?' => 'ಫಾರ್ಮ್ ಸಲ್ಲಿಸಿದ ಎಷ್ಟು ಸಮಯದ ನಂತರ?',
  'Scrutiny of forms and resumes takes a minimum of 3 to 6 months.' => 'ಫಾರ್ಮ್‌ಗಳು ಮತ್ತು ರೆಸ್ಯೂಮ್‌ಗಳ ಪರಿಶೀಲನೆಗೆ ಕನಿಷ್ಠ 3 ರಿಂದ 6 ತಿಂಗಳು ಬೇಕಾಗುತ್ತದೆ.',
  'Who can apply?' => 'ಯಾರು ಅರ್ಜಿ ಸಲ್ಲಿಸಬಹುದು?',
  'Anyone unemployed – uneducated, 10th/12th pass, ITI, graduates, engineers, doctors, drivers, homemakers – from any village, district, city or capital in India.' => 'ನಿರುದ್ಯೋಗಿಯಾಗಿರುವ ಯಾರಾದರೂ – ಅವಿದ್ಯಾವಂತರು, 10ನೇ/12ನೇ ತರಗತಿ ಉತ್ತೀರ್ಣರು, ITI, ಪದವೀಧರರು, ಇಂಜಿನಿಯರ್‌ಗಳು, ವೈದ್ಯರು, ಚಾಲಕರು, ಗೃಹಿಣಿಯರು – ಭಾರತದ ಯಾವುದೇ ಹಳ್ಳಿ, ಜಿಲ್ಲೆ, ನಗರ ಅಥವಾ ರಾಜಧಾನಿಯಿಂದ.',
  'In which language is training given?' => 'ತರಬೇತಿಯನ್ನು ಯಾವ ಭಾಷೆಯಲ್ಲಿ ನೀಡಲಾಗುತ್ತದೆ?',
  'In Hindi, English or a local/regional language, depending on mentor availability.' => 'ಮಾರ್ಗದರ್ಶಕರ ಲಭ್ಯತೆಯನ್ನು ಅವಲಂಬಿಸಿ ಹಿಂದಿ, ಇಂಗ್ಲಿಷ್ ಅಥವಾ ಸ್ಥಳೀಯ/ಪ್ರಾದೇಶಿಕ ಭಾಷೆಯಲ್ಲಿ.',
  'Who conducts the training?' => 'ತರಬೇತಿಯನ್ನು ಯಾರು ನಡೆಸುತ್ತಾರೆ?',
  'Training is conducted through third-party skill development partners and registered mentors.' => 'ತರಬೇತಿಯನ್ನು ಮೂರನೇ ವ್ಯಕ್ತಿ ಕೌಶಲ್ಯ ಅಭಿವೃದ್ಧಿ ಪಾಲುದಾರರು ಮತ್ತು ನೋಂದಾಯಿತ ಮಾರ್ಗದರ್ಶಕರ ಮೂಲಕ ನಡೆಸಲಾಗುತ್ತದೆ.',
  'Can I join as a mentor / trainer?' => 'ನಾನು ಮಾರ್ಗದರ್ಶಕರು / ತರಬೇತುದಾರರಾಗಿ ಸೇರಬಹುದೇ?',
);
